/* ============================================================
   Utils — math, procedural textures and small scene helpers
   ============================================================ */
import * as THREE from 'three';

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const smoothstep = (a, b, v) => { const t = clamp((v - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const damp = (current, target, lambda, dt) => lerp(current, target, 1 - Math.exp(-lambda * dt));
export const angleLerp = (a, b, t) => {
  let d = ((b - a + Math.PI) % TAU) - Math.PI;
  if (d < -Math.PI) d += TAU;
  return a + d * t;
};
export const formatTime = (sec) => {
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${String(s).padStart(2, '0')}`;
};

/* ---------------- deterministic value noise ---------------- */
function hash2(x, y, seed) {
  let h = Math.sin(x * 127.1 + y * 311.7 + seed * 74.7) * 43758.5453123;
  return h - Math.floor(h);
}
function smooth(t) { return t * t * (3 - 2 * t); }
export function valueNoise(x, y, seed = 1) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = smooth(xf), v = smooth(yf);
  const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed);
  const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}
export function fbm(x, y, octaves = 4, seed = 1, lacunarity = 2.03, gain = 0.5) {
  let amp = 0.5, freq = 1, sum = 0, norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(x * freq, y * freq, seed + i * 13.7);
    norm += amp; amp *= gain; freq *= lacunarity;
  }
  return sum / norm;
}

/* ---------------- canvas texture helpers ---------------- */
function makeCanvas(size) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}
function toTexture(canvas, { srgb = true, repeat = 1, aniso = 8 } = {}) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.anisotropy = aniso;
  tex.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  tex.needsUpdate = true;
  return tex;
}

/** A mottled colour texture built from FBM, with flecks and painterly strokes. */
export function makeMottleTexture(size, opts = {}) {
  const {
    base = [88, 128, 62], variance = 30, scale = 5, seed = 1, strokes = 0,
    strokeColor = [140, 170, 90], darkSpots = 0, repeat = 1
  } = opts;
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const n = fbm(x / size * scale, y / size * scale, 5, seed);
      const n2 = fbm(x / size * scale * 4 + 17, y / size * scale * 4 - 9, 3, seed + 8);
      const v = (n - 0.5) * 2 * variance + (n2 - 0.5) * variance * 0.45;
      const i = (y * size + x) * 4;
      img.data[i] = clamp(base[0] + v, 0, 255);
      img.data[i + 1] = clamp(base[1] + v * 0.9, 0, 255);
      img.data[i + 2] = clamp(base[2] + v * 0.7, 0, 255);
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);

  // painterly flecks
  for (let i = 0; i < strokes; i++) {
    const x = Math.random() * size, y = Math.random() * size;
    const len = rand(2, 7);
    const ang = rand(-0.9, 0.9) + Math.PI / 2;
    ctx.strokeStyle = `rgba(${strokeColor[0]},${strokeColor[1]},${strokeColor[2]},${rand(0.1, 0.35)})`;
    ctx.lineWidth = rand(0.6, 1.8);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(ang) * len, y + Math.sin(ang) * len);
    ctx.stroke();
  }
  for (let i = 0; i < darkSpots; i++) {
    const x = Math.random() * size, y = Math.random() * size, r = rand(1, size * 0.035);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(15,30,15,${rand(0.08, 0.22)})`);
    g.addColorStop(1, 'rgba(15,30,15,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  return toTexture(canvas, { repeat });
}

/** Height-derived tangent-space normal map. */
export function makeNormalTexture(size = 256, scale = 8, strength = 2.2, seed = 3, repeat = 1) {
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  const h = (x, y) => fbm((x / size) * scale, (y / size) * scale, 5, seed) +
    0.25 * fbm((x / size) * scale * 3, (y / size) * scale * 3, 2, seed + 4);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const xm = (x - 1 + size) % size, xp = (x + 1) % size;
      const ym = (y - 1 + size) % size, yp = (y + 1) % size;
      const dx = (h(xp, y) - h(xm, y)) * strength;
      const dy = (h(x, yp) - h(x, ym)) * strength;
      const nx = -dx, ny = -dy, nz = 1;
      const len = Math.hypot(nx, ny, nz);
      const i = (y * size + x) * 4;
      img.data[i] = ((nx / len) * 0.5 + 0.5) * 255;
      img.data[i + 1] = ((ny / len) * 0.5 + 0.5) * 255;
      img.data[i + 2] = ((nz / len) * 0.5 + 0.5) * 255;
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return toTexture(canvas, { srgb: false, repeat });
}

/** Roughness / AO detail map (grayscale). */
export function makeGrainTexture(size = 256, opts = {}) {
  const { base = 180, variance = 50, scale = 14, seed = 6, repeat = 1 } = opts;
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const n = fbm((x / size) * scale, (y / size) * scale, 3, seed);
      const v = clamp(base + (n - 0.5) * variance, 0, 255);
      const i = (y * size + x) * 4;
      img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return toTexture(canvas, { srgb: false, repeat });
}

/* ---------------- sprites / gradients ---------------- */
export function makeRadialTexture(size = 128, inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)', sharpness = 0.35) {
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, size * 0.02, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(sharpness, inner);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(canvas);
  t.colorSpace = THREE.SRGBColorSpace;
  t.needsUpdate = true;
  return t;
}

export function makeCloudTexture(size = 256, seed = 2) {
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  const img = ctx.createImageData(size, size);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const nx = x / size, ny = y / size;
      const dx = nx - 0.5, dy = ny - 0.5;
      const falloff = clamp(1 - Math.hypot(dx, dy) * 2.15, 0, 1);
      const n = fbm(nx * 4.2, ny * 4.2, 5, seed);
      const a = clamp((n * 0.75 + 0.25) * Math.pow(falloff, 1.5), 0, 1);
      const i = (y * size + x) * 4;
      img.data[i] = 255; img.data[i + 1] = 255; img.data[i + 2] = 255;
      img.data[i + 3] = a * 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(canvas);
  t.colorSpace = THREE.SRGBColorSpace;
  t.needsUpdate = true;
  return t;
}

export function makeShaftTexture(size = 128) {
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, size);
  g.addColorStop(0, 'rgba(255,240,200,0.85)');
  g.addColorStop(0.35, 'rgba(255,232,180,0.32)');
  g.addColorStop(1, 'rgba(255,225,170,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  // soften the sides
  const side = ctx.createLinearGradient(0, 0, size, 0);
  side.addColorStop(0, 'rgba(0,0,0,1)');
  side.addColorStop(0.32, 'rgba(0,0,0,0)');
  side.addColorStop(0.68, 'rgba(0,0,0,0)');
  side.addColorStop(1, 'rgba(0,0,0,1)');
  ctx.globalCompositeOperation = 'destination-out';
  ctx.fillStyle = side;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(canvas);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

/* ---------------- material / mesh helpers ---------------- */
export function setShadows(obj, cast = true, receive = true) {
  obj.traverse((child) => {
    if (child.isMesh) {
      child.castShadow = cast;
      child.receiveShadow = receive;
    }
  });
  return obj;
}

export function makeGlowSprite({ color = 0x9ffff4, size = 1, opacity = 1, texture = null, blending = THREE.AdditiveBlending } = {}) {
  const mat = new THREE.SpriteMaterial({
    map: texture,
    color,
    transparent: true,
    opacity,
    blending,
    depthWrite: false,
    toneMapped: false,
  });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(size, size, 1);
  return sprite;
}

/** Simple billboard-friendly ribbon used for trails and slashes. */
export function createRibbon(points = 24, width = 0.5, color = 0x8ff7ec) {
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(points * 2 * 3);
  const alpha = new Float32Array(points * 2);
  const idx = [];
  for (let i = 0; i < points - 1; i++) {
    const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
    idx.push(a, b, c, b, d, c);
  }
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1));
  geo.setIndex(idx);
  const mat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: { uColor: { value: new THREE.Color(color) } },
    vertexShader: `
      attribute float aAlpha; varying float vA;
      void main(){ vA = aAlpha; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
    `,
    fragmentShader: `
      uniform vec3 uColor; varying float vA;
      void main(){ gl_FragColor = vec4(uColor, vA); }
    `,
  });
  return { mesh: new THREE.Mesh(geo, mat), width, points };
}

export function disposeObject(root) {
  root.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach((m) => {
        for (const key in m) {
          const val = m[key];
          if (val && val.isTexture) val.dispose();
        }
        m.dispose();
      });
    }
  });
}

export function makeCapsuleRadius(radius, height) {
  return new THREE.CapsuleGeometry(radius, height, 6, 12);
}

/** Simple AABB overlap test used by physics and abilities. */
export function overlapsAABB(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y &&
         a.z < b.z + b.d && a.z + a.d > b.z;
}

export function pointInBox(p, box, pad = 0) {
  return p.x > box.min.x - pad && p.x < box.max.x + pad &&
         p.y > box.min.y - pad && p.y < box.max.y + pad &&
         p.z > box.min.z - pad && p.z < box.max.z + pad;
}

/* ============================================================
   Input — keyboard, mouse (pointer lock), gamepad, multi-touch
   Edge presses are buffered until consumed by the fixed-step sim.
   ============================================================ */
import { clamp } from './Utils.js';

const KEY_MAP = {
  KeyW: 'forward', ArrowUp: 'forward',
  KeyS: 'back', ArrowDown: 'back',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  Space: 'jump',
  ShiftLeft: 'dash', ShiftRight: 'dash',
  KeyJ: 'attack', KeyK: 'attack',
  KeyQ: 'lock',
  KeyE: 'interact',
  Escape: 'pause',
  KeyM: 'mute',
};

const PAD_DEADZONE = 0.16;

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.lookX = 0;
    this.lookY = 0;
    this.zoomDelta = 0;
    this.lookSensitivity = 1;
    this.invertY = false;
    this.enabled = true;

    this.touch = {
      moveX: 0, moveY: 0,
      actions: new Set(),
    };
    this.touchActive = false;

    this.pad = {
      index: null,
      connected: false,
      buttons: new Array(20).fill(false),
      prev: new Array(20).fill(false),
      axes: [0, 0, 0, 0],
    };
    this.activeDevice = 'keyboard';
    this.onGamepad = null;

    this._mouse = { down: false, id: -1, lastX: 0, lastY: 0, startX: 0, startY: 0, dragged: false, locked: false };

    this._bindKeyboard();
    this._bindMouse();
    this._bindTouch();

    // expose for querying / tuning from the console
    window.__aetherInput = this;
  }

  get isTouchDevice() {
    return window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
  }

  /* ---------------- keyboard ---------------- */
  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (e.code === 'F5' || e.code === 'F12') return;
      const action = KEY_MAP[e.code];
      if (action) e.preventDefault();
      if (!action) return;
      if (!e.repeat) {
        this.pressed.add(action);
        if (action === 'mute' || action === 'pause') this.pressed.add(action);
      }
      this.keys.add(e.code);
      this.activeDevice = 'keyboard';
    }, { passive: false });

    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
    });

    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touch.actions.clear();
    });
  }

  /* ---------------- mouse ---------------- */
  _bindMouse() {
    const canvas = this.canvas;

    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    canvas.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'touch') return;
      this.activeDevice = e.pointerType === 'pen' ? 'pen' : 'mouse';
      if (e.button === 1) { e.preventDefault(); this.pressed.add('lock'); return; }
      if (e.button === 2) { e.preventDefault(); this.pressed.add('lock'); return; }
      if (e.button !== 0) return;
      this._mouse.down = true;
      this._mouse.id = e.pointerId;
      this._mouse.lastX = e.clientX;
      this._mouse.lastY = e.clientY;
      this._mouse.startX = e.clientX;
      this._mouse.startY = e.clientY;
      this._mouse.dragged = false;
      try { canvas.setPointerCapture(e.pointerId); } catch { /* ignore */ }

      if (document.pointerLockElement === canvas) {
        this.pressed.add('attack');
      }
    });

    window.addEventListener('pointermove', (e) => {
      if (e.pointerType === 'touch') return;
      if (document.pointerLockElement === canvas) {
        this._addLook(e.movementX, e.movementY);
        return;
      }
      if (!this._mouse.down || e.pointerId !== this._mouse.id) return;
      const dx = e.clientX - this._mouse.lastX;
      const dy = e.clientY - this._mouse.lastY;
      this._mouse.lastX = e.clientX;
      this._mouse.lastY = e.clientY;
      if (Math.hypot(e.clientX - this._mouse.startX, e.clientY - this._mouse.startY) > 5) this._mouse.dragged = true;
      if (this._mouse.dragged) this._addLook(dx, dy);
      this.activeDevice = 'mouse';
    });

    const endMouse = (e) => {
      if (e.pointerType === 'touch') return;
      if (!this._mouse.down) return;
      const wasDrag = this._mouse.dragged;
      this._mouse.down = false;
      this._mouse.dragged = false;
      if (!wasDrag && e.button === 0 && document.pointerLockElement !== canvas) {
        // A short click: capture the mouse for fluid camera control.
        this.pressed.add('attack');
        this.requestLock();
      }
    };
    window.addEventListener('pointerup', endMouse);
    window.addEventListener('pointercancel', () => { this._mouse.down = false; this._mouse.dragged = false; });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.zoomDelta += clamp(e.deltaY * 0.0025, -1.5, 1.5);
    }, { passive: false });

    document.addEventListener('pointerlockchange', () => {
      this._mouse.locked = document.pointerLockElement === canvas;
    });
  }

  requestLock() {
    if (this.isTouchDevice) return;
    const el = this.canvas;
    if (document.pointerLockElement === el) return;
    if (el.requestPointerLock) {
      const p = el.requestPointerLock();
      if (p && p.catch) p.catch(() => {});
    }
  }

  exitLock() {
    if (document.pointerLockElement) document.exitPointerLock();
  }

  _addLook(dx, dy) {
    this.lookX += dx * 0.0026 * this.lookSensitivity;
    this.lookY += dy * 0.0026 * this.lookSensitivity * (this.invertY ? -1 : 1);
  }

  /* ---------------- gamepad ---------------- */
  _pollGamepad() {
    if (!navigator.getGamepads) return;
    const pads = navigator.getGamepads();
    let pad = null;
    for (const p of pads) { if (p && p.connected) { pad = p; break; } }
    if (!pad) {
      if (this.pad.connected) this.pad.connected = false;
      return;
    }
    if (!this.pad.connected) {
      this.pad.connected = true;
      this.pad.index = pad.index;
      this.onGamepad?.(pad);
    }

    const btns = pad.buttons.map(b => b.pressed || b.value > 0.35);
    // Standard mapping: 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 8 Back, 9 Start
    const mappings = [
      [0, 'jump'], [2, 'attack'], [5, 'dash'], [4, 'lock'],
      [9, 'pause'], [8, 'mute'], [1, 'dash'],
    ];
    for (const [idx, action] of mappings) {
      if (btns[idx] && !this.pad.prev[idx]) {
        this.pressed.add(action);
        this.activeDevice = 'gamepad';
      }
      if (btns[idx]) this.pad.buttons[idx] = true;
      else this.pad.buttons[idx] = false;
    }

    const ax = pad.axes;
    const dead = (v) => Math.abs(v) < PAD_DEADZONE ? 0 : (v - Math.sign(v) * PAD_DEADZONE) / (1 - PAD_DEADZONE);
    this.pad.axes = [dead(ax[0] || 0), dead(ax[1] || 0), dead(ax[2] || 0), dead(ax[3] || 0)];
    if (Math.abs(this.pad.axes[0]) + Math.abs(this.pad.axes[1]) + Math.abs(this.pad.axes[2]) + Math.abs(this.pad.axes[3]) > 0.02) {
      this.activeDevice = 'gamepad';
    }
    this.pad.prev = btns;
  }

  /* ---------------- touch ---------------- */
  _bindTouch() {
    if (this.isTouchDevice) document.body.classList.add('touch-mode');

    const zone = document.getElementById('stick-zone');
    const knob = document.getElementById('stick-knob');
    const look = document.getElementById('touch-look');
    if (!zone || !knob) return;

    let stickId = -1;
    let lookId = -1;
    let lookLastX = 0, lookLastY = 0;
    let centerX = 0, centerY = 0;
    const maxDist = 46;

    const setKnob = (x, y) => {
      knob.style.transform = `translate(${x}px, ${y}px)`;
    };

    zone.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      this.touchActive = true;
      this.activeDevice = 'touch';
      if (stickId !== -1) return;
      stickId = e.pointerId;
      const rect = zone.getBoundingClientRect();
      centerX = rect.left + rect.width / 2;
      centerY = rect.top + rect.height / 2;
      zone.setPointerCapture(e.pointerId);
      this._updateStick(e.clientX, e.clientY, centerX, centerY, maxDist, setKnob);
    });

    zone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== stickId) return;
      e.preventDefault();
      this._updateStick(e.clientX, e.clientY, centerX, centerY, maxDist, setKnob);
    });

    const endStick = (e) => {
      if (e.pointerId !== stickId) return;
      stickId = -1;
      this.touch.moveX = 0;
      this.touch.moveY = 0;
      setKnob(0, 0);
    };
    zone.addEventListener('pointerup', endStick);
    zone.addEventListener('pointercancel', endStick);

    if (look) {
      look.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.touchActive = true;
        this.activeDevice = 'touch';
        if (lookId !== -1) return;
        lookId = e.pointerId;
        lookLastX = e.clientX;
        lookLastY = e.clientY;
        look.setPointerCapture(e.pointerId);
      });
      look.addEventListener('pointermove', (e) => {
        if (e.pointerId !== lookId) return;
        const dx = e.clientX - lookLastX;
        const dy = e.clientY - lookLastY;
        lookLastX = e.clientX;
        lookLastY = e.clientY;
        this._addLook(dx * 1.5, dy * 1.5);
      });
      const endLook = (e) => { if (e.pointerId === lookId) lookId = -1; };
      look.addEventListener('pointerup', endLook);
      look.addEventListener('pointercancel', endLook);
    }

    // Action buttons: independent pointers => true multi-touch.
    document.querySelectorAll('[data-touch]').forEach((btn) => {
      const action = btn.dataset.touch;
      const down = (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.touchActive = true;
        this.activeDevice = 'touch';
        if (!this.touch.actions.has(action)) this.pressed.add(action);
        this.touch.actions.add(action);
        btn.classList.add('active');
        try { btn.setPointerCapture(e.pointerId); } catch { /* ignore */ }
      };
      const up = (e) => {
        e.preventDefault();
        this.touch.actions.delete(action);
        btn.classList.remove('active');
      };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('lostpointercapture', up);
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
    });

    // Prevent double-tap zoom / browser gestures on the play surface.
    document.addEventListener('touchmove', (e) => {
      if (e.target.closest && e.target.closest('#touch')) e.preventDefault();
    }, { passive: false });
  }

  _updateStick(clientX, clientY, cx, cy, maxDist, setKnob) {
    let dx = clientX - cx;
    let dy = clientY - cy;
    const len = Math.hypot(dx, dy);
    if (len > maxDist) { dx = (dx / len) * maxDist; dy = (dy / len) * maxDist; }
    setKnob(dx, dy);
    this.touch.moveX = dx / maxDist;
    this.touch.moveY = dy / maxDist;
  }

  /* ---------------- public API ---------------- */
  update(dt) {
    this._pollGamepad();
    // Gamepad camera: graceful continuous rotation.
    if (this.pad.connected) {
      const gx = this.pad.axes[2];
      const gy = this.pad.axes[3];
      if (Math.abs(gx) > 0.01 || Math.abs(gy) > 0.01) {
        this.lookX += gx * 2.2 * this.lookSensitivity * dt;
        this.lookY += gy * 2.0 * this.lookSensitivity * (this.invertY ? -1 : 1) * dt;
      }
    }
  }

  isDown(action) {
    if (!this.enabled) return false;
    if (this.touch.actions.has(action)) return true;
    for (const code in KEY_MAP) {
      if (KEY_MAP[code] === action && this.keys.has(code)) return true;
    }
    if (this.pad.connected) {
      if (action === 'jump' && (this.pad.buttons[0] || this.pad.buttons[3])) return true;
      if (action === 'attack' && this.pad.buttons[2]) return true;
      if (action === 'dash' && (this.pad.buttons[5] || this.pad.buttons[1])) return true;
      if (action === 'lock' && this.pad.buttons[4]) return true;
    }
    return false;
  }

  consumePressed(action) {
    if (this.pressed.has(action)) {
      this.pressed.delete(action);
      return true;
    }
    return false;
  }

  getMove() {
    let x = 0, y = 0;
    if (this.enabled) {
      if (this.isDown('right')) x += 1;
      if (this.isDown('left')) x -= 1;
      if (this.isDown('forward')) y += 1;
      if (this.isDown('back')) y -= 1;
      x += this.touch.moveX;
      y += -this.touch.moveY;
      if (this.pad.connected) {
        x += this.pad.axes[0];
        y += -this.pad.axes[1];
      }
    }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    return { x, y, len: Math.min(1, len) };
  }

  consumeLook() {
    const out = { x: this.lookX, y: this.lookY };
    this.lookX = 0; this.lookY = 0;
    return out;
  }

  consumeZoom() {
    const z = this.zoomDelta;
    this.zoomDelta = 0;
    return z;
  }

  getUsingGamepad() {
    return this.pad.connected && this.activeDevice === 'gamepad';
  }
}

/* ============================================================
   Audio — fully procedural WebAudio SFX, ambience and generative
   music. No external samples, so the game boots with zero assets.
   ============================================================ */
import { rand, pick } from './Utils.js';

const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12);

const ZONE_MUSIC = {
  meadow: { root: 57, chords: [[0, 4, 7, 11], [-3, 2, 5, 9], [5, 9, 12, 16], [3, 7, 10, 14]], tempo: 1.65, arp: [0, 7, 12, 16, 19, 16, 12, 7] },
  ruins: { root: 52, chords: [[0, 3, 7, 10], [-2, 3, 5, 10], [5, 8, 12, 15], [3, 7, 10, 14]], tempo: 1.95, arp: [0, 7, 10, 12, 15, 12, 10, 7] },
  crystal: { root: 55, chords: [[0, 3, 7, 14], [-4, 0, 5, 12], [3, 7, 10, 15], [-2, 3, 7, 10]], tempo: 2.25, arp: [0, 12, 7, 15, 19, 15, 7, 12] },
  sky: { root: 60, chords: [[0, 4, 7, 12], [-5, 0, 4, 9], [2, 5, 9, 12], [0, 4, 7, 11]], tempo: 1.55, arp: [0, 7, 12, 16, 19, 24, 19, 16] },
};

export class AudioManager {
  constructor(settings = {}) {
    this.ctx = null;
    this.ready = false;
    this.masterVolume = settings.master ?? 0.8;
    this.musicVolume = settings.music ?? 0.55;
    this.sfxVolume = settings.sfx ?? 0.9;
    this.muted = false;
    this.zone = 'meadow';
    this.musicTimer = null;
    this.musicStart = 0;
    this.nextNoteTime = 0;
    this.step = 0;
    this.ambientNodes = [];
    this.lastStep = 0;
    this._musicGain = null;
    this._sfxGain = null;
  }

  /** Must be called from a user gesture. Safe to call repeatedly. */
  async init() {
    if (this.ready) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    if (this.ctx.state === 'suspended') {
      try { await this.ctx.resume(); } catch { /* will retry on gesture */ }
    }

    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.masterVolume;
    this.master.connect(this.ctx.destination);

    this.compressor = this.ctx.createDynamicsCompressor();
    this.compressor.threshold.value = -14;
    this.compressor.knee.value = 18;
    this.compressor.ratio.value = 4;
    this.compressor.attack.value = 0.003;
    this.compressor.release.value = 0.22;
    this.compressor.connect(this.master);

    // procedural cathedral-ish reverb
    this.reverb = this.ctx.createConvolver();
    this.reverb.buffer = this._makeImpulse(2.6, 2.1);
    this.reverbGain = this.ctx.createGain();
    this.reverbGain.gain.value = 0.22;
    this.reverb.connect(this.reverbGain);
    this.reverbGain.connect(this.compressor);

    this._sfxGain = this.ctx.createGain();
    this._sfxGain.gain.value = this.sfxVolume;
    this._sfxGain.connect(this.compressor);
    this._sfxGain.connect(this.reverb);

    this._musicGain = this.ctx.createGain();
    this._musicGain.gain.value = 0;
    this._musicGain.connect(this.compressor);
    this._musicGain.connect(this.reverb);

    this.noiseBuffer = this._makeNoise(2.0);
    this.ready = true;

    this.startAmbience();
    this.startMusic('meadow');
    // gentle fade-in
    const t = this.ctx.currentTime;
    this._musicGain.gain.cancelScheduledValues(t);
    this._musicGain.gain.setValueAtTime(0.0001, t);
    this._musicGain.gain.exponentialRampToValueAtTime(Math.max(0.0002, this.musicVolume * 0.25), t + 3.5);
  }

  _makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  _makeImpulse(duration, decay) {
    const rate = this.ctx.sampleRate;
    const len = Math.floor(rate * duration);
    const buffer = this.ctx.createBuffer(2, len, rate);
    for (let ch = 0; ch < 2; ch++) {
      const data = buffer.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / len;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, decay) * (1 + 0.3 * Math.sin(i * 0.003));
      }
    }
    return buffer;
  }

  setVolumes({ master, music, sfx }) {
    if (master !== undefined) this.masterVolume = master;
    if (music !== undefined) this.musicVolume = music;
    if (sfx !== undefined) this.sfxVolume = sfx;
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    this.master.gain.setTargetAtTime(this.muted ? 0 : this.masterVolume, t, 0.08);
    this._sfxGain.gain.setTargetAtTime(this.sfxVolume, t, 0.08);
    this._musicGain.gain.setTargetAtTime(this.muted ? 0 : this.musicVolume * 0.25, t, 0.3);
  }

  toggleMute() {
    this.muted = !this.muted;
    this.setVolumes({});
    return this.muted;
  }

  /* ---------------- sound effects ---------------- */
  _env(gainNode, t, attack, hold, release, peak) {
    gainNode.gain.cancelScheduledValues(t);
    gainNode.gain.setValueAtTime(0.0001, t);
    gainNode.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), t + attack);
    gainNode.gain.setValueAtTime(Math.max(0.0002, peak), t + attack + hold);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, t + attack + hold + release);
  }

  tone({ freq = 440, freqEnd = null, type = 'sine', dur = 0.3, gain = 0.12, attack = 0.008, hold = 0.02, detune = 0, pan = 0, wet = 0.25 }) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const p = this.ctx.createStereoPanner();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (freqEnd) osc.frequency.exponentialRampToValueAtTime(Math.max(1, freqEnd), t + attack + hold + dur);
    osc.detune.value = detune;
    p.pan.value = pan;
    this._env(g, t, attack, hold, dur, gain);
    osc.connect(g); g.connect(p); p.connect(this._sfxGain);
    if (wet > 0) {
      const send = this.ctx.createGain(); send.gain.value = wet;
      p.connect(send); send.connect(this.reverb);
    }
    osc.start(t);
    osc.stop(t + attack + hold + dur + 0.05);
  }

  noise({ dur = 0.3, gain = 0.2, filter = 'bandpass', freq = 1200, freqEnd = null, q = 1, attack = 0.005, pan = 0, wet = 0.15 }) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const f = this.ctx.createBiquadFilter();
    f.type = filter; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    if (freqEnd) f.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t + dur);
    const g = this.ctx.createGain();
    const p = this.ctx.createStereoPanner();
    p.pan.value = pan;
    this._env(g, t, attack, 0.01, dur, gain);
    src.connect(f); f.connect(g); g.connect(p); p.connect(this._sfxGain);
    if (wet > 0) {
      const send = this.ctx.createGain(); send.gain.value = wet;
      p.connect(send); send.connect(this.reverb);
    }
    src.start(t);
    src.stop(t + dur + 0.1);
  }

  sfx(name, opts = {}) {
    if (!this.ready) return;
    switch (name) {
      case 'jump':
        this.tone({ freq: 280, freqEnd: 620, type: 'sine', dur: 0.18, gain: 0.09, wet: 0.2 });
        this.noise({ dur: 0.16, gain: 0.03, filter: 'highpass', freq: 900, freqEnd: 2600 });
        break;
      case 'doubleJump':
        this.tone({ freq: 520, freqEnd: 1050, type: 'triangle', dur: 0.22, gain: 0.07, wet: 0.4 });
        this.tone({ freq: 780, freqEnd: 1560, type: 'sine', dur: 0.18, gain: 0.045, wet: 0.5 });
        break;
      case 'land':
        this.noise({ dur: 0.18, gain: 0.12, filter: 'lowpass', freq: 420, freqEnd: 120, q: 0.7, wet: 0.08 });
        this.tone({ freq: 110, freqEnd: 55, type: 'sine', dur: 0.16, gain: 0.13, wet: 0.05 });
        break;
      case 'dash':
        this.noise({ dur: 0.32, gain: 0.12, filter: 'bandpass', freq: 380, freqEnd: 2800, q: 1.6, wet: 0.15 });
        this.tone({ freq: 220, freqEnd: 620, type: 'sawtooth', dur: 0.16, gain: 0.025, wet: 0.2 });
        break;
      case 'attack':
      case 'attack2':
      case 'attack3': {
        const base = name === 'attack' ? 1500 : name === 'attack2' ? 1900 : 2400;
        this.noise({ dur: 0.16, gain: 0.1, filter: 'bandpass', freq: base, freqEnd: base * 0.3, q: 1.2, wet: 0.2 });
        this.tone({ freq: base * 0.22, freqEnd: base * 0.1, type: 'triangle', dur: 0.12, gain: 0.035, wet: 0.3 });
        break;
      }
      case 'hit':
        this.noise({ dur: 0.12, gain: 0.2, filter: 'lowpass', freq: 1800, freqEnd: 260, q: 0.8, wet: 0.1 });
        this.tone({ freq: 150, freqEnd: 70, type: 'square', dur: 0.09, gain: 0.05, wet: 0.1 });
        break;
      case 'enemyHit':
        this.tone({ freq: 360, freqEnd: 180, type: 'triangle', dur: 0.1, gain: 0.07, wet: 0.2 });
        this.noise({ dur: 0.08, gain: 0.08, filter: 'bandpass', freq: 1600, q: 1.2 });
        break;
      case 'enemyDie':
        this.tone({ freq: 320, freqEnd: 90, type: 'sawtooth', dur: 0.4, gain: 0.06, wet: 0.4 });
        this.noise({ dur: 0.35, gain: 0.12, filter: 'lowpass', freq: 2400, freqEnd: 180, wet: 0.3 });
        break;
      case 'hurt':
        this.tone({ freq: 220, freqEnd: 60, type: 'sawtooth', dur: 0.32, gain: 0.1, wet: 0.25 });
        this.noise({ dur: 0.2, gain: 0.1, filter: 'lowpass', freq: 1200, freqEnd: 200, wet: 0.1 });
        break;
      case 'collect':
        this.tone({ freq: NOTE(88), type: 'sine', dur: 0.38, gain: 0.07, wet: 0.55 });
        setTimeout(() => this.tone({ freq: NOTE(95), type: 'sine', dur: 0.5, gain: 0.055, wet: 0.65 }), 65);
        setTimeout(() => this.tone({ freq: NOTE(100), type: 'triangle', dur: 0.45, gain: 0.03, wet: 0.7 }), 130);
        break;
      case 'checkpoint':
        [60, 64, 67, 72].forEach((n, i) => setTimeout(() => this.tone({ freq: NOTE(n), type: 'sine', dur: 1.1, gain: 0.05, attack: 0.06, wet: 0.7 }), i * 90));
        break;
      case 'heal':
        [72, 76, 79].forEach((n, i) => setTimeout(() => this.tone({ freq: NOTE(n), type: 'sine', dur: 0.7, gain: 0.05, wet: 0.6 }), i * 70));
        break;
      case 'portal':
        this.tone({ freq: 180, freqEnd: 880, type: 'sine', dur: 1.2, gain: 0.05, attack: 0.2, wet: 0.8 });
        this.noise({ dur: 1.1, gain: 0.06, filter: 'bandpass', freq: 400, freqEnd: 4200, q: 2, attack: 0.25, wet: 0.7 });
        break;
      case 'bossRoar':
        this.tone({ freq: 72, freqEnd: 38, type: 'sawtooth', dur: 1.6, gain: 0.14, attack: 0.08, wet: 0.45 });
        this.tone({ freq: 96, freqEnd: 45, type: 'square', dur: 1.4, gain: 0.06, attack: 0.1, wet: 0.4 });
        this.noise({ dur: 1.3, gain: 0.09, filter: 'lowpass', freq: 600, freqEnd: 120, attack: 0.05, wet: 0.3 });
        break;
      case 'bossHit':
        this.noise({ dur: 0.22, gain: 0.16, filter: 'lowpass', freq: 2400, freqEnd: 160, q: 0.9, wet: 0.25 });
        this.tone({ freq: 110, freqEnd: 52, type: 'square', dur: 0.18, gain: 0.05, wet: 0.2 });
        break;
      case 'slam':
        this.tone({ freq: 80, freqEnd: 28, type: 'sine', dur: 0.6, gain: 0.22, wet: 0.3 });
        this.noise({ dur: 0.5, gain: 0.18, filter: 'lowpass', freq: 1400, freqEnd: 90, wet: 0.25 });
        break;
      case 'shockwave':
        this.noise({ dur: 0.55, gain: 0.12, filter: 'bandpass', freq: 220, freqEnd: 1200, q: 0.7, wet: 0.35 });
        break;
      case 'shoot':
        this.tone({ freq: 900, freqEnd: 280, type: 'triangle', dur: 0.22, gain: 0.055, wet: 0.4 });
        this.noise({ dur: 0.12, gain: 0.04, filter: 'highpass', freq: 1800 });
        break;
      case 'death':
        this.tone({ freq: 180, freqEnd: 40, type: 'sawtooth', dur: 1.4, gain: 0.1, wet: 0.6 });
        this.noise({ dur: 1.2, gain: 0.09, filter: 'lowpass', freq: 1000, freqEnd: 80, wet: 0.4 });
        break;
      case 'victory':
        [60, 64, 67, 72, 76, 79, 84].forEach((n, i) => setTimeout(() => this.tone({ freq: NOTE(n), type: 'sine', dur: 1.8, gain: 0.055, attack: 0.04, wet: 0.8 }), i * 160));
        break;
      case 'ui':
        this.tone({ freq: 720, freqEnd: 980, type: 'sine', dur: 0.09, gain: 0.035, wet: 0.2 });
        break;
      case 'step':
        this.noise({ dur: 0.07, gain: 0.022 + Math.random() * 0.012, filter: 'lowpass', freq: 500 + Math.random() * 300, q: 0.8, wet: 0.02 });
        break;
      case 'splash':
        this.noise({ dur: 0.2, gain: 0.06, filter: 'bandpass', freq: 1400, freqEnd: 700, q: 0.8, wet: 0.15 });
        break;
      default:
        break;
    }
  }

  /* ---------------- generative music ---------------- */
  startMusic(zone) {
    if (!this.ready) return;
    if (this.musicTimer) return;
    this.zone = zone;
    this.step = 0;
    this.nextNoteTime = this.ctx.currentTime + 0.15;
    this.musicTimer = setInterval(() => this._scheduleMusic(), 180);
    this._scheduleMusic();
  }

  setZone(zone) {
    if (this.zone === zone) return;
    this.zone = zone;
    // A gentle harmonic lift when entering a new realm.
    if (this.ready) {
      this.tone({ freq: NOTE(ZONE_MUSIC[zone].root + 12), type: 'sine', dur: 1.6, gain: 0.03, attack: 0.2, wet: 0.8 });
    }
  }

  _scheduleMusic() {
    if (!this.ready || !this._musicGain) return;
    const conf = ZONE_MUSIC[this.zone] || ZONE_MUSIC.meadow;
    const stepDur = conf.tempo / 2;
    while (this.nextNoteTime < this.ctx.currentTime + 0.8) {
      const step = this.step;
      const chordIndex = Math.floor(step / 8) % conf.chords.length;
      const chord = conf.chords[chordIndex];
      const time = this.nextNoteTime;

      // Pad bloom on each chord.
      if (step % 8 === 0) {
        chord.forEach((semi, ci) => {
          this._musicNote(NOTE(conf.root + semi), time + ci * 0.08, stepDur * 7.8, 0.035, 'sine', 0.9, 0.35);
          if (ci === 0) this._musicNote(NOTE(conf.root + semi - 12), time, stepDur * 8, 0.03, 'triangle', 0.8, 0.1);
        });
      }

      // Airy arpeggio.
      const arpNote = conf.arp[step % conf.arp.length];
      const arpGain = 0.014 + (step % 4 === 0 ? 0.008 : 0);
      this._musicNote(NOTE(conf.root + 12 + arpNote), time, stepDur * 2.2, arpGain, 'sine', 0.7, 0.6);

      // Sub pulse / soft heartbeat every two beats.
      if (step % 4 === 0) {
        this._musicNote(NOTE(conf.root - 24), time, stepDur * 1.4, 0.045, 'sine', 0.9, 0.05);
      }

      this.nextNoteTime += stepDur;
      this.step++;
    }
  }

  _musicNote(freq, time, dur, gain, type = 'sine', attackRatio = 0.2, wet = 0.4) {
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(type === 'sine' ? 3200 : 1400, time);
    filter.Q.value = 0.4;
    osc.type = type;
    osc.frequency.setValueAtTime(freq, time);
    osc.detune.value = rand(-4, 4);
    const attack = Math.max(0.01, dur * attackRatio);
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), time + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    osc.connect(filter); filter.connect(g); g.connect(this._musicGain);
    if (wet > 0) {
      const send = this.ctx.createGain(); send.gain.value = wet;
      g.connect(send); send.connect(this.reverb);
    }
    osc.start(time);
    osc.stop(time + dur + 0.05);
  }

  /* ---------------- ambience ---------------- */
  startAmbience() {
    if (!this.ready) return;
    // Looping wind bed.
    const src = this.ctx.createBufferSource();
    src.buffer = this._makeNoise(4);
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass'; filter.frequency.value = 380; filter.Q.value = 0.4;
    const gain = this.ctx.createGain(); gain.gain.value = 0.018;
    const lfo = this.ctx.createOscillator(); lfo.frequency.value = 0.07;
    const lfoGain = this.ctx.createGain(); lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain); lfoGain.connect(gain.gain);
    src.connect(filter); filter.connect(gain); gain.connect(this.master);
    src.start();
    lfo.start();
    this.ambientNodes.push(src, lfo);

    // Occasional bird calls / crystal chimes.
    this._ambientTimer = setInterval(() => {
      if (!this.ready || this.muted || document.hidden) return;
      if (Math.random() > 0.55) return;
      if (this.zone === 'meadow' || this.zone === 'sky') {
        const base = rand(1400, 2300);
        this.tone({ freq: base, freqEnd: base * rand(1.05, 1.4), type: 'sine', dur: 0.12, gain: 0.012, attack: 0.01, pan: rand(-0.7, 0.7), wet: 0.6 });
        setTimeout(() => this.tone({ freq: base * 1.15, freqEnd: base * 0.9, type: 'sine', dur: 0.1, gain: 0.008, wet: 0.6 }), 140);
      } else if (this.zone === 'crystal') {
        this.tone({ freq: rand(1600, 2600), type: 'sine', dur: 1.4, gain: 0.008, attack: 0.1, wet: 0.9 });
      } else if (this.zone === 'ruins') {
        this.tone({ freq: rand(260, 420), type: 'triangle', dur: 1.8, gain: 0.008, attack: 0.3, wet: 0.8 });
      }
    }, 3300);
  }

  setPaused(paused) {
    if (!this.ready || !this._musicGain) return;
    const target = this.muted ? 0 : this.musicVolume * (paused ? 0.08 : 0.25);
    this._musicGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.25);
  }
}

