const SKY_VERT = /* glsl */`
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_Position = projectionMatrix * mv;
    gl_Position.z = gl_Position.w; // always at far plane
  }
`;

const SKY_FRAG = /* glsl */`
  precision highp float;
  uniform vec3 uSunDir;
  uniform vec3 uTop;
  uniform vec3 uHorizon;
  uniform vec3 uBottom;
  uniform vec3 uSunColor;
  uniform vec3 uCloudColor;
  uniform vec3 uCloudShade;
  uniform float uTime;
  uniform float uCloudAmount;
  varying vec3 vDir;

  float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
  }
  float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
  }
  float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 5; i++) {
      v += a * noise(p);
      p = p * 2.03 + vec2(11.7, 5.3);
      a *= 0.5;
    }
    return v;
  }

  void main() {
    vec3 dir = normalize(vDir);
    float up = clamp(dir.y, -1.0, 1.0);
    float h = clamp(up * 0.5 + 0.5, 0.0, 1.0);

    // Base vertical gradient, extra warm at the horizon.
    vec3 col = mix(uBottom, uHorizon, smoothstep(-0.18, 0.06, up));
    col = mix(col, uTop, pow(clamp(up, 0.0, 1.0), 0.58));

    float sun = clamp(dot(dir, uSunDir), 0.0, 1.0);
    float az = max(0.0, dot(normalize(vec3(dir.x, 0.0, dir.z)), normalize(vec3(uSunDir.x, 0.0, uSunDir.z))));

    // Warm horizon wash on the sun's side.
    float horizonWarm = pow(1.0 - abs(up), 7.0) * pow(az, 2.0);
    col += uSunColor * horizonWarm * 0.22;

    // Sun disk + broad halo.
    col += uSunColor * pow(sun, 900.0) * 4.2;
    col += uSunColor * pow(sun, 32.0) * 0.34;
    col += uSunColor * pow(sun, 6.0) * 0.08;

    // Procedural cloud deck (projected on a virtual plane).
    vec2 cuv = dir.xz / max(up, 0.055) * 0.42;
    cuv += vec2(uTime * 0.0018, uTime * 0.0007);
    float n = fbm(cuv * 1.7 + fbm(cuv * 0.8) * 0.9);
    float cloud = smoothstep(0.51, 0.74, n) * smoothstep(0.015, 0.24, up);
    cloud *= uCloudAmount;
    float lit = clamp(0.35 + sun * 0.9, 0.0, 1.0);
    vec3 cloudCol = mix(uCloudShade, uCloudColor, lit);
    cloudCol += uSunColor * pow(sun, 4.0) * 0.16;
    col = mix(col, cloudCol, cloud * 0.82);

    // Subtle atmospheric noise / dithering.
    float dither = (hash(gl_FragCoord.xy) - 0.5) * 0.0035;
    col += dither;

    gl_FragColor = vec4(col, 1.0);
  }
`;

const GradeShader = {
  uniforms: {
    tDiffuse: { value: null },
    uTime: { value: 0 },
    uVignette: { value: 0.36 },
    uSaturation: { value: 1.12 },
    uGrain: { value: 0.018 },
    uWarmth: { value: 0.04 },
    uAberration: { value: 0.0016 },
  },
  vertexShader: /* glsl */`
    varying vec2 vUv;
    void main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }
  `,
  fragmentShader: /* glsl */`
    uniform sampler2D tDiffuse;
    uniform float uTime, uVignette, uSaturation, uGrain, uWarmth, uAberration;
    varying vec2 vUv;
    void main() {
      vec2 uv = vUv;
      vec2 d = uv - 0.5;
      float r2 = dot(d, d);
      float ca = uAberration * (0.35 + r2 * 2.2);
      vec3 col;
      col.r = texture2D(tDiffuse, uv + d * ca).r;
      col.g = texture2D(tDiffuse, uv).g;
      col.b = texture2D(tDiffuse, uv - d * ca).b;

      float lum = dot(col, vec3(0.299, 0.587, 0.114));
      col = mix(vec3(lum), col, uSaturation);
      // teal shadows / warm highlights, filmic split-tone
      col *= vec3(1.0 + uWarmth, 1.0 + uWarmth * 0.35, 1.0 - uWarmth * 0.35);
      col += vec3(-0.004, 0.006, 0.010) * (1.0 - smoothstep(0.0, 0.45, lum));
      col += vec3(0.012, 0.006, -0.006) * smoothstep(0.55, 1.0, lum);

      float vig = smoothstep(1.03, 0.26, length(d) * 1.42);
      col *= mix(1.0, vig, uVignette);

      float grain = fract(sin(dot(uv * (1.0 + fract(uTime) * 0.01) * 1013.0, vec2(12.9898, 78.233))) * 43758.5453);
      col += (grain - 0.5) * uGrain;

      gl_FragColor = vec4(max(col, 0.0), 1.0);
    }
  `,
};

export class Environment {
  constructor(container, { quality = 'high', renderScale = 1.0 } = {}) {
    this.container = container;
    this.qualityName = quality;
    this.renderScale = renderScale;
    this.autoScale = 1;
    this.tmpColor = new THREE.Color();
    this.zone = 'meadow';
    this.ambiance = { ...AMBIANCE.meadow };
    this.currentAmbiance = {
      fog: new THREE.Color(AMBIANCE.meadow.fog),
      fogDensity: AMBIANCE.meadow.fogDensity,
      sun: AMBIANCE.meadow.sun,
      sunColor: new THREE.Color(AMBIANCE.meadow.sunColor),
      hemi: AMBIANCE.meadow.hemi,
      exposure: AMBIANCE.meadow.exposure,
      skyTop: new THREE.Color(AMBIANCE.meadow.skyTop),
      skyHorizon: new THREE.Color(AMBIANCE.meadow.skyHorizon),
      skyBottom: new THREE.Color(AMBIANCE.meadow.skyBottom),
      cloud: AMBIANCE.meadow.cloud,
      bloom: 1.0,
    };
    this.dayTime = 0.42;
    this.sunDir = new THREE.Vector3(0.55, 0.74, 0.38).normalize();

    /* ---------- renderer ---------- */
    this.renderer = new THREE.WebGLRenderer({
      antialias: false,
      alpha: false,
      powerPreference: 'high-performance',
      stencil: false,
      logarithmicDepthBuffer: false,
    });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.info.autoReset = true;
    this.renderer.domElement.setAttribute('aria-label', 'Aetherbound game viewport');
    container.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(AMBIANCE.meadow.fog, AMBIANCE.meadow.fogDensity);

    this.camera = new THREE.PerspectiveCamera(58, window.innerWidth / window.innerHeight, 0.1, 1200);
    this.camera.position.set(0, 6, 14);
    this.cameraTarget = new THREE.Vector3(0, 2, 0);

    /* ---------- sky ---------- */
    this.sunColor = new THREE.Color(0xfff0cf);
    this.skyUniforms = {
      uSunDir: { value: this.sunDir.clone() },
      uTop: { value: new THREE.Color(AMBIANCE.meadow.skyTop) },
      uHorizon: { value: new THREE.Color(AMBIANCE.meadow.skyHorizon) },
      uBottom: { value: new THREE.Color(AMBIANCE.meadow.skyBottom) },
      uSunColor: { value: new THREE.Color(0xfff0c8) },
      uCloudColor: { value: new THREE.Color(0xfdfbf4) },
      uCloudShade: { value: new THREE.Color(0xb9cfd4) },
      uTime: { value: 0 },
      uCloudAmount: { value: AMBIANCE.meadow.cloud },
    };
    const skyMat = new THREE.ShaderMaterial({
      uniforms: this.skyUniforms,
      vertexShader: SKY_VERT,
      fragmentShader: SKY_FRAG,
      side: THREE.BackSide,
      depthWrite: false,
      depthTest: false,
      fog: false,
      toneMapped: false,
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(620, 48, 32), skyMat);
    this.sky.frustumCulled = false;
    this.sky.renderOrder = -20;
    this.scene.add(this.sky);

    // Separate scene used once to bake the sky into an IBL environment.
    this._buildEnvironmentMap();

    /* ---------- lighting ---------- */
    this.hemi = new THREE.HemisphereLight(0xbfe9ff, 0x6f7f4f, AMBIANCE.meadow.hemi);
    this.scene.add(this.hemi);

    this.sun = new THREE.DirectionalLight(AMBIANCE.meadow.sunColor, AMBIANCE.meadow.sun);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(4096, 4096);
    this.sun.shadow.camera.near = 1;
    this.sun.shadow.camera.far = 280;
    this.sun.shadow.camera.left = -60;
    this.sun.shadow.camera.right = 60;
    this.sun.shadow.camera.top = 60;
    this.sun.shadow.camera.bottom = -60;
    this.sun.shadow.bias = -0.0007;
    this.sun.shadow.normalBias = 0.035;
    this.sun.shadow.radius = 3.5;
    this.scene.add(this.sun);
    this.sun.target.position.set(0, 0, 0);
    this.scene.add(this.sun.target);

    this.fill = new THREE.DirectionalLight(0x9fdfff, 0.38);
    this.fill.position.set(-45, 35, -30);
    this.scene.add(this.fill);

    /* ---------- sun sprite + atmospheric shafts ---------- */
    this.glowTex = makeRadialTexture(128, 'rgba(255,248,220,1)', 'rgba(255,210,120,0)', 0.12);
    this.sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.glowTex, color: 0xfff0c8, transparent: true, opacity: 0.72,
      blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false, toneMapped: false,
    }));
    this.sunSprite.scale.set(74, 74, 1);
    this.sunSprite.renderOrder = -10;
    this.scene.add(this.sunSprite);

    this.rays = new THREE.Group();
    const shaftTex = makeShaftTexture(128);
    for (let i = 0; i < 8; i++) {
      const w = 8 + Math.random() * 22;
      const h = 38 + Math.random() * 50;
      const mat = new THREE.MeshBasicMaterial({
        map: shaftTex, color: 0xffe8b8, transparent: true,
        opacity: 0.035 + Math.random() * 0.045, blending: THREE.AdditiveBlending,
        depthWrite: false, side: THREE.DoubleSide, toneMapped: false, fog: false,
      });
      const plane = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
      plane.position.set(-15 + i * 9 + Math.random() * 6, 16 + Math.random() * 15, 12 - i * 5);
      plane.rotation.z = -0.35 + Math.random() * 0.2;
      plane.rotation.y = Math.random() * 0.4 - 0.2;
      plane.renderOrder = 2;
      this.rays.add(plane);
    }
    this.scene.add(this.rays);

    /* ---------- cloud layers ---------- */
    this.cloudTex = makeCloudTexture(256, 4);
    this.clouds = new THREE.Group();
    for (let i = 0; i < 22; i++) {
      const mat = new THREE.SpriteMaterial({
        map: this.cloudTex, transparent: true,
        opacity: 0.1 + Math.random() * 0.2,
        color: new THREE.Color().setHSL(0.52, 0.18, 0.94),
        depthWrite: false, fog: false, toneMapped: false,
      });
      const s = new THREE.Sprite(mat);
      const scale = 42 + Math.random() * 80;
      s.scale.set(scale * 1.7, scale * 0.62, 1);
      s.position.set((Math.random() - 0.5) * 360, 26 + Math.random() * 70, -260 + Math.random() * 310);
      s.userData.speed = 0.12 + Math.random() * 0.2;
      this.clouds.add(s);
    }
    this.scene.add(this.clouds);

    /* ---------- post ---------- */
    this.composer = null;
    this._buildComposer();
    this.applyQuality(quality, { silent: true });
    this._bindResize();
  }

  _buildEnvironmentMap() {
    const pmrem = new THREE.PMREMGenerator(this.renderer);
    pmrem.compileEquirectangularShader();
    const envScene = new THREE.Scene();
    const envSky = new THREE.Mesh(this.sky.geometry, this.sky.material.clone());
    envSky.material.depthTest = true;
    envSky.material.side = THREE.BackSide;
    envScene.add(envSky);
    // A soft ground disc gives the IBL a believable bounce colour.
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(500, 32),
      new THREE.MeshBasicMaterial({ color: 0x6b7d54 })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -12;
    envScene.add(ground);
    const rt = pmrem.fromScene(envScene, 0.02, 0.1, 1000);
    this.envMap = rt.texture;
    this.scene.environment = rt.texture;
    pmrem.dispose();
  }

  _buildComposer() {
    if (this.composer) {
      this.composer.dispose?.();
      this.composer = null;
    }
    const preset = QUALITY[this.qualityName] || QUALITY.high;
    this.composer = new EffectComposer(this.renderer);
    this.composer.setPixelRatio(this._effectivePixelRatio());
    this.composer.setSize(window.innerWidth, window.innerHeight);

    this.renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(this.renderPass);

    this.ssaoPass = null;
    if (preset.ssao) {
      try {
        this.ssaoPass = new SSAOPass(this.scene, this.camera, window.innerWidth, window.innerHeight);
        this.ssaoPass.kernelRadius = 1.4;
        this.ssaoPass.minDistance = 0.002;
        this.ssaoPass.maxDistance = 0.08;
        this.ssaoPass.output = SSAOPass.OUTPUT.Default;
        this.composer.addPass(this.ssaoPass);
      } catch (err) {
        console.warn('SSAO unavailable:', err);
        this.ssaoPass = null;
      }
    }

    this.bokehPass = null;
    if (preset.dof) {
      try {
        this.bokehPass = new BokehPass(this.scene, this.camera, { focus: 12, aperture: 0.00045, maxblur: 0.0055 });
        this.composer.addPass(this.bokehPass);
      } catch (err) {
        console.warn('DOF unavailable:', err);
        this.bokehPass = null;
      }
    }

    this.bloomPass = null;
    if (preset.bloom) {
      this.bloomPass = new UnrealBloomPass(
        new THREE.Vector2(window.innerWidth, window.innerHeight),
        preset.bloomStrength, preset.bloomRadius, preset.bloomThreshold
      );
      this.composer.addPass(this.bloomPass);
    }

    this.gradePass = new ShaderPass(GradeShader);
    this.composer.addPass(this.gradePass);

    this.outputPass = new OutputPass();
    this.composer.addPass(this.outputPass);

    if (preset.smaa) {
      this.smaaPass = new SMAAPass(window.innerWidth, window.innerHeight);
      this.composer.addPass(this.smaaPass);
    } else {
      this.smaaPass = null;
    }

    this.renderer.shadowMap.enabled = preset.shadow;
    this.sun.castShadow = preset.shadow;
    this.sun.shadow.mapSize.set(preset.shadowSize, preset.shadowSize);
    if (this.sun.shadow.map) {
      this.sun.shadow.map.dispose();
      this.sun.shadow.map = null;
    }
  }

  _effectivePixelRatio() {
    const preset = QUALITY[this.qualityName] || QUALITY.high;
    const dpr = Math.min(window.devicePixelRatio || 1, preset.maxPR);
    return clamp(dpr * this.renderScale * this.autoScale, 0.5, 2.2);
  }

  applyQuality(name, { silent = false, renderScale = this.renderScale } = {}) {
    if (!QUALITY[name]) name = 'high';
    this.qualityName = name;
    this.renderScale = renderScale;
    if (!silent) this._buildComposer();
    this._applyResolution();
    return QUALITY[name];
  }

  _applyResolution() {
    const pr = this._effectivePixelRatio();
    this.renderer.setPixelRatio(pr);
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    if (this.composer) {
      this.composer.setPixelRatio(pr);
      this.composer.setSize(window.innerWidth, window.innerHeight);
    }
    if (this.smaaPass && this.smaaPass.setSize) this.smaaPass.setSize(window.innerWidth, window.innerHeight);
  }

  setRenderScale(scale, { rebuild = false } = {}) {
    this.renderScale = clamp(scale, 0.6, 1.5);
    if (rebuild) this._buildComposer();
    this._applyResolution();
  }

  setAutoScale(scale) {
    this.autoScale = clamp(scale, 0.6, 1.0);
    this._applyResolution();
  }

  _bindResize() {
    window.addEventListener('resize', () => {
      const w = window.innerWidth, h = window.innerHeight;
      this.camera.aspect = w / h;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(w, h, false);
      if (this.composer) this.composer.setSize(w, h);
      if (this.smaaPass && this.smaaPass.setSize) this.smaaPass.setSize(w, h);
      if (this.bokehPass) {
        this.bokehPass.uniforms.aspect.value = this.camera.aspect;
      }
    });
  }

  setZone(zone, instant = false) {
    const target = AMBIANCE[zone] || AMBIANCE.meadow;
    this.zone = zone;
    this.ambiance = target;
    if (instant) {
      this.currentAmbiance.fog.set(target.fog);
      this.currentAmbiance.fogDensity = target.fogDensity;
      this.currentAmbiance.sun = target.sun;
      this.currentAmbiance.sunColor.set(target.sunColor);
      this.currentAmbiance.hemi = target.hemi;
      this.currentAmbiance.exposure = target.exposure;
      this.currentAmbiance.skyTop.set(target.skyTop);
      this.currentAmbiance.skyHorizon.set(target.skyHorizon);
      this.currentAmbiance.skyBottom.set(target.skyBottom);
      this.currentAmbiance.cloud = target.cloud;
      this.currentAmbiance.bloom = target.bloom;
      this._applyAmbiance();
    }
  }

  _applyAmbiance() {
    const a = this.currentAmbiance;
    this.scene.fog.color.copy(a.fog);
    this.scene.fog.density = a.fogDensity;
    this.sun.intensity = a.sun;
    this.sun.color.copy(a.sunColor);
    this.hemi.intensity = a.hemi;
    this.hemi.color.copy(a.skyTop);
    this.hemi.groundColor.set(0x6f7f4f).lerp(a.fog, 0.25);
    this.renderer.toneMappingExposure = a.exposure;
    this.skyUniforms.uTop.value.copy(a.skyTop);
    this.skyUniforms.uHorizon.value.copy(a.skyHorizon);
    this.skyUniforms.uBottom.value.copy(a.skyBottom);
    this.skyUniforms.uCloudAmount.value = a.cloud;
    if (this.bloomPass) this.bloomPass.strength = (QUALITY[this.qualityName]?.bloomStrength || 0.35) * a.bloom;
    if (this.gradePass) this.gradePass.uniforms.uVignette.value = this.zone === 'crystal' ? 0.46 : 0.34;
    this.rays.visible = !!this.ambiance.rays;
  }

  getAmbiance() { return this.currentAmbiance; }

  update(dt, playerPos) {
    if (!playerPos) return;
    // slow time-of-day orbit
    this.dayTime += dt * 0.0032;
    const az = this.dayTime * 0.62;
    const elev = 0.55 + Math.sin(this.dayTime * 1.7) * 0.13;
    this.sunDir.set(Math.cos(az) * 0.95, elev, Math.sin(az) * 0.85).normalize();
    this.skyUniforms.uSunDir.value.copy(this.sunDir);
    this.skyUniforms.uTime.value += dt;

    // sky + sun sprite follow the camera; shadow light follows the player
    this.sky.position.copy(this.camera.position);
    this.sunSprite.position.copy(this.camera.position).addScaledVector(this.sunDir, 480);
    // keep the sun sprite on-screen sized consistently
    this.sunSprite.material.opacity = this.zone === 'crystal' ? 0.0 : 0.72;

    const shadowTarget = playerPos.clone();
    shadowTarget.y += 0.5;
    this.sun.target.position.copy(shadowTarget);
    this.sun.position.copy(shadowTarget).addScaledVector(this.sunDir, 105);
    this.sun.target.updateMatrixWorld();
    this.fill.position.copy(shadowTarget).add(new THREE.Vector3(-45, 35, -30));

    // smooth zone ambience
    const a = this.ambiance;
    const c = this.currentAmbiance;
    const k = 1 - Math.exp(-dt * 1.65);
    c.fog.lerp(this.tmpColor.set(a.fog), k);
    c.fogDensity = lerp(c.fogDensity, a.fogDensity, k);
    c.sun = lerp(c.sun, a.sun, k);
    c.sunColor.lerp(this.tmpColor.set(a.sunColor), k);
    c.hemi = lerp(c.hemi, a.hemi, k);
    c.exposure = lerp(c.exposure, a.exposure, k);
    c.skyTop.lerp(this.tmpColor.set(a.skyTop), k);
    c.skyHorizon.lerp(this.tmpColor.set(a.skyHorizon), k);
    c.skyBottom.lerp(this.tmpColor.set(a.skyBottom), k);
    c.cloud = lerp(c.cloud, a.cloud, k);
    c.bloom = lerp(c.bloom, a.bloom, k);
    this._applyAmbiance();
    this.skyUniforms.uSunColor.value.set(0xfff0c8).lerp(this.tmpColor.set(0xffc789), clamp(1 - this.sunDir.y, 0, 1) * 0.65);

    // clouds drift
    for (const cloud of this.clouds.children) {
      cloud.position.x += dt * cloud.userData.speed;
      if (cloud.position.x > 210) cloud.position.x = -210;
    }
    this.rays.rotation.y += dt * 0.002;

    // sun shafts gently pulse
    for (let i = 0; i < this.rays.children.length; i++) {
      const p = this.rays.children[i];
      p.material.opacity = (0.035 + Math.sin(performance.now() * 0.0002 + i) * 0.012) * (this.zone === 'crystal' ? 0 : 1);
    }

    if (this.gradePass) {
      this.gradePass.uniforms.uTime.value += dt;
      this.gradePass.uniforms.uSaturation.value = this.zone === 'crystal' ? 1.05 : 1.13;
    }
    if (this.bokehPass) {
      const dist = this.camera.position.distanceTo(playerPos);
      this.bokehPass.uniforms.focus.value = damp(this.bokehPass.uniforms.focus.value, dist, 4, dt);
      this.bokehPass.uniforms.aperture.value = 0.00045;
      this.bokehPass.uniforms.maxblur.value = 0.006;
    }
  }

  render(dt) {
    if (this.composer) this.composer.render(dt);
    else this.renderer.render(this.scene, this.camera);
  }
}

/* ============================================================
   Effects — GPU point particles, ambient fields, shockwaves,
   slash arcs, lightning, camera shake and hit feedback.
   ============================================================ */
import * as THREE from 'three';
import { makeRadialTexture, rand, randInt, pick, clamp, lerp } from './Utils.js';

const GLOW = makeRadialTexture(128, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)', 0.16);
const PETAL = makeRadialTexture(64, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)', 0.55);

const POINT_VERT = /* glsl */`
  attribute float aSize;
  attribute vec3 aColor;
  attribute float aAlpha;
  varying vec3 vColor;
  varying float vAlpha;
  uniform float uScale;
  void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = clamp(aSize * uScale / max(1.0, -mv.z), 1.0, 180.0);
    gl_Position = projectionMatrix * mv;
    vColor = aColor;
    vAlpha = aAlpha;
  }
`;
const POINT_FRAG = /* glsl */`
  uniform sampler2D uMap;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec4 tex = texture2D(uMap, gl_PointCoord);
    float a = tex.a * vAlpha;
    if (a < 0.003) discard;
    gl_FragColor = vec4(vColor, a);
  }
`;

class ParticlePool {
  constructor(scene, max = 1800) {
    this.max = max;
    this.cursor = 0;
    this.data = [];
    const positions = new Float32Array(max * 3);
    const colors = new Float32Array(max * 3);
    const sizes = new Float32Array(max);
    const alphas = new Float32Array(max);
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aColor', new THREE.BufferAttribute(colors, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1).setUsage(THREE.DynamicDrawUsage));
    this.geo = geo;
    this.mat = new THREE.ShaderMaterial({
      uniforms: {
        uMap: { value: GLOW },
        uScale: { value: 620 },
      },
      vertexShader: POINT_VERT,
      fragmentShader: POINT_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });
    this.points = new THREE.Points(geo, this.mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 6;
    scene.add(this.points);
  }

  spawn(opts) {
    const {
      position, count = 12, speed = 4, speedVar = 0.7, direction = null, spread = 1,
      size = 0.2, sizeVar = 0.5, life = 0.6, lifeVar = 0.4, gravity = -6,
      drag = 1.4, colors = [0xffe3a0], posVar = 0.1,
    } = opts;
    const col = new THREE.Color();
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.max;
      let d;
      if (direction) {
        d = direction.clone().normalize();
        d.x += rand(-spread, spread);
        d.y += rand(-spread, spread);
        d.z += rand(-spread, spread);
        d.normalize();
      } else {
        const theta = rand(0, Math.PI * 2);
        const phi = Math.acos(rand(-1, 1));
        d = new THREE.Vector3(Math.sin(phi) * Math.cos(theta), Math.cos(phi), Math.sin(phi) * Math.sin(theta));
      }
      const sp = speed * (1 + rand(-speedVar, speedVar));
      const p = this.data[i] || (this.data[i] = { pos: new THREE.Vector3(), vel: new THREE.Vector3(), life: 0, maxLife: 1, size: 0, color: new THREE.Color(), gravity: 0, drag: 1 });
      p.pos.set(
        position.x + rand(-posVar, posVar),
        position.y + rand(-posVar, posVar),
        position.z + rand(-posVar, posVar)
      );
      p.vel.copy(d).multiplyScalar(sp);
      p.life = p.maxLife = life * (1 + rand(-lifeVar, lifeVar));
      p.size = size * (1 + rand(-sizeVar, sizeVar));
      p.color.set(pick(colors));
      p.gravity = gravity;
      p.drag = drag;
    }
  }

  update(dt) {
    const pos = this.geo.attributes.position.array;
    const col = this.geo.attributes.aColor.array;
    const siz = this.geo.attributes.aSize.array;
    const alp = this.geo.attributes.aAlpha.array;
    for (let i = 0; i < this.max; i++) {
      const p = this.data[i];
      if (!p || p.life <= 0) {
        alp[i] = 0;
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) { alp[i] = 0; continue; }
      const damp = Math.exp(-p.drag * dt);
      p.vel.multiplyScalar(damp);
      p.vel.y += p.gravity * dt;
      p.pos.addScaledVector(p.vel, dt);
      const t = p.life / p.maxLife;
      pos[i * 3] = p.pos.x; pos[i * 3 + 1] = p.pos.y; pos[i * 3 + 2] = p.pos.z;
      col[i * 3] = p.color.r; col[i * 3 + 1] = p.color.g; col[i * 3 + 2] = p.color.b;
      siz[i] = p.size * (0.5 + t * 0.6);
      alp[i] = Math.pow(t, 0.7);
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}

class AmbientField {
  constructor(scene, { count = 200, size = 0.05, color = 0xffe9b0, range = 38, height = 14, mode = 'dust', map = GLOW, opacity = 1 }) {
    this.scene = scene;
    this.count = count;
    this.range = range;
    this.height = height;
    this.mode = mode;
    this.opacity = opacity;
    this.base = [];
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const alphas = new Float32Array(count);
    const c = new THREE.Color();
    for (let i = 0; i < count; i++) {
      const b = new THREE.Vector3(rand(-range, range), rand(0, height), rand(-range, range));
      this.base.push({
        pos: b.clone(),
        phase: rand(0, Math.PI * 2),
        speed: rand(0.25, 1),
        size: size * rand(0.6, 1.6),
        color: c.clone().set(color).offsetHSL(rand(-0.03, 0.03), rand(-0.05, 0.05), rand(-0.08, 0.08)),
        alpha: rand(0.35, 1),
      });
      positions[i * 3] = b.x; positions[i * 3 + 1] = b.y; positions[i * 3 + 2] = b.z;
      colors[i * 3] = this.base[i].color.r; colors[i * 3 + 1] = this.base[i].color.g; colors[i * 3 + 2] = this.base[i].color.b;
      sizes[i] = this.base[i].size;
      alphas[i] = this.base[i].alpha;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aColor', new THREE.BufferAttribute(colors, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1).setUsage(THREE.DynamicDrawUsage));
    this.geo = geo;
    this.mat = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: map }, uScale: { value: 620 } },
      vertexShader: POINT_VERT,
      fragmentShader: POINT_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });
    this.points = new THREE.Points(geo, this.mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.time = rand(0, 100);
  }

  update(dt, playerPos) {
    this.time += dt;
    const pos = this.geo.attributes.position.array;
    const alp = this.geo.attributes.aAlpha.array;
    for (let i = 0; i < this.count; i++) {
      const b = this.base[i];
      let x, y, z;
      if (this.mode === 'dust') {
        b.pos.x += Math.sin(this.time * 0.16 + b.phase) * dt * 0.22;
        b.pos.y += Math.cos(this.time * 0.22 + b.phase) * dt * 0.16;
        b.pos.z += Math.sin(this.time * 0.13 + b.phase * 2) * dt * 0.18;
        x = b.pos.x + playerPos.x; y = b.pos.y; z = b.pos.z + playerPos.z;
        // wrap horizontally around player
        const dx = x - playerPos.x, dz = z - playerPos.z;
        if (Math.abs(dx) > this.range) { b.pos.x -= Math.sign(dx) * this.range * 2; }
        if (Math.abs(dz) > this.range) { b.pos.z -= Math.sign(dz) * this.range * 2; }
        x = b.pos.x + playerPos.x; z = b.pos.z + playerPos.z;
        if (y < -2) b.pos.y += this.height + 2;
        alp[i] = b.alpha * (0.55 + 0.45 * Math.sin(this.time * 0.7 + b.phase)) * this.opacity;
      } else if (this.mode === 'firefly') {
        x = b.pos.x + Math.sin(this.time * 0.35 * b.speed + b.phase) * 2.2 + playerPos.x;
        y = b.pos.y + Math.sin(this.time * 0.6 * b.speed + b.phase * 2) * 0.9 + 0.4;
        z = b.pos.z + Math.cos(this.time * 0.3 * b.speed + b.phase) * 2.2 + playerPos.z;
        alp[i] = b.alpha * (0.25 + 0.75 * Math.pow(Math.max(0, Math.sin(this.time * b.speed + b.phase)), 4)) * this.opacity;
      } else if (this.mode === 'petal') {
        b.pos.y -= dt * 0.45 * b.speed;
        b.pos.x += Math.sin(this.time * 0.5 + b.phase) * dt * 0.5;
        b.pos.z += Math.cos(this.time * 0.4 + b.phase) * dt * 0.35;
        if (b.pos.y < 0) b.pos.y = this.height;
        x = b.pos.x + playerPos.x; y = b.pos.y; z = b.pos.z + playerPos.z;
        alp[i] = b.alpha * 0.55 * this.opacity;
      } else if (this.mode === 'mote') {
        b.pos.y += dt * 0.28 * b.speed;
        if (b.pos.y > this.height) b.pos.y = 0;
        x = b.pos.x + playerPos.x + Math.sin(this.time * 0.4 + b.phase) * 0.8;
        y = b.pos.y;
        z = b.pos.z + playerPos.z + Math.cos(this.time * 0.3 + b.phase) * 0.8;
        alp[i] = b.alpha * (0.35 + 0.65 * Math.abs(Math.sin(this.time * 0.7 + b.phase))) * this.opacity;
      } else { // sparkle
        x = b.pos.x + playerPos.x;
        y = b.pos.y + Math.sin(this.time * 0.4 + b.phase) * 3;
        z = b.pos.z + playerPos.z;
        alp[i] = b.alpha * (0.1 + 0.9 * Math.pow(Math.max(0, Math.sin(this.time * 1.3 * b.speed + b.phase)), 8)) * this.opacity;
      }
      pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}

export class Effects {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.pool = new ParticlePool(scene, 2200);
    this.shockwaves = [];
    this.slashes = [];
    this.lines = [];
    this.shakeAmp = 0;
    this.shakeDur = 0;
    this.shakeTime = 0;
    this.shakePhase = 0;
    this.shakeOffset = new THREE.Vector3();
    this.time = 0;

    // ambient life fields
    this.dust = new AmbientField(scene, { count: 260, size: 0.055, color: 0xffe7b3, range: 34, height: 14, mode: 'dust', opacity: 0.55 });
    this.fireflies = new AmbientField(scene, { count: 95, size: 0.28, color: 0xb7ff9a, range: 28, height: 9, mode: 'firefly', opacity: 0.9 });
    this.petals = new AmbientField(scene, { count: 80, size: 0.16, color: 0xff9fb0, range: 30, height: 13, mode: 'petal', map: PETAL, opacity: 0.8 });
    this.motes = new AmbientField(scene, { count: 120, size: 0.17, color: 0x8ff9ff, range: 28, height: 16, mode: 'mote', opacity: 0.9 });
    this.sparkles = new AmbientField(scene, { count: 100, size: 0.22, color: 0xfff1c2, range: 26, height: 20, mode: 'sparkle', opacity: 0.7 });
    this.petals.points.visible = false;
    this.motes.points.visible = false;
    this.sparkles.points.visible = false;
    this.zone = 'meadow';
  }

  setZone(zone) {
    this.zone = zone;
    this.petals.points.visible = zone === 'ruins';
    this.motes.points.visible = zone === 'crystal';
    this.sparkles.points.visible = zone === 'sky';
    this.fireflies.points.visible = zone === 'meadow' || zone === 'sky';
    this.dust.points.visible = zone !== 'crystal';
    this.dust.mat.uniforms.uMap.value = GLOW;
  }

  /* ---------------- camera shake ---------------- */
  addShake(amount = 0.25, duration = 0.3) {
    this.shakeAmp = Math.max(this.shakeAmp, amount);
    this.shakeDur = Math.max(this.shakeDur, duration);
    this.shakeTime = Math.max(this.shakeTime, duration);
  }

  getShakeOffset() {
    return this.shakeOffset;
  }

  /* ---------------- bursts ---------------- */
  burst(position, opts = {}) {
    this.pool.spawn({ position, ...opts });
  }

  hitSpark(position, color = 0xffe3a0, count = 24) {
    this.pool.spawn({
      position, count, speed: 8.5, speedVar: 0.9, size: 0.14, sizeVar: 0.8,
      life: 0.35, lifeVar: 0.6, gravity: -12, drag: 2.2,
      colors: [color, 0xffffff, 0xffcf7a],
    });
  }

  enemyDeath(position, color = 0x9ef2c0) {
    this.pool.spawn({
      position, count: 46, speed: 7, size: 0.25, sizeVar: 0.9,
      life: 0.9, lifeVar: 0.6, gravity: -8, drag: 1.2,
      colors: [color, 0xffffff, 0xd7ffb0],
    });
    this.burst(position, {
      count: 16, speed: 2, size: 0.7, life: 0.6, gravity: 0.4, drag: 2,
      colors: [color, 0xffffff],
    });
    this.shockwave(position, { color, radius: 2.4, duration: 0.5, y: position.y - 0.6 });
  }

  collect(position, color = 0x8ff7ec) {
    this.pool.spawn({
      position, count: 34, speed: 5, size: 0.18, sizeVar: 0.8,
      life: 0.7, lifeVar: 0.5, gravity: 1.2, drag: 2.4,
      colors: [color, 0xffffff, 0xfff1b0],
    });
    this.shockwave(position, { color, radius: 1.4, duration: 0.45, y: position.y - 0.4 });
  }

  doubleJump(position) {
    this.pool.spawn({
      position, count: 26, speed: 4, direction: new THREE.Vector3(0, 1, 0), spread: 0.9,
      size: 0.2, life: 0.5, gravity: -2, drag: 2.4, colors: [0x8ff7ec, 0xffffff, 0x9fdfff],
    });
    this.shockwave(position, { color: 0x8ff7ec, radius: 1.8, duration: 0.4 });
  }

  dashTrail(position, color = 0x8ff7ec) {
    this.pool.spawn({
      position, count: 4, speed: 1.4, posVar: 0.28, size: 0.28, sizeVar: 0.7,
      life: 0.38, lifeVar: 0.5, gravity: 0.4, drag: 3,
      colors: [color, 0xb8fff6, 0xffffff],
    });
  }

  footstep(position, color = 0xcdbf9a) {
    this.pool.spawn({
      position, count: 4, speed: 0.8, direction: new THREE.Vector3(0, 1, 0), spread: 1,
      posVar: 0.14, size: 0.12, life: 0.35, gravity: -1, drag: 2.5, colors: [color, 0xe6dcc3],
    });
  }

  splash(position) {
    this.pool.spawn({
      position, count: 16, speed: 3.4, direction: new THREE.Vector3(0, 1, 0), spread: 0.8,
      posVar: 0.45, size: 0.11, life: 0.55, gravity: -9, drag: 1, colors: [0xd9ffff, 0x9fe6e2, 0xffffff],
    });
  }

  /* ---------------- shockwave rings ---------------- */
  shockwave(position, { color = 0xffd38c, radius = 4, duration = 0.7, y = null } = {}) {
    const geo = new THREE.TorusGeometry(1, 0.035, 6, 64);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending,
      depthWrite: false, toneMapped: false, side: THREE.DoubleSide,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(position);
    if (y !== null) mesh.position.y = y;
    mesh.scale.setScalar(0.2);
    this.scene.add(mesh);
    this.shockwaves.push({ mesh, life: duration, maxLife: duration, radius });
  }

  /* ---------------- slash arcs ---------------- */
  slash(position, yaw, { color = 0x9ffff4, scale = 1 } = {}) {
    const geo = new THREE.RingGeometry(0.45, 1.28, 32, 1, 0.3, Math.PI * 1.35);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.85, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.rotation.z = -yaw - Math.PI * 0.2;
    mesh.position.copy(position);
    mesh.position.y += 1.0;
    mesh.scale.setScalar(scale);
    mesh.renderOrder = 8;
    this.scene.add(mesh);
    this.slashes.push({ mesh, life: 0.22, maxLife: 0.22, yaw });
    const fwd = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
    this.pool.spawn({
      position: position.clone().addScaledVector(fwd, 1.2).add(new THREE.Vector3(0, 1.0, 0)),
      count: 10, speed: 3.5, size: 0.1, life: 0.28, gravity: 0, drag: 4,
      colors: [color, 0xffffff],
    });
  }

  /* ---------------- lightning ---------------- */
  lightning(from, to, { color = 0xd8feff, bolts = 3 } = {}) {
    const group = new THREE.Group();
    for (let b = 0; b < bolts; b++) {
      const pts = [];
      const segments = 10;
      for (let i = 0; i <= segments; i++) {
        const t = i / segments;
        const p = new THREE.Vector3().lerpVectors(from, to, t);
        if (i > 0 && i < segments) {
          p.x += rand(-1.5, 1.5) * (1 - Math.abs(t - 0.5));
          p.z += rand(-1.5, 1.5) * (1 - Math.abs(t - 0.5));
        }
        pts.push(p);
      }
      const geo = new THREE.BufferGeometry().setFromPoints(pts);
      const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
      group.add(new THREE.Line(geo, mat));
    }
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: GLOW, color, transparent: true, opacity: 0.85,
      blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
    }));
    glow.position.copy(to);
    glow.scale.setScalar(5);
    group.add(glow);
    this.scene.add(group);
    this.lines.push({ group, life: 0.32, maxLife: 0.32 });
    this.addShake(0.2, 0.25);
    this.pool.spawn({ position: to, count: 26, speed: 7, size: 0.18, life: 0.5, gravity: -5, colors: [color, 0xffffff] });
  }

  /* ---------------- update ---------------- */
  setZoneVisibility(zone) { this.setZone(zone); }

  update(dt, playerPos) {
    this.time += dt;
    this.pool.update(dt);
    this.dust.update(dt, playerPos);
    this.fireflies.update(dt, playerPos);
    if (this.petals.points.visible) this.petals.update(dt, playerPos);
    if (this.motes.points.visible) this.motes.update(dt, playerPos);
    if (this.sparkles.points.visible) this.sparkles.update(dt, playerPos);

    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const s = this.shockwaves[i];
      s.life -= dt;
      const t = clamp(1 - s.life / s.maxLife, 0, 1);
      const ease = 1 - Math.pow(1 - t, 2);
      s.mesh.scale.setScalar(0.2 + s.radius * ease);
      s.mesh.material.opacity = (1 - t) * 0.8;
      if (s.life <= 0) {
        this.scene.remove(s.mesh);
        s.mesh.geometry.dispose(); s.mesh.material.dispose();
        this.shockwaves.splice(i, 1);
      }
    }

    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.life -= dt;
      const t = clamp(1 - s.life / s.maxLife, 0, 1);
      s.mesh.scale.setScalar(0.85 + t * 0.5);
      s.mesh.rotation.z += dt * 4;
      s.mesh.material.opacity = (1 - t) * 0.85;
      if (s.life <= 0) {
        this.scene.remove(s.mesh);
        s.mesh.geometry.dispose(); s.mesh.material.dispose();
        this.slashes.splice(i, 1);
      }
    }

    for (let i = this.lines.length - 1; i >= 0; i--) {
      const l = this.lines[i];
      l.life -= dt;
      const a = clamp(l.life / l.maxLife, 0, 1);
      l.group.traverse((o) => { if (o.material) o.material.opacity = a; });
      if (l.life <= 0) {
        this.scene.remove(l.group);
        l.group.traverse((o) => { o.geometry?.dispose(); o.material?.dispose(); });
        this.lines.splice(i, 1);
      }
    }

    // camera shake
    if (this.shakeTime > 0) {
      this.shakeTime = Math.max(0, this.shakeTime - dt);
      const t = this.shakeTime / Math.max(0.0001, this.shakeDur);
      const amp = this.shakeAmp * t * t;
      this.shakePhase += dt * 57;
      this.shakeOffset.set(
        Math.sin(this.shakePhase * 1.7) * amp,
        Math.cos(this.shakePhase * 2.3) * amp * 0.8,
        Math.sin(this.shakePhase * 1.1) * amp * 0.6
      );
      if (this.shakeTime <= 0) { this.shakeAmp = 0; this.shakeDur = 0; this.shakeOffset.set(0, 0, 0); }
    } else {
      this.shakeOffset.set(0, 0, 0);
    }
  }

  updatePointScale(scale) {
    this.pool.mat.uniforms.uScale.value = scale;
    this.dust.mat.uniforms.uScale.value = scale;
    this.fireflies.mat.uniforms.uScale.value = scale;
    this.petals.mat.uniforms.uScale.value = scale;
    this.motes.mat.uniforms.uScale.value = scale;
    this.sparkles.mat.uniforms.uScale.value = scale;
  }
}

