/* ============================================================
   World objects — movable platforms, gates, portals,
   checkpoints and shard collectibles.
   ============================================================ */
import * as THREE from 'three';
import { makeRadialTexture, makeGlowSprite, damp, clamp, rand } from '../Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const GLOW_TEX = makeRadialTexture(96, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)', 0.15);

/* ---------------- moving platform ---------------- */
export class MovingPlatform {
  constructor(world, mesh, size, opts = {}) {
    this.world = world;
    this.mesh = mesh;
    this.size = size.clone();
    this.base = mesh.position.clone();
    this.axis = (opts.axis || V3(0, 1, 0)).clone().normalize();
    this.amplitude = opts.amplitude ?? 2;
    this.speed = opts.speed ?? 1;
    this.phase = opts.phase ?? 0;
    this.zone = opts.zone || 'meadow';
    this.delta = V3();
    this.prevPos = mesh.position.clone();
    this.collider = { box: new THREE.Box3(), kind: 'moving', active: true, platform: this };
    this._updateBox();
    world.colliders.push(this.collider);
    world.movingPlatforms.push(this);
  }

  _updateBox() {
    this.collider.box.setFromCenterAndSize(this.mesh.position, this.size);
  }

  update(time, dt) {
    this.prevPos.copy(this.mesh.position);
    const offset = Math.sin(time * this.speed + this.phase) * this.amplitude;
    this.mesh.position.copy(this.base).addScaledVector(this.axis, offset);
    this.delta.copy(this.mesh.position).sub(this.prevPos);
    this._updateBox();
  }
}

/* ---------------- ancient gate ---------------- */
export class Gate {
  constructor(world, {
    id, zone = 'meadow', position = V3(), width = 12, height = 7, depth = 1.0,
  }) {
    this.world = world;
    this.id = id;
    this.zone = zone;
    this.width = width;
    this.height = height;
    this.open = 0;
    this.target = 0;
    this.instant = false;

    const group = new THREE.Group();
    group.position.copy(position);
    const stone = world.materials.stoneDark;
    const metal = world.materials.darkMetal;

    // flanking pillars
    for (const sx of [-1, 1]) {
      const pillar = new THREE.Mesh(new THREE.BoxGeometry(1.5, height + 1.2, 1.8), stone);
      pillar.position.set(sx * (width / 2 + 0.2), (height + 1.2) / 2, 0);
      pillar.castShadow = pillar.receiveShadow = true;
      group.add(pillar);
      const cap = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.45, 2.2), stone);
      cap.position.set(sx * (width / 2 + 0.2), height + 1.2, 0);
      cap.castShadow = true;
      group.add(cap);
      // glowing rune strip
      const rune = new THREE.Mesh(
        new THREE.BoxGeometry(0.12, height * 0.55, 0.05),
        new THREE.MeshBasicMaterial({ color: 0xffd98a, transparent: true, opacity: 0.65, toneMapped: false })
      );
      rune.position.set(sx * (width / 2 + 0.2) - sx * 0.77, height * 0.5, 0.9);
      group.add(rune);
    }

    // arch
    const arch = new THREE.Mesh(new THREE.BoxGeometry(width + 2.2, 1.2, 1.9), stone);
    arch.position.set(0, height + 1.35, 0);
    arch.castShadow = arch.receiveShadow = true;
    group.add(arch);
    const crest = new THREE.Mesh(new THREE.ConeGeometry(1.25, 2.2, 4), world.materials.gold);
    crest.rotation.y = Math.PI / 4;
    crest.position.set(0, height + 2.9, 0);
    crest.castShadow = true;
    group.add(crest);

    // portcullis
    this.bars = new THREE.Group();
    this.bars.position.y = 0;
    const barGeo = new THREE.BoxGeometry(0.18, height, 0.22);
    for (let i = 0; i < 9; i++) {
      const bar = new THREE.Mesh(barGeo, metal);
      bar.position.set(-width / 2 + 0.75 + i * ((width - 1.5) / 8), height / 2, 0);
      bar.castShadow = true;
      this.bars.add(bar);
    }
    const crossGeo = new THREE.BoxGeometry(width - 1.0, 0.16, 0.24);
    for (let j = 1; j <= 4; j++) {
      const cross = new THREE.Mesh(crossGeo, metal);
      cross.position.set(0, (height / 4) * j, 0);
      this.bars.add(cross);
    }
    // runes on the portcullis
    const runeMat = new THREE.MeshBasicMaterial({ color: 0xffb864, transparent: true, opacity: 0.7, toneMapped: false });
    for (let j = 0; j < 3; j++) {
      const r = new THREE.Mesh(new THREE.TorusGeometry(0.32 + j * 0.16, 0.035, 5, 18, Math.PI * 1.3), runeMat);
      r.rotation.z = 0.3 + j;
      r.position.set(0, height * 0.5 + j * 0.18, 0.18);
      this.bars.add(r);
    }
    group.add(this.bars);
    this.group = group;
    world.scene.add(group);

    // collision is wider than the bars so the player can't slip around
    this.collider = { box: new THREE.Box3(), kind: 'gate', active: true, gate: this };
    this.collider.box.setFromCenterAndSize(
      V3(position.x, position.y + height / 2, position.z),
      V3(width + 1.8, height, depth + 1.2)
    );
    world.colliders.push(this.collider);
    world.gates.push(this);
    this.runeMat = runeMat;
  }

  setOpen(open, instant = false) {
    this.target = open ? 1 : 0;
    if (instant) {
      this.open = this.target;
      this._apply();
    }
  }

  _apply() {
    this.bars.position.y = this.open * (this.height + 1.4);
    this.collider.active = this.open < 0.55;
    this.runeMat.opacity = (1 - this.open) * 0.7;
  }

  update(dt) {
    if (this.open !== this.target) {
      this.open = damp(this.open, this.target, 2.2, dt);
      if (Math.abs(this.open - this.target) < 0.002) this.open = this.target;
      this._apply();
    }
  }
}

/* ---------------- zone portal ---------------- */
const PORTAL_FRAG = /* glsl */`
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;
  uniform float uUnlocked;
  varying vec2 vUv;
  float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
  float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p); vec2 u = f*f*(3.0-2.0*f);
    return mix(mix(hash(i), hash(i+vec2(1.0,0.0)), u.x), mix(hash(i+vec2(0.0,1.0)), hash(i+vec2(1.0,1.0)), u.x), u.y);
  }
  void main() {
    vec2 p = vUv * 2.0 - 1.0;
    float r = length(p);
    if (r > 1.0) discard;
    float a = atan(p.y, p.x);
    float swirl = noise(vec2(a * 2.4 + uTime * 0.7, r * 6.0 - uTime * 1.4));
    float swirl2 = noise(vec2(a * 4.0 - uTime * 0.4, r * 11.0 + uTime * 0.9));
    vec3 col = mix(uColorA, uColorB, swirl * 0.8 + 0.15);
    col += uColorB * pow(swirl2, 3.0) * 0.9;
    float edge = smoothstep(1.0, 0.78, r);
    float core = smoothstep(0.6, 0.0, r) * 0.5;
    float alpha = (0.34 + swirl * 0.3 + core) * edge;
    if (uUnlocked < 0.5) alpha *= 0.25;
    gl_FragColor = vec4(col, alpha);
  }
`;

export class Portal {
  constructor(world, {
    id, zone, targetZone, position = V3(), unlocked = false, label = '',
    colorA = 0x6ff5e7, colorB = 0xffe2a0,
  }) {
    this.world = world;
    this.id = id;
    this.zone = zone;
    this.targetZone = targetZone;
    this.position = position.clone();
    this.unlocked = unlocked;
    this.label = label;
    this.cooldown = 0;
    this.time = rand(0, 10);

    const group = new THREE.Group();
    group.position.copy(position);
    this.group = group;

    const baseMat = world.materials.stoneDark;
    const dais = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 3.8, 0.5, 24), baseMat);
    dais.position.y = 0.25;
    dais.receiveShadow = dais.castShadow = true;
    group.add(dais);
    const ringBase = new THREE.Mesh(new THREE.TorusGeometry(3.05, 0.12, 6, 48), world.materials.gold);
    ringBase.rotation.x = Math.PI / 2;
    ringBase.position.y = 0.55;
    group.add(ringBase);

    // runic outer ring
    this.ringMat = new THREE.MeshStandardMaterial({
      color: 0xd8cbb0, emissive: new THREE.Color(0x2a6f73), emissiveIntensity: 0.3,
      metalness: 0.65, roughness: 0.35,
    });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(2.85, 0.2, 8, 64), this.ringMat);
    ring.position.y = 3.4;
    group.add(ring);
    this.ring = ring;

    const glyphMat = new THREE.MeshBasicMaterial({ color: 0x8ff7ec, transparent: true, opacity: 0.25, toneMapped: false, blending: THREE.AdditiveBlending, depthWrite: false });
    this.glyphs = new THREE.Group();
    for (let i = 0; i < 10; i++) {
      const angle = (i / 10) * Math.PI * 2;
      const g = new THREE.Mesh(new THREE.TorusGeometry(0.19, 0.03, 4, 10, Math.PI * 1.4), glyphMat);
      g.position.set(Math.cos(angle) * 2.85, Math.sin(angle) * 2.85, 0);
      g.rotation.z = angle + Math.PI / 2;
      this.glyphs.add(g);
    }
    this.glyphs.position.y = 3.4;
    group.add(this.glyphs);
    this.glyphMat = glyphMat;

    // swirling face
    this.innerUniforms = {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(colorA) },
      uColorB: { value: new THREE.Color(colorB) },
      uUnlocked: { value: unlocked ? 1 : 0 },
    };
    const innerMat = new THREE.ShaderMaterial({
      uniforms: this.innerUniforms,
      vertexShader: `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
      fragmentShader: PORTAL_FRAG,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });
    const inner = new THREE.Mesh(new THREE.CircleGeometry(2.75, 48), innerMat);
    inner.position.set(0, 3.4, 0.08);
    group.add(inner);
    this.inner = inner;

    this.glow = makeGlowSprite({ color: colorA, size: 10, opacity: unlocked ? 0.36 : 0.06, texture: GLOW_TEX });
    this.glow.position.set(0, 3.4, 0.2);
    group.add(this.glow);

    this.light = new THREE.PointLight(colorA, unlocked ? 2.2 : 0.2, 20, 2);
    this.light.position.set(0, 3.4, 1.4);
    group.add(this.light);

    // marker beam visible from afar
    this.beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.16, 0.6, 26, 8, 1, true),
      new THREE.MeshBasicMaterial({ color: colorA, transparent: true, opacity: unlocked ? 0.11 : 0.02, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    );
    this.beam.position.y = 14;
    group.add(this.beam);

    world.scene.add(group);
    world.portals.push(this);
    this.setUnlocked(unlocked, true);
  }

  setUnlocked(unlocked, instant = false) {
    this.unlocked = unlocked;
    this.innerUniforms.uUnlocked.value = unlocked ? 1 : 0;
    this.ringMat.emissive.set(unlocked ? 0x2fbdb8 : 0x1a2f33);
    this.ringMat.emissiveIntensity = unlocked ? 1.4 : 0.25;
    this.glyphMat.opacity = unlocked ? 0.9 : 0.15;
    this.glow.material.opacity = unlocked ? 0.38 : 0.05;
    this.light.intensity = unlocked ? 2.2 : 0.15;
    this.beam.material.opacity = unlocked ? 0.1 : 0.015;
  }

  update(dt) {
    this.time += dt;
    this.innerUniforms.uTime.value = this.time;
    this.glyphs.rotation.z += dt * (this.unlocked ? 0.4 : 0.06);
    this.ring.rotation.z -= dt * (this.unlocked ? 0.15 : 0.03);
    const pulse = 0.85 + Math.sin(this.time * 2.2) * 0.15;
    this.light.intensity = (this.unlocked ? 2.2 : 0.15) * pulse;
    this.glow.material.opacity = (this.unlocked ? 0.36 : 0.05) * pulse;
    if (this.beam) this.beam.material.opacity = (this.unlocked ? 0.11 : 0.012) * (0.8 + Math.sin(this.time * 1.3) * 0.2);
    if (this.cooldown > 0) this.cooldown -= dt;
  }

  isPlayerInside(pos) {
    if (this.cooldown > 0) return false;
    const dx = pos.x - this.position.x, dz = pos.z - this.position.z;
    return dx * dx + dz * dz < 3.2 * 3.2 && Math.abs(pos.y - this.position.y) < 5;
  }
}

/* ---------------- checkpoint shrine ---------------- */
export class Checkpoint {
  constructor(world, { id, zone, position = V3(), name = 'Shrine' }) {
    this.world = world;
    this.id = id;
    this.zone = zone;
    this.name = name;
    this.position = position.clone();
    this.activated = false;
    this.time = rand(0, 10);

    const group = new THREE.Group();
    group.position.copy(position);
    this.group = group;

    const base = new THREE.Mesh(new THREE.CylinderGeometry(1.35, 1.7, 0.35, 16), world.materials.stone);
    base.position.y = 0.17; base.castShadow = base.receiveShadow = true;
    group.add(base);
    const inner = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.9, 0.12, 16), world.materials.stoneDark);
    inner.position.y = 0.38; inner.receiveShadow = true;
    group.add(inner);

    this.crystalMat = new THREE.MeshStandardMaterial({
      color: 0x507a7c, emissive: new THREE.Color(0x2a6f73), emissiveIntensity: 0.4,
      roughness: 0.2, metalness: 0.25, transparent: true, opacity: 0.9,
    });
    this.shard = new THREE.Mesh(new THREE.OctahedronGeometry(0.38, 0), this.crystalMat);
    this.shard.position.y = 1.55;
    this.shard.castShadow = true;
    group.add(this.shard);

    this.ringMat = new THREE.MeshBasicMaterial({ color: 0x7ff5e7, transparent: true, opacity: 0.25, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
    this.ring = new THREE.Mesh(new THREE.TorusGeometry(1.05, 0.025, 4, 32), this.ringMat);
    this.ring.rotation.x = Math.PI / 2;
    this.ring.position.y = 0.45;
    group.add(this.ring);

    this.glow = makeGlowSprite({ color: 0x9ff9ee, size: 3.2, opacity: 0.2, texture: GLOW_TEX });
    this.glow.position.y = 1.5;
    group.add(this.glow);

    this.light = new THREE.PointLight(0x9ff9ee, 0.25, 10, 2);
    this.light.position.y = 1.5;
    group.add(this.light);

    world.scene.add(group);
    world.checkpoints.push(this);
  }

  activate() {
    if (this.activated) return false;
    this.activated = true;
    this.crystalMat.color.set(0xffd98a);
    this.crystalMat.emissive.set(0xffb35c);
    this.crystalMat.emissiveIntensity = 1.8;
    this.ringMat.color.set(0xffdc93);
    this.ringMat.opacity = 0.7;
    this.glow.material.color.set(0xffdda0);
    this.glow.material.opacity = 0.55;
    this.light.color.set(0xffce74);
    this.light.intensity = 1.6;
    return true;
  }

  reset() {
    this.activated = false;
    this.crystalMat.color.set(0x507a7c);
    this.crystalMat.emissive.set(0x2a6f73);
    this.crystalMat.emissiveIntensity = 0.4;
    this.ringMat.color.set(0x7ff5e7);
    this.ringMat.opacity = 0.25;
    this.glow.material.color.set(0x9ff9ee);
    this.glow.material.opacity = 0.2;
    this.light.color.set(0x9ff9ee);
    this.light.intensity = 0.25;
  }

  update(dt) {
    this.time += dt;
    this.shard.position.y = 1.55 + Math.sin(this.time * 1.6) * 0.12;
    this.shard.rotation.y += dt * 0.9;
    this.ring.rotation.z += dt * 0.6;
    const p = 0.75 + Math.sin(this.time * 2.4) * 0.25;
    this.glow.material.opacity = (this.activated ? 0.55 : 0.2) * p;
    this.light.intensity = (this.activated ? 1.6 : 0.25) * p;
  }
}

/* ---------------- collectible shard ---------------- */
export class Gem {
  constructor(world, { id, zone, position = V3(), color = 0x8ff7ec, kind = 'shard' }) {
    this.world = world;
    this.id = id;
    this.zone = zone;
    this.position = position.clone();
    this.collected = false;
    this.time = rand(0, 10);
    this.color = color;

    const group = new THREE.Group();
    group.position.copy(position);
    this.group = group;

    this.coreMat = new THREE.MeshPhysicalMaterial({
      color, emissive: new THREE.Color(color).multiplyScalar(0.55), emissiveIntensity: 1.6,
      metalness: 0.1, roughness: 0.08, clearcoat: 1, clearcoatRoughness: 0.04,
      transparent: true, opacity: 0.94, envMapIntensity: 1.8,
    });
    this.core = new THREE.Mesh(new THREE.OctahedronGeometry(kind === 'heart' ? 0.4 : 0.32, 0), this.coreMat);
    this.core.castShadow = true;
    group.add(this.core);

    const haloMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
    this.halo = new THREE.Mesh(new THREE.TorusGeometry(0.55, 0.018, 4, 28), haloMat);
    this.halo.rotation.x = Math.PI / 2.2;
    group.add(this.halo);

    this.glow = makeGlowSprite({ color, size: 2.3, opacity: 0.45, texture: GLOW_TEX });
    group.add(this.glow);

    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.035, 0.11, 3.2, 5, 1, true),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.13, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    );
    beam.position.y = 1.3;
    group.add(beam);
    this.beam = beam;

    world.scene.add(group);
    world.gems.push(this);
  }

  collect() {
    if (this.collected) return false;
    this.collected = true;
    this.group.visible = false;
    return true;
  }

  restore() {
    this.collected = false;
    this.group.visible = true;
  }

  update(dt) {
    if (this.collected) return;
    this.time += dt;
    this.core.position.y = Math.sin(this.time * 2.1) * 0.16;
    this.core.rotation.y += dt * 1.8;
    this.core.rotation.z = Math.sin(this.time * 0.7) * 0.18;
    this.halo.position.y = this.core.position.y;
    this.halo.rotation.z -= dt * 0.9;
    this.halo.rotation.y += dt * 0.4;
    const p = 0.8 + Math.sin(this.time * 3.1) * 0.2;
    this.glow.material.opacity = 0.4 * p;
    this.beam.material.opacity = 0.1 * p;
  }
}

/* ---------------- world-space rune decal ---------------- */
export class RuneCircle {
  constructor(world, { position = V3(), radius = 9, color = 0xffd28a, opacity = 0.5, speed = 0.05 }) {
    this.group = new THREE.Group();
    this.group.position.copy(position);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
    this.mat = mat;
    for (const r of [radius, radius * 0.72, radius * 0.34]) {
      const ring = new THREE.Mesh(new THREE.RingGeometry(r - 0.035, r, 96), mat);
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = 0.03;
      this.group.add(ring);
    }
    // radial glyphs
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * Math.PI * 2;
      const g = new THREE.Mesh(new THREE.PlaneGeometry(0.14, Math.min(0.9, radius * 0.12)), mat);
      g.rotation.x = -Math.PI / 2;
      g.rotation.z = -a;
      g.position.set(Math.cos(a) * radius * 0.85, 0.035, Math.sin(a) * radius * 0.85);
      this.group.add(g);
    }
    this.speed = speed;
    world.scene.add(this.group);
    world.runeCircles.push(this);
  }

  update(dt, time) {
    this.group.rotation.y = time * this.speed;
    const p = 0.65 + Math.sin(time * 1.1) * 0.2;
    this.mat.opacity = p * 0.65;
  }
}

/* ============================================================
   Props — reusable environment builders: LOD trees, instanced
   grass/flowers, rocks, ruin architecture, crystals, water,
   sky islands, cloud platforms, wind columns and waterfalls.
   ============================================================ */
import * as THREE from 'three';
import { makeRadialTexture, makeGlowSprite, rand, randInt, clamp, TAU, setShadows } from '../Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);
const GLOW = makeRadialTexture(96, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)', 0.16);

/* ============================================================
   Trees (LOD + wind sway)
   ============================================================ */
function buildCanopy(world, detail, palette) {
  const group = new THREE.Group();
  const mats = palette.map((c) => new THREE.MeshStandardMaterial({
    color: c, roughness: 0.9, metalness: 0.0, flatShading: true, envMapIntensity: 0.7,
  }));
  const count = detail === 'high' ? 7 : 2;
  for (let i = 0; i < count; i++) {
    const isTop = i === 0;
    const r = isTop ? rand(2.0, 2.8) : rand(1.15, 2.15);
    const geo = new THREE.IcosahedronGeometry(r, detail === 'high' ? 1 : 0);
    const leaf = new THREE.Mesh(geo, mats[i % mats.length]);
    const angle = rand(0, TAU);
    const dist = isTop ? 0 : rand(0.8, 2.1);
    leaf.position.set(
      Math.cos(angle) * dist,
      (isTop ? 6.1 : rand(4.1, 6.0)),
      Math.sin(angle) * dist
    );
    leaf.scale.y = rand(0.8, 1.15);
    leaf.rotation.set(rand(0, 1), rand(0, TAU), rand(0, 1));
    leaf.castShadow = detail === 'high';
    leaf.receiveShadow = true;
    group.add(leaf);
  }
  return group;
}

export function createTree(world, x, y, z, opts = {}) {
  const scale = opts.scale ?? 1;
  const palette = opts.palette || [0x4d8c45, 0x5fa34e, 0x6fb75a, 0x3f7a42];
  const high = new THREE.Group();
  const low = new THREE.Group();
  const trunkMat = world.materials.wood;
  const trunkGeo = new THREE.CylinderGeometry(0.24, 0.46, 4.6, 8);
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = 2.3;
  trunk.castShadow = trunk.receiveShadow = true;
  high.add(trunk);
  const trunkLow = new THREE.Mesh(trunkGeo, trunkMat);
  trunkLow.position.y = 2.3;
  trunkLow.castShadow = true;
  low.add(trunkLow);

  // a few branches
  for (let i = 0; i < 3; i++) {
    const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.17, rand(1.6, 2.4), 6), trunkMat);
    const a = rand(0, TAU);
    branch.position.set(Math.cos(a) * 0.55, rand(3.0, 4.2), Math.sin(a) * 0.55);
    branch.rotation.z = Math.cos(a) * 0.9;
    branch.rotation.x = -Math.sin(a) * 0.9;
    branch.castShadow = true;
    high.add(branch);
  }

  const canopyHigh = buildCanopy(world, 'high', palette);
  const canopyLow = buildCanopy(world, 'low', palette);
  high.add(canopyHigh);
  low.add(canopyLow);

  const lod = new THREE.LOD();
  lod.position.set(x, y, z);
  lod.addLevel(high, 0);
  lod.addLevel(low, 46);
  lod.scale.setScalar(scale);
  world.scene.add(lod);
  world.trees.push({ lod, canopyHigh, canopyLow, phase: rand(0, TAU), amp: rand(0.008, 0.02) });

  if (opts.collide !== false) {
    world.addCollider(x, y + 2.3 * scale, z, 1.0 * scale, 4.6 * scale, 1.0 * scale, 'solid');
  }
  return lod;
}

/* ============================================================
   Rocks & ruin architecture
   ============================================================ */
export function createRock(world, x, y, z, scale = 1, opts = {}) {
  const geo = new THREE.DodecahedronGeometry(scale, 0);
  const mesh = new THREE.Mesh(geo, opts.material || world.materials.rock);
  mesh.position.set(x, y + scale * 0.55, z);
  mesh.scale.set(rand(0.8, 1.5), rand(0.55, 1.05), rand(0.8, 1.4));
  mesh.rotation.set(rand(0, 0.6), rand(0, TAU), rand(0, 0.6));
  mesh.castShadow = mesh.receiveShadow = true;
  world.scene.add(mesh);
  if (opts.collide) {
    const s = scale * 1.2;
    world.addCollider(mesh.position.x, y + s * 0.5, mesh.position.z, s, s, s, 'solid');
  }
  return mesh;
}

export function createColumn(world, x, y, z, opts = {}) {
  const height = opts.height ?? 6;
  const radius = opts.radius ?? 0.65;
  const mat = opts.material || world.materials.stone;
  const broken = opts.broken ?? false;
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const base = new THREE.Mesh(new THREE.CylinderGeometry(radius * 1.35, radius * 1.55, 0.5, 10), mat);
  base.position.y = 0.25; base.castShadow = base.receiveShadow = true;
  group.add(base);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.92, radius, height, 12), mat);
  shaft.position.y = height / 2 + 0.4;
  shaft.castShadow = shaft.receiveShadow = true;
  group.add(shaft);
  if (!broken) {
    const cap = new THREE.Mesh(new THREE.BoxGeometry(radius * 3.1, 0.42, radius * 3.1), mat);
    cap.position.y = height + 0.6;
    cap.castShadow = true;
    group.add(cap);
    const cap2 = new THREE.Mesh(new THREE.BoxGeometry(radius * 2.2, 0.24, radius * 2.2), world.materials.gold);
    cap2.position.y = height + 0.9;
    group.add(cap2);
    const rune = new THREE.Mesh(
      new THREE.TorusGeometry(radius * 0.5, 0.035, 4, 16, Math.PI * 1.4),
      new THREE.MeshBasicMaterial({ color: 0xffd28a, transparent: true, opacity: 0.55, toneMapped: false })
    );
    rune.position.set(0, height * 0.6, radius * 0.95);
    group.add(rune);
  } else {
    // jagged broken crown
    for (let i = 0; i < 3; i++) {
      const chunk = new THREE.Mesh(new THREE.DodecahedronGeometry(radius * rand(0.25, 0.5), 0), mat);
      chunk.position.set(rand(-radius, radius), height + rand(0.3, 0.8), rand(-radius, radius));
      chunk.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
      chunk.castShadow = true;
      group.add(chunk);
    }
  }
  world.scene.add(group);
  if (opts.collide !== false) {
    world.addCollider(x, y + height / 2 + 0.4, z, radius * 2.1, height, radius * 2.1, 'solid');
  }
  return group;
}

export function createArch(world, x, y, z, opts = {}) {
  const width = opts.width ?? 7;
  const height = opts.height ?? 5.5;
  const mat = opts.material || world.materials.stone;
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const torus = new THREE.Mesh(new THREE.TorusGeometry(width / 2, 0.35, 8, 24, Math.PI), mat);
  torus.position.y = height;
  torus.castShadow = true;
  group.add(torus);
  // keystone
  const key = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.8, 0.8), world.materials.gold);
  key.position.y = height + width / 2;
  key.castShadow = true;
  group.add(key);
  world.scene.add(group);
  createColumn(world, x - width / 2, y, z, { height, radius: 0.42, material: mat });
  createColumn(world, x + width / 2, y, z, { height, radius: 0.42, material: mat });
  return group;
}

export function createRuinWall(world, x, y, z, opts = {}) {
  const width = opts.width ?? 8;
  const height = opts.height ?? 4;
  const depth = opts.depth ?? 0.8;
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const segments = Math.max(3, Math.floor(width / 1.2));
  const mat = world.materials.stone;
  for (let i = 0; i < segments; i++) {
    const h = height * rand(0.45, 1.0);
    const seg = new THREE.Mesh(new THREE.BoxGeometry(width / segments * 0.98, h, depth), mat);
    seg.position.set(-width / 2 + (i + 0.5) * (width / segments), h / 2, rand(-0.1, 0.1));
    seg.rotation.y = rand(-0.03, 0.03);
    seg.castShadow = seg.receiveShadow = true;
    group.add(seg);
  }
  world.scene.add(group);
  world.addCollider(x, y + height * 0.45, z, width, height * 0.9, depth + 0.2, 'solid');
  return group;
}

/* ============================================================
   Crystals
   ============================================================ */
export function createCrystalCluster(world, x, y, z, opts = {}) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const color = opts.color ?? 0x6ff7ea;
  const color2 = opts.color2 ?? 0xbd8fff;
  const scale = opts.scale ?? 1;
  const mat = new THREE.MeshPhysicalMaterial({
    color, emissive: new THREE.Color(color).multiplyScalar(0.5), emissiveIntensity: 1.4,
    metalness: 0.15, roughness: 0.07, clearcoat: 1, clearcoatRoughness: 0.05,
    transparent: true, opacity: 0.93, envMapIntensity: 1.8, flatShading: true,
  });
  const mat2 = mat.clone();
  mat2.color.set(color2); mat2.emissive.set(new THREE.Color(color2).multiplyScalar(0.5));
  const count = opts.count ?? randInt(4, 8);
  for (let i = 0; i < count; i++) {
    const h = rand(1.2, 5.4) * scale;
    const r = rand(0.22, 0.65) * scale;
    const geo = new THREE.ConeGeometry(r, h, randInt(4, 6));
    const shard = new THREE.Mesh(geo, i % 3 === 0 ? mat2 : mat);
    const a = rand(0, TAU);
    const d = rand(0, 1.3) * scale;
    shard.position.set(Math.cos(a) * d, h / 2, Math.sin(a) * d);
    shard.rotation.z = rand(-0.3, 0.3);
    shard.rotation.x = rand(-0.25, 0.25);
    shard.castShadow = true;
    shard.receiveShadow = true;
    group.add(shard);
  }
  const glow = makeGlowSprite({ color, size: 7 * scale, opacity: 0.22, texture: GLOW });
  glow.position.y = 1.8 * scale;
  group.add(glow);
  if (opts.light) {
    const light = new THREE.PointLight(color, opts.lightIntensity ?? 2.5, opts.lightDistance ?? 24, 2);
    light.position.set(0, 3 * scale, 0);
    group.add(light);
    world.crystalLights.push({ light, phase: rand(0, TAU), base: light.intensity });
  }
  world.scene.add(group);
  world.crystalClusters.push({ mat, mat2, phase: rand(0, TAU), base: 1.4 });
  if (opts.collide) {
    const s = 2.0 * scale;
    world.addCollider(x, y + s * 0.45, z, s, s * 0.9, s, 'solid');
  }
  return group;
}

/* ============================================================
   Instanced grass / flowers / bushes
   ============================================================ */
function makeBladeGeometry() {
  const geo = new THREE.BufferGeometry();
  const positions = new Float32Array([
    -0.055, 0, 0, 0.055, 0, 0, 0.0, 0.72, 0.02,
    0, 0, -0.055, 0, 0, 0.055, 0.01, 0.72, 0,
  ]);
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.computeVertexNormals();
  return geo;
}

export function createGrassField(world, samples, opts = {}) {
  if (!samples.length) return null;
  const geo = makeBladeGeometry();
  const mat = world.grassMaterial;
  const mesh = new THREE.InstancedMesh(geo, mat, samples.length);
  mesh.frustumCulled = false;
  mesh.receiveShadow = true;
  mesh.castShadow = false;
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  const palette = opts.palette || [0x6faa52, 0x82b95a, 0x95c96a, 0x5d9448, 0xa7cc70];
  for (let i = 0; i < samples.length; i++) {
    const s = samples[i];
    dummy.position.set(s.x, s.y, s.z);
    dummy.rotation.y = rand(0, TAU);
    const sc = (s.scale ?? 1) * rand(0.7, 1.45);
    dummy.scale.set(sc, sc * rand(0.7, 1.3), sc);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
    color.set(palette[randInt(0, palette.length - 1)]).offsetHSL(rand(-0.02, 0.02), 0, rand(-0.06, 0.06));
    mesh.setColorAt(i, color);
  }
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  world.scene.add(mesh);
  world.instanced.push(mesh);
  return mesh;
}

export function createFlowerField(world, samples) {
  if (!samples.length) return null;
  const geo = new THREE.IcosahedronGeometry(0.12, 0);
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.6, emissive: 0x221100, emissiveIntensity: 0.4 });
  const mesh = new THREE.InstancedMesh(geo, mat, samples.length);
  mesh.frustumCulled = false;
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  const palette = [0xffd36e, 0xff9fbe, 0xcfa8ff, 0xfff0c0, 0xffb078];
  for (let i = 0; i < samples.length; i++) {
    const s = samples[i];
    dummy.position.set(s.x, s.y + 0.22, s.z);
    dummy.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    const sc = rand(0.6, 1.5);
    dummy.scale.setScalar(sc);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
    color.set(palette[randInt(0, palette.length - 1)]);
    mesh.setColorAt(i, color);
  }
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  world.scene.add(mesh);
  world.instanced.push(mesh);
  return mesh;
}

export function createBush(world, x, y, z, scale = 1) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const mat = world.materials.leafBush;
  for (let i = 0; i < 4; i++) {
    const r = rand(0.5, 0.95) * scale;
    const b = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 1), mat);
    b.position.set(rand(-0.5, 0.5) * scale, rand(0.3, 0.9) * scale, rand(-0.5, 0.5) * scale);
    b.scale.y = rand(0.7, 1.1);
    b.castShadow = true; b.receiveShadow = true;
    group.add(b);
  }
  world.scene.add(group);
  return group;
}

/* ============================================================
   Water
   ============================================================ */
const WATER_FRAG = /* glsl */`
  uniform float uTime;
  uniform vec3 uDeep;
  uniform vec3 uShallow;
  uniform vec3 uSunColor;
  uniform vec3 uSky;
  varying vec2 vUv;
  varying vec3 vWorld;
  float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
  float noise(vec2 p){
    vec2 i=floor(p), f=fract(p); vec2 u=f*f*(3.0-2.0*f);
    return mix(mix(hash(i),hash(i+vec2(1.0,0.0)),u.x), mix(hash(i+vec2(0.0,1.0)),hash(i+vec2(1.0,1.0)),u.x),u.y);
  }
  float waves(vec2 p){
    float t=uTime*0.7;
    return sin(p.x*3.1+t)*0.5 + sin(p.y*4.3-t*1.3)*0.5 + noise(p*2.4+vec2(t*0.4,-t*0.3))*0.9;
  }
  void main(){
    vec2 uv = vUv;
    vec2 p = uv * 7.0;
    float n = waves(p);
    float n2 = waves(p*1.9 + 3.0);
    vec3 normal = normalize(vec3((n-n2)*0.045, 1.0, (n2-n)*0.045));
    vec3 viewDir = normalize(cameraPosition - vWorld);
    float fres = pow(1.0 - max(dot(normal, viewDir), 0.0), 3.0);
    vec3 sunDir = normalize(vec3(0.5, 0.75, 0.35));
    vec3 halfV = normalize(viewDir + sunDir);
    float spec = pow(max(dot(normal, halfV), 0.0), 220.0) * 1.8;
    float ripple = smoothstep(0.55, 0.95, n*0.5+0.5);
    vec3 col = mix(uDeep, uShallow, 0.35 + ripple * 0.3);
    col = mix(col, uSky, fres * 0.65);
    col += uSunColor * spec;
    float edge = smoothstep(1.0, 0.72, length(uv - 0.5) * 1.8);
    float foam = smoothstep(0.72, 0.98, ripple) * edge;
    col += vec3(0.7, 0.95, 0.92) * foam * 0.18;
    float alpha = 0.68 + fres * 0.22;
    gl_FragColor = vec4(col, alpha);
  }
`;

const WATER_VERT = /* glsl */`
  uniform float uTime;
  varying vec2 vUv;
  varying vec3 vWorld;
  void main(){
    vUv = uv;
    vec3 pos = position;
    float w = sin(pos.x*1.7 + uTime*0.8)*0.035 + sin(pos.y*2.1 - uTime*0.6)*0.03;
    pos.z += w;
    vec4 world = modelMatrix * vec4(pos, 1.0);
    vWorld = world.xyz;
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

export function createWater(world, x, y, z, radius, opts = {}) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const uniforms = {
    uTime: { value: 0 },
    uDeep: { value: new THREE.Color(opts.deep ?? 0x0e4a52) },
    uShallow: { value: new THREE.Color(opts.shallow ?? 0x2f9e91) },
    uSunColor: { value: new THREE.Color(0xffe6b0) },
    uSky: { value: new THREE.Color(0xbfe6e2) },
  };
  const mat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: WATER_VERT,
    fragmentShader: WATER_FRAG,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  const geo = new THREE.CircleGeometry(radius, 72, 0, TAU);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.y = 0.03;
  mesh.renderOrder = 3;
  group.add(mesh);

  const bottom = new THREE.Mesh(
    new THREE.CircleGeometry(radius * 0.98, 48),
    new THREE.MeshStandardMaterial({ color: opts.bottom ?? 0x183d34, roughness: 1 })
  );
  bottom.rotation.x = -Math.PI / 2;
  bottom.position.y = -0.08;
  bottom.receiveShadow = true;
  group.add(bottom);

  // edge stones
  const rockMat = world.materials.rock;
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * TAU + rand(-0.1, 0.1);
    const rr = radius * rand(0.95, 1.07);
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(0.3, 0.9), 0), rockMat);
    rock.position.set(Math.cos(a) * rr, rand(-0.16, 0.05), Math.sin(a) * rr);
    rock.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    rock.castShadow = rock.receiveShadow = true;
    group.add(rock);
  }

  world.scene.add(group);
  world.waters.push({ group, uniforms, mesh, radius, center: V3(x, y, z) });
  return group;
}

/* ============================================================
   Sky islands, cloud platforms, wind, waterfalls
   ============================================================ */
export function createSkyIsland(world, cx, topY, cz, w, d, opts = {}) {
  const group = new THREE.Group();
  group.position.set(cx, 0, cz);
  const rockMat = world.materials.rock;
  const grass = world.materials.grassTopIsland;

  const top = new THREE.Mesh(new THREE.PlaneGeometry(w, d), grass);
  top.rotation.x = -Math.PI / 2;
  top.position.y = topY;
  top.receiveShadow = true;
  group.add(top);

  const cap = new THREE.Mesh(new THREE.BoxGeometry(w, 1.8, d), rockMat);
  cap.position.y = topY - 0.9;
  cap.castShadow = cap.receiveShadow = true;
  group.add(cap);

  // inverted rock keel
  const depth = opts.depth ?? Math.min(w, d) * rand(0.55, 0.85);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(Math.min(w, d) * 0.46, depth, 9), rockMat);
  cone.rotation.x = Math.PI;
  cone.position.y = topY - 1.8 - depth / 2;
  cone.rotation.y = rand(0, TAU);
  cone.castShadow = true;
  group.add(cone);
  for (let i = 0; i < 5; i++) {
    const chunk = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(0.8, 2.2), 0), rockMat);
    chunk.position.set(rand(-w * 0.33, w * 0.33), topY - rand(1.5, 5), rand(-d * 0.33, d * 0.33));
    chunk.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    chunk.castShadow = true;
    group.add(chunk);
  }
  // jagged rim stones
  for (let i = 0; i < Math.floor((w + d) * 0.55); i++) {
    const edge = randInt(0, 3);
    const a = rand(0, TAU);
    const rw = w / 2 - rand(0.2, 1.2), rd = d / 2 - rand(0.2, 1.2);
    let px = Math.cos(a) * rw, pz = Math.sin(a) * rd;
    if (edge === 0) pz = -d / 2 + rand(0, 0.6);
    if (edge === 1) pz = d / 2 - rand(0, 0.6);
    if (edge === 2) px = -w / 2 + rand(0, 0.6);
    if (edge === 3) px = w / 2 - rand(0, 0.6);
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(0.35, 1.1), 0), rockMat);
    rock.position.set(px, topY + rand(-0.1, 0.25), pz);
    rock.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    rock.castShadow = rock.receiveShadow = true;
    group.add(rock);
  }

  world.scene.add(group);
  world.addCollider(cx, topY - 2.0, cz, w, 4.0, d, 'solid');
  if (opts.hangVines) {
    for (let i = 0; i < 7; i++) {
      const vine = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.05, rand(2, 6), 4), world.materials.vines);
      vine.position.set(rand(-w / 2, w / 2), topY - rand(2, 5), rand(-d / 2, d / 2));
      vine.rotation.z = rand(-0.15, 0.15);
      group.add(vine);
    }
  }
  return { group, top: topY };
}

export function createCloudPlatform(world, x, y, z, w, d, opts = {}) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const mat = world.materials.cloud;
  const blobs = 6;
  for (let i = 0; i < blobs; i++) {
    const geo = new THREE.SphereGeometry(rand(1.0, 2.0), 12, 8);
    const b = new THREE.Mesh(geo, mat);
    b.position.set(rand(-w * 0.35, w * 0.35), rand(-0.25, 0.2), rand(-d * 0.3, d * 0.3));
    b.scale.y = 0.45;
    b.castShadow = false;
    b.receiveShadow = true;
    group.add(b);
  }
  const top = new THREE.Mesh(new THREE.BoxGeometry(w * 0.9, 0.25, d * 0.75), mat);
  top.position.y = 0.35;
  top.receiveShadow = true;
  group.add(top);
  world.scene.add(group);

  const collider = { box: new THREE.Box3(), kind: 'solid', active: true };
  collider.box.setFromCenterAndSize(V3(x, y + 0.35, z), V3(w * 0.9, 0.5, d * 0.75));
  world.colliders.push(collider);
  if (opts.moving) {
    const platform = new (world.MovingPlatformClass)(world, group, V3(w * 0.9, 0.6, d * 0.75), {
      axis: opts.axis || V3(0, 1, 0), amplitude: opts.amplitude ?? 1.5,
      speed: opts.speed ?? 0.8, phase: opts.phase ?? 0, zone: opts.zone || 'sky',
    });
    world.colliders = world.colliders.filter((c) => c !== collider);
    return platform;
  }
  return group;
}

export function createWindColumn(world, x, y, z, radius, height, opts = {}) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const mat = new THREE.MeshBasicMaterial({
    color: opts.color ?? 0xcafcff, transparent: true, opacity: 0.12,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false,
    map: world.cloudTex,
  });
  if (mat.map) { mat.map = mat.map.clone(); mat.map.wrapS = mat.map.wrapT = THREE.RepeatWrapping; mat.map.repeat.set(2, 3); mat.map.needsUpdate = true; }
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.75, radius, height, 20, 1, true), mat);
  mesh.position.y = height / 2;
  group.add(mesh);
  for (let i = 0; i < 3; i++) {
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(radius * rand(0.6, 0.95), 0.04, 4, 28),
      new THREE.MeshBasicMaterial({ color: 0xd6ffff, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = rand(1, height - 1);
    group.add(ring);
  }
  world.scene.add(group);
  world.windZones.push({ x, y, z, radius, height, strength: opts.strength ?? 34 });
  world.windVisuals.push({ mesh, mat, time: rand(0, 10) });
  return group;
}

export function createWaterfall(world, x, y, z, w, h, opts = {}) {
  const tex = world.cloudTex.clone();
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(1, 4);
  tex.needsUpdate = true;
  const mat = new THREE.MeshBasicMaterial({
    map: tex, color: opts.color ?? 0xcdfcff, transparent: true, opacity: 0.5,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false,
  });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  mesh.position.set(x, y - h / 2, z);
  mesh.rotation.y = opts.rotation ?? 0;
  world.scene.add(mesh);
  world.waterfalls.push({ mesh, tex, speed: opts.speed ?? 0.4 });
  return mesh;
}

/* ============================================================
   Small decorations
   ============================================================ */
export function createBrazier(world, x, y, z, opts = {}) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.35, 0.5, 10), world.materials.stoneDark);
  bowl.position.y = 0.9; bowl.castShadow = true;
  group.add(bowl);
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.28, 0.8, 8), world.materials.stoneDark);
  stem.position.y = 0.45; group.add(stem);
  const glow = makeGlowSprite({ color: opts.color ?? 0xffc46a, size: 2.2, opacity: 0.7, texture: GLOW });
  glow.position.y = 1.25;
  group.add(glow);
  const light = new THREE.PointLight(opts.color ?? 0xffb45e, 2.0, 12, 2);
  light.position.y = 1.4;
  group.add(light);
  world.scene.add(group);
  world.braziers.push({ glow, light, phase: rand(0, TAU), base: 2.0 });
  return group;
}

export function createLantern(world, x, y, z, opts = {}) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.1, 2.1, 6), world.materials.wood);
  post.position.y = 1.05; post.castShadow = true; group.add(post);
  const orb = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8), new THREE.MeshBasicMaterial({ color: opts.color ?? 0xffd98a, toneMapped: false }));
  orb.position.y = 2.2; group.add(orb);
  const glow = makeGlowSprite({ color: opts.color ?? 0xffd98a, size: 1.8, opacity: 0.55, texture: GLOW });
  glow.position.y = 2.2; group.add(glow);
  const light = new THREE.PointLight(opts.color ?? 0xffc46a, 0.8, 8, 2);
  light.position.y = 2.2; group.add(light);
  world.scene.add(group);
  world.lanterns.push({ group, glow, light, phase: rand(0, TAU) });
  return group;
}

export function createLilyPads(world, x, y, z, radius, count = 10) {
  const mat = new THREE.MeshStandardMaterial({ color: 0x4f9c59, roughness: 0.8, side: THREE.DoubleSide });
  for (let i = 0; i < count; i++) {
    const a = rand(0, TAU), r = rand(1, radius * 0.85);
    const pad = new THREE.Mesh(new THREE.CircleGeometry(rand(0.25, 0.65), 10, 0, Math.PI * 1.75), mat);
    pad.rotation.x = -Math.PI / 2;
    pad.rotation.z = rand(0, TAU);
    pad.position.set(x + Math.cos(a) * r, y + 0.08, z + Math.sin(a) * r);
    pad.receiveShadow = true;
    world.scene.add(pad);
  }
}

export function createStatue(world, x, y, z) {
  const group = new THREE.Group();
  group.position.set(x, y, z);
  const base = new THREE.Mesh(new THREE.CylinderGeometry(2.6, 3.2, 1.2, 12), world.materials.stoneDark);
  base.position.y = 0.6; base.castShadow = base.receiveShadow = true; group.add(base);
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 1.1, 4.4, 8), world.materials.stone);
  body.position.y = 3.4; body.castShadow = true; group.add(body);
  const head = new THREE.Mesh(new THREE.IcosahedronGeometry(0.85, 0), world.materials.stone);
  head.position.y = 5.9; head.castShadow = true; group.add(head);
  const halo = new THREE.Mesh(new THREE.TorusGeometry(1.15, 0.07, 4, 32), new THREE.MeshBasicMaterial({ color: 0xffd98a, transparent: true, opacity: 0.65, toneMapped: false }));
  halo.position.y = 6.3; group.add(halo);
  const wingL = new THREE.Mesh(new THREE.ConeGeometry(0.55, 3.4, 4), world.materials.stone);
  wingL.position.set(-1.3, 4.2, 0); wingL.rotation.z = 0.45; wingL.castShadow = true; group.add(wingL);
  const wingR = wingL.clone(); wingR.position.x = 1.3; wingR.rotation.z = -0.45; group.add(wingR);
  world.scene.add(group);
  world.addCollider(x, y + 1.2, z, 5, 2.4, 5, 'solid');
  return group;
}

/* ============================================================
   World — assembles the four connected zones, owns all collision
   AABBs, collectibles, shrines, gates and portals.
   Zones are built in ./world/*.js for clarity.
   ============================================================ */
import * as THREE from 'three';
import {
  makeMottleTexture, makeNormalTexture, makeGrainTexture, makeCloudTexture,
  makeGlowSprite, rand, randInt, clamp, TAU,
} from './Utils.js';
import { MovingPlatform, Gate, Portal, Checkpoint, Gem, RuneCircle } from './world/Objects.js';
import {
  createTree, createRock, createColumn, createArch, createRuinWall, createCrystalCluster,
  createGrassField, createFlowerField, createBush, createWater, createSkyIsland,
  createCloudPlatform, createWindColumn, createWaterfall, createBrazier, createLantern,
  createLilyPads, createStatue,
} from './world/Props.js';
import { buildMeadow } from './world/meadow.js';
import { buildRuins } from './world/ruins.js';
import { buildCrystal } from './world/crystal.js';
import { buildSky } from './world/sky.js';

export const ZONES = {
  meadow: { name: 'Sunlit Meadow', sub: 'Where the world wakes', color: 0x9fe4a8 },
  ruins: { name: 'Ancient Ruins', sub: 'Stones that remember the sun', color: 0xffd08a },
  crystal: { name: 'Crystal Caverns', sub: 'Light sleeping under the earth', color: 0x8ff7ff },
  sky: { name: 'Skybound Isles', sub: 'The last road to dawn', color: 0xfff1c2 },
};

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

export class World {
  constructor(scene, environment) {
    this.scene = scene;
    this.environment = environment;
    this.time = 0;

    this.colliders = [];
    this.movingPlatforms = [];
    this.gems = [];
    this.checkpoints = [];
    this.portals = [];
    this.gates = [];
    this.hazards = [];
    this.enemySpawns = [];
    this.bossSpawns = {};
    this.windZones = [];
    this.windVisuals = [];
    this.waterfalls = [];
    this.waters = [];
    this.braziers = [];
    this.lanterns = [];
    this.runeCircles = [];
    this.crystalLights = [];
    this.crystalClusters = [];
    this.trees = [];
    this.instanced = [];
    this.buildings = [];
    this.MovingPlatformClass = MovingPlatform;

    this.tex = this._makeTextures();
    this.cloudTex = makeCloudTexture(256, 4);
    this.materials = this._makeMaterials();
    this._makeGrassMaterial();

    // Each zone appends itself to the shared scene.
    buildMeadow(this);
    buildRuins(this);
    buildCrystal(this);
    buildSky(this);

    this.gemTotal = this.gems.length;
    this.zoneSpawns = {
      meadow: V3(0, 0.05, 8),
      ruins: V3(0, 2.45, -66),
      crystal: V3(0, -23.95, -146),
      sky: V3(0, 44.05, -74),
    };
  }

  /* ============================================================
     Procedural materials
     ============================================================ */
  _makeTextures() {
    const grass = makeMottleTexture(512, {
      base: [92, 138, 64], variance: 26, scale: 3.6, seed: 2,
      strokes: 1900, strokeColor: [164, 205, 96], darkSpots: 40,
    });
    const rock = makeMottleTexture(384, {
      base: [117, 113, 102], variance: 34, scale: 4.5, seed: 9,
      strokes: 500, strokeColor: [142, 138, 125], darkSpots: 65,
    });
    const stone = makeMottleTexture(384, {
      base: [174, 167, 146], variance: 24, scale: 5.2, seed: 15,
      strokes: 620, strokeColor: [198, 189, 163], darkSpots: 30,
    });
    const wood = makeMottleTexture(256, {
      base: [103, 76, 51], variance: 20, scale: 3.0, seed: 8,
      strokes: 320, strokeColor: [141, 108, 72], darkSpots: 15,
    });
    const sand = makeMottleTexture(256, {
      base: [194, 177, 139], variance: 18, scale: 4.0, seed: 21,
      strokes: 200, strokeColor: [215, 200, 162], darkSpots: 12,
    });
    const normal = makeNormalTexture(256, 9, 1.8, 5);
    const normalRock = makeNormalTexture(256, 7, 2.6, 12);
    const grain = makeGrainTexture(256, { base: 168, variance: 74, scale: 18, seed: 4 });
    const ao = makeGrainTexture(256, { base: 160, variance: 90, scale: 11, seed: 19 });
    return { grass, rock, stone, wood, sand, normal, normalRock, grain, ao };
  }

  _tex(tex, repeat) {
    const t = tex.clone();
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(repeat, repeat);
    t.needsUpdate = true;
    return t;
  }

  _makeMaterials() {
    const t = this.tex;
    const grass = new THREE.MeshStandardMaterial({
      map: this._tex(t.grass, 13),
      normalMap: this._tex(t.normal, 13),
      normalScale: new THREE.Vector2(0.55, 0.55),
      roughnessMap: this._tex(t.grain, 13),
      roughness: 0.94, metalness: 0.0, envMapIntensity: 0.6,
    });
    const grassTopIsland = new THREE.MeshStandardMaterial({
      map: this._tex(t.grass, 4),
      normalMap: this._tex(t.normal, 4),
      normalScale: new THREE.Vector2(0.5, 0.5),
      roughness: 0.94, metalness: 0.0, envMapIntensity: 0.6,
    });
    const path = new THREE.MeshStandardMaterial({
      map: this._tex(t.sand, 2),
      normalMap: this._tex(t.normal, 2),
      normalScale: new THREE.Vector2(0.4, 0.4),
      roughness: 0.9, metalness: 0.0, envMapIntensity: 0.55,
    });
    const rock = new THREE.MeshStandardMaterial({
      map: this._tex(t.rock, 5),
      normalMap: this._tex(t.normalRock, 5),
      normalScale: new THREE.Vector2(1.1, 1.1),
      roughnessMap: this._tex(t.grain, 5),
      roughness: 0.97, metalness: 0.0, envMapIntensity: 0.55,
    });
    const stone = new THREE.MeshStandardMaterial({
      map: this._tex(t.stone, 4),
      normalMap: this._tex(t.normalRock, 4),
      normalScale: new THREE.Vector2(0.8, 0.8),
      roughnessMap: this._tex(t.grain, 4),
      aoMap: this._tex(t.ao, 4),
      aoMapIntensity: 0.65,
      roughness: 0.9, metalness: 0.0, envMapIntensity: 0.7,
    });
    const stoneDark = new THREE.MeshStandardMaterial({
      map: this._tex(t.rock, 4),
      normalMap: this._tex(t.normalRock, 4),
      normalScale: new THREE.Vector2(0.9, 0.9),
      roughness: 0.95, metalness: 0.0, envMapIntensity: 0.6,
    });
    const wood = new THREE.MeshStandardMaterial({
      map: this._tex(t.wood, 3),
      normalMap: this._tex(t.normal, 3),
      normalScale: new THREE.Vector2(0.5, 0.5),
      roughness: 0.85, metalness: 0.0, envMapIntensity: 0.5,
    });
    const gold = new THREE.MeshStandardMaterial({
      color: 0xd8a955, metalness: 0.82, roughness: 0.24,
      emissive: 0x3a2205, emissiveIntensity: 0.4, envMapIntensity: 1.3,
    });
    const darkMetal = new THREE.MeshStandardMaterial({
      color: 0x30363a, metalness: 0.75, roughness: 0.38, envMapIntensity: 0.9,
    });
    const leafBush = new THREE.MeshStandardMaterial({
      color: 0x4c8646, roughness: 0.9, flatShading: true, envMapIntensity: 0.6,
    });
    const vines = new THREE.MeshStandardMaterial({
      color: 0x3f6f3f, roughness: 0.9, envMapIntensity: 0.4,
    });
    const cloud = new THREE.MeshStandardMaterial({
      color: 0xf0fbff, roughness: 1.0, metalness: 0.0,
      emissive: 0x7ea6b4, emissiveIntensity: 0.22, envMapIntensity: 0.7,
    });
    const acid = new THREE.MeshStandardMaterial({
      color: 0x0a4d4a, emissive: 0x1ed8c6, emissiveIntensity: 1.3,
      metalness: 0.1, roughness: 0.3, transparent: true, opacity: 0.9,
    });
    const ice = new THREE.MeshPhysicalMaterial({
      color: 0x9ffbf5, emissive: 0x155f68, emissiveIntensity: 1.0,
      metalness: 0.05, roughness: 0.1, clearcoat: 1, clearcoatRoughness: 0.05,
      transparent: true, opacity: 0.92, envMapIntensity: 1.8,
    });
    const crystalTeal = new THREE.MeshPhysicalMaterial({
      color: 0x76f4e5, emissive: 0x0b6d70, emissiveIntensity: 1.5,
      metalness: 0.1, roughness: 0.09, clearcoat: 1, clearcoatRoughness: 0.04,
      transparent: true, opacity: 0.94, envMapIntensity: 1.9, flatShading: true,
    });
    const crystalViolet = new THREE.MeshPhysicalMaterial({
      color: 0xb48cff, emissive: 0x4b1b86, emissiveIntensity: 1.4,
      metalness: 0.1, roughness: 0.1, clearcoat: 1, clearcoatRoughness: 0.05,
      transparent: true, opacity: 0.94, envMapIntensity: 1.9, flatShading: true,
    });
    return {
      grass, grassTopIsland, path, rock, stone, stoneDark, wood, gold, darkMetal,
      leafBush, vines, cloud, acid, ice, crystalTeal, crystalViolet,
    };
  }

  _makeGrassMaterial() {
    const mat = new THREE.MeshStandardMaterial({
      color: 0xffffff, roughness: 1.0, metalness: 0.0,
      side: THREE.DoubleSide, envMapIntensity: 0.4,
    });
    mat.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = { value: 0 };
      shader.vertexShader = 'uniform float uTime;\n' + shader.vertexShader;
      shader.vertexShader = shader.vertexShader.replace('#include <begin_vertex>', /* glsl */`
        #include <begin_vertex>
        float wX = instanceMatrix[3].x;
        float wZ = instanceMatrix[3].z;
        float swayAmp = 0.09 + 0.05 * sin(uTime * 0.6 + wX * 0.2 + wZ * 0.1);
        transformed.x += sin(uTime * 1.5 + wX * 0.35 + wZ * 0.28) * position.y * swayAmp;
        transformed.z += cos(uTime * 1.1 + wX * 0.2 + wZ * 0.4) * position.y * swayAmp * 0.55;
      `);
      this.grassShader = shader;
    };
    this.grassMaterial = mat;
  }

  /* ============================================================
     Collision / mesh helpers used by zone builders
     ============================================================ */
  addCollider(cx, cy, cz, w, h, d, kind = 'solid') {
    const collider = { box: new THREE.Box3(), kind, active: true };
    collider.box.setFromCenterAndSize(V3(cx, cy, cz), V3(w, h, d));
    this.colliders.push(collider);
    return collider;
  }

  addMesh(mesh, { cast = true, receive = true } = {}) {
    mesh.castShadow = cast;
    mesh.receiveShadow = receive;
    this.scene.add(mesh);
    return mesh;
  }

  /** Box mesh with its top surface at topY. */
  addPlatform(cx, topY, cz, w, h, d, material, opts = {}) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
    mesh.position.set(cx, topY - h / 2, cz);
    mesh.castShadow = opts.cast ?? true;
    mesh.receiveShadow = opts.receive ?? true;
    this.scene.add(mesh);
    if (opts.collider !== false) {
      this.addCollider(cx, topY - h / 2, cz, w, h, d, opts.kind || 'solid');
    }
    return mesh;
  }

  /** Big flat ground: grass/stone plane over a chunk of rock. */
  addGround(cx, cz, w, d, topY, material, opts = {}) {
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(w, d, opts.segments || 1, opts.segments || 1), material);
    plane.rotation.x = -Math.PI / 2;
    plane.position.set(cx, topY, cz);
    plane.receiveShadow = true;
    this.scene.add(plane);
    if (opts.underside !== false) {
      const under = new THREE.Mesh(new THREE.BoxGeometry(w, opts.depth || 9, d), opts.rockMaterial || this.materials.rock);
      under.position.set(cx, topY - (opts.depth || 9) / 2 - 0.02, cz);
      under.castShadow = false;
      under.receiveShadow = true;
      this.scene.add(under);
    }
    if (opts.collider !== false) {
      this.addCollider(cx, topY - 2.0, cz, w, 4.0, d, 'solid');
    }
    return plane;
  }

  addGem(zone, index, x, y, z, color) {
    const id = `${zone}_gem_${index}`;
    const colorForZone = color ?? { meadow: 0x8ff7ec, ruins: 0xffd98a, crystal: 0xa0fff4, sky: 0xfff0b8 }[zone];
    return new Gem(this, { id, zone, position: V3(x, y, z), color: colorForZone });
  }

  addCheckpoint(zone, index, x, y, z, name) {
    return new Checkpoint(this, { id: `${zone}_cp_${index}`, zone, position: V3(x, y, z), name });
  }

  addPortal(opts) {
    return new Portal(this, opts);
  }

  addGate(opts) {
    return new Gate(this, opts);
  }

  addEnemy(zone, type, x, y, z, opts = {}) {
    this.enemySpawns.push({ zone, type, position: V3(x, y, z), ...opts });
  }

  addHazard(x, y, z, w, h, d, opts = {}) {
    const hazard = {
      box: new THREE.Box3().setFromCenterAndSize(V3(x, y, z), V3(w, h, d)),
      damage: opts.damage ?? 1, knockback: opts.knockback ?? 7, kind: opts.kind || 'spikes',
    };
    this.hazards.push(hazard);
    return hazard;
  }

  addWindZone(x, y, z, radius, height, strength = 34) {
    this.windZones.push({ x, y, z, radius, height, strength });
  }

  addRuneCircle(position, radius, color, opacity) {
    return new RuneCircle(this, { position, radius, color, opacity });
  }

  // pass-throughs used by zone builders
  tree(x, y, z, opts) { return createTree(this, x, y, z, opts); }
  rock(x, y, z, scale, opts) { return createRock(this, x, y, z, scale, opts); }
  column(x, y, z, opts) { return createColumn(this, x, y, z, opts); }
  arch(x, y, z, opts) { return createArch(this, x, y, z, opts); }
  wall(x, y, z, opts) { return createRuinWall(this, x, y, z, opts); }
  crystal(x, y, z, opts) { return createCrystalCluster(this, x, y, z, opts); }
  bush(x, y, z, scale) { return createBush(this, x, y, z, scale); }
  water(x, y, z, radius, opts) { return createWater(this, x, y, z, radius, opts); }
  island(cx, topY, cz, w, d, opts) { return createSkyIsland(this, cx, topY, cz, w, d, opts); }
  cloudPlatform(x, y, z, w, d, opts) { return createCloudPlatform(this, x, y, z, w, d, opts); }
  wind(x, y, z, radius, height, opts) { return createWindColumn(this, x, y, z, radius, height, opts); }
  waterfall(x, y, z, w, h, opts) { return createWaterfall(this, x, y, z, w, h, opts); }
  brazier(x, y, z, opts) { return createBrazier(this, x, y, z, opts); }
  lantern(x, y, z, opts) { return createLantern(this, x, y, z, opts); }
  lilyPads(x, y, z, radius, count) { return createLilyPads(this, x, y, z, radius, count); }
  statue(x, y, z) { return createStatue(this, x, y, z); }
  grass(samples, opts) { return createGrassField(this, samples, opts); }
  flowers(samples) { return createFlowerField(this, samples); }

  /* ============================================================
     Queries
     ============================================================ */
  zoneAt(position) {
    if (position.y > 30) return 'sky';
    if (position.y < -10) return 'crystal';
    if (position.z < -60) return 'ruins';
    return 'meadow';
  }

  getZoneInfo(zone) { return ZONES[zone] || ZONES.meadow; }

  getSpawn(zone) { return this.zoneSpawns[zone]?.clone() || this.zoneSpawns.meadow.clone(); }

  getBossSpawn(zone) { return this.bossSpawns[zone] || null; }

  findNearbyCheckpoint(position, radius = 2.4) {
    for (const cp of this.checkpoints) {
      if (cp.activated) continue;
      const dx = position.x - cp.position.x;
      const dy = position.y - cp.position.y;
      const dz = position.z - cp.position.z;
      if (dx * dx + dz * dz < radius * radius && Math.abs(dy) < 3.2) return cp;
    }
    return null;
  }

  findNearbyPortal(position) {
    for (const portal of this.portals) {
      if (!portal.unlocked) continue;
      if (portal.isPlayerInside(position)) return portal;
    }
    return null;
  }

  hazardAt(box) {
    for (const h of this.hazards) {
      if (h.box.intersectsBox(box)) return h;
    }
    return null;
  }

  windAt(position) {
    for (const w of this.windZones) {
      const dx = position.x - w.x, dz = position.z - w.z;
      if (dx * dx + dz * dz < w.radius * w.radius && position.y > w.y - 1 && position.y < w.y + w.height) {
        return w;
      }
    }
    return null;
  }

  inWater(position) {
    for (const water of this.waters) {
      const dx = position.x - water.center.x;
      const dz = position.z - water.center.z;
      if (dx * dx + dz * dz < (water.radius - 0.6) * (water.radius - 0.6) &&
          position.y < water.center.y + 0.5 && position.y > water.center.y - 2.5) {
        return water;
      }
    }
    return null;
  }

  /* ============================================================
     Progress state helpers
     ============================================================ */
  setGateOpen(zone, open, instant = false) {
    for (const gate of this.gates) {
      if (gate.zone === zone) gate.setOpen(open, instant);
    }
  }

  setPortalUnlocked(zone, unlocked, instant = true) {
    for (const portal of this.portals) {
      if (portal.zone === zone) portal.setUnlocked(unlocked, instant);
    }
  }

  restoreProgress(progress) {
    if (!progress) return;
    if (progress.gems) {
      for (const gem of this.gems) {
        if (progress.gems.includes(gem.id)) gem.collect();
      }
    }
    if (progress.checkpoints) {
      for (const cp of this.checkpoints) {
        if (progress.checkpoints.includes(cp.id)) cp.activate();
      }
    }
    if (progress.bosses) {
      if (progress.bosses.meadow) this.setGateOpen('meadow', true, true);
      if (progress.bosses.ruins) this.setPortalUnlocked('ruins', true, true);
      if (progress.bosses.crystal) this.setPortalUnlocked('crystal', true, true);
    }
  }

  /* ============================================================
     Frame update
     ============================================================ */
  update(dt, time, playerPos) {
    this.time = time;
    for (const p of this.movingPlatforms) p.update(time, dt);
    for (const gate of this.gates) gate.update(dt);
    for (const portal of this.portals) portal.update(dt);
    for (const gem of this.gems) gem.update(dt);
    for (const cp of this.checkpoints) cp.update(dt);
    for (const rune of this.runeCircles) rune.update(dt, time);

    for (const water of this.waters) water.uniforms.uTime.value = time;
    for (const w of this.windVisuals) {
      if (w.mat.map) w.mat.map.offset.y -= dt * 0.22;
      w.mesh.rotation.y += dt * 0.15;
    }
    for (const wf of this.waterfalls) {
      wf.tex.offset.y -= dt * wf.speed;
    }
    for (const b of this.braziers) {
      const p = 0.7 + Math.sin(time * 7 + b.phase) * 0.2 + Math.sin(time * 13 + b.phase * 2) * 0.1;
      b.light.intensity = b.base * p;
      b.glow.material.opacity = 0.45 + p * 0.2;
    }
    for (const l of this.lanterns) {
      const p = 0.8 + Math.sin(time * 5 + l.phase) * 0.15;
      l.light.intensity = 0.8 * p;
      l.glow.material.opacity = 0.4 * p;
    }

    // LOD canopies sway in the wind.
    for (const t of this.trees) {
      const s = Math.sin(time * 0.7 + t.phase) * t.amp;
      const c = Math.cos(time * 0.5 + t.phase) * t.amp * 0.6;
      t.canopyHigh.rotation.z = s;
      t.canopyHigh.rotation.x = c;
      t.canopyLow.rotation.z = s;
      t.canopyLow.rotation.x = c;
    }
    for (const c of this.crystalClusters) {
      const p = c.base + Math.sin(time * 1.4 + c.phase) * 0.22;
      c.mat.emissiveIntensity = p;
      c.mat2.emissiveIntensity = p * 0.9;
    }
    for (const l of this.crystalLights) {
      l.light.intensity = l.base * (0.8 + Math.sin(time * 1.7 + l.phase) * 0.2);
    }
    if (this.grassShader) this.grassShader.uniforms.uTime.value = time;
  }
}

/* ============================================================
   Zone 1 — The Sunlit Meadow
   A bright starting plateau with a shallow aether pond, warm
   grass, swaying trees, a mossy boss arena and the ruins gate.
   ============================================================ */
import * as THREE from 'three';
import { MovingPlatform } from './Objects.js';
import { rand, randInt, TAU, makeRadialTexture } from '../Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

export function buildMeadow(world) {
  const M = world.materials;
  const TOP = 0;

  /* ---------------- ground ---------------- */
  world.addGround(0, -20, 96, 76, TOP, M.grass, { depth: 11 });
  // mossy cliff chunks around the rim
  for (let i = 0; i < 22; i++) {
    const side = i % 4;
    let x = rand(-45, 45), z = rand(-56, 16);
    if (side === 0) z = -57 + rand(-1.4, 0.5);
    if (side === 1) z = 17 + rand(-0.5, 1.4);
    if (side === 2) x = -47 + rand(-1.2, 0.5);
    if (side === 3) x = 47 + rand(-0.5, 1.2);
    const r = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(1.2, 3.5), 0), M.rock);
    r.position.set(x, rand(-2.2, 0.25), z);
    r.scale.y = rand(0.6, 1.2);
    r.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    r.castShadow = r.receiveShadow = true;
    world.scene.add(r);
  }

  /* ---------------- stone path ---------------- */
  for (let i = 0; i < 26; i++) {
    const z = 11 - i * 2.55;
    const tile = new THREE.Mesh(new THREE.BoxGeometry(rand(2.4, 3.0), 0.09, 2.18), M.path);
    tile.position.set(rand(-0.12, 0.12), 0.055, z);
    tile.rotation.y = rand(-0.035, 0.035);
    tile.receiveShadow = true;
    world.scene.add(tile);
    if (i % 5 === 2) world.lantern(x = (i % 2 ? 2.4 : -2.4), 0, z);
  }

  /* ---------------- spawn shrine ---------------- */
  world.statue(-5.4, 0, 12.4);
  world.addRuneCircle(V3(0, 0.02, 7), 4.4, 0xffd98a, 0.3);
  world.addCheckpoint('meadow', 0, 0, 0.02, 7, 'Dawn Shrine');

  /* ---------------- aether pond ---------------- */
  const pondX = -20, pondZ = -8, pondR = 9.2;
  world.water(pondX, 0.12, pondZ, pondR, { deep: 0x0b4148, shallow: 0x2c9b8e, bottom: 0x143a31 });
  world.lilyPads(pondX, 0.12, pondZ, pondR, 12);

  // little island + plank bridge
  world.addPlatform(pondX, 0.78, pondZ, 5.4, 1.6, 5.4, M.rock);
  const islandGrass = new THREE.Mesh(new THREE.CircleGeometry(2.55, 28), M.grassTopIsland);
  islandGrass.rotation.x = -Math.PI / 2;
  islandGrass.position.set(pondX, 0.79, pondZ);
  islandGrass.receiveShadow = true;
  world.scene.add(islandGrass);
  world.addCollider(pondX, 0.7, pondZ, 5.4, 1.4, 5.4, 'solid');
  world.tree(pondX + 0.8, 0.78, pondZ - 0.9, { scale: 0.75, palette: [0x4d8c45, 0x6fb75a, 0x3f7a42] });

  // wooden planks from the north shore
  for (let i = 0; i < 7; i++) {
    const plank = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.13, 0.7), M.wood);
    plank.position.set(pondX, 0.7 + i * 0.012, 0.7 - i * 0.92);
    plank.rotation.y = rand(-0.02, 0.02);
    plank.castShadow = plank.receiveShadow = true;
    world.scene.add(plank);
  }
  world.addCollider(pondX, 0.58, -2.2, 2.0, 0.34, 7.2, 'solid');
  for (const sx of [-1.05, 1.05]) {
    for (let i = 0; i < 3; i++) {
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 1.2, 6), M.wood);
      post.position.set(pondX + sx, 1.2, 0.6 - i * 2.3);
      post.castShadow = true;
      world.scene.add(post);
    }
  }

  // floating stepping platforms over the pond
  const makeStonePlatform = (x, y, z, w, d) => {
    const mesh = world.addMesh(new THREE.Mesh(new THREE.BoxGeometry(w, 0.42, d), M.stone));
    mesh.position.set(x, y, z);
    const plat = new MovingPlatform(world, mesh, V3(w, 0.42, d), {
      axis: V3(0, 1, 0), amplitude: 1.1, speed: 0.65, phase: rand(0, TAU), zone: 'meadow',
    });
    return { mesh, plat };
  };
  makeStonePlatform(-28.5, 1.4, -4.5, 3.2, 3.2);
  makeStonePlatform(-23.5, 2.2, -13.8, 2.8, 2.8);
  const movingBridge = world.addMesh(new THREE.Mesh(new THREE.BoxGeometry(4.4, 0.4, 2.2), M.stoneDark));
  movingBridge.position.set(-13.5, 1.6, -7.5);
  new MovingPlatform(world, movingBridge, V3(4.4, 0.4, 2.2), {
    axis: V3(1, 0, 0), amplitude: 3.4, speed: 0.45, phase: 1.2, zone: 'meadow',
  });

  /* ---------------- trees & greenery ---------------- */
  const treeSpots = [
    [-34, 8, 1.25], [-40, -14, 1.0], [-32, -30, 1.1], [37, 5, 1.15],
    [40, -20, 0.9], [31, -44, 1.05], [-38, -45, 0.85], [16, -8, 0.8],
    [12, -48, 1.25], [-13, 13, 0.9], [44, -34, 1.0], [-45, -26, 0.8],
    [22, 10, 0.95], [6, -12, 0.72],
  ];
  for (const [x, z, s] of treeSpots) {
    world.tree(x, 0, z, { scale: s, palette: [0x4d8c45, 0x5fa34e, 0x6fb75a, 0x3f7a42, 0x83c060] });
  }

  for (let i = 0; i < 14; i++) {
    const x = rand(-43, 43), z = rand(-54, 15);
    if (Math.abs(x) < 4 || Math.hypot(x - pondX, z - pondZ) < pondR + 1) continue;
    world.bush(x, 0.02, z, rand(0.7, 1.4));
  }
  for (let i = 0; i < 22; i++) {
    const x = rand(-44, 44), z = rand(-55, 16);
    if (Math.abs(x) < 3.5 || Math.hypot(x - pondX, z - pondZ) < pondR) continue;
    world.rock(x, 0, z, rand(0.35, 1.3), { collide: i < 4 });
  }
  // mushrooms and tiny flora
  for (let i = 0; i < 16; i++) {
    const x = rand(-42, 42), z = rand(-54, 14);
    if (Math.abs(x) < 3 || Math.hypot(x - pondX, z - pondZ) < pondR + 0.5) continue;
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.08, rand(0.2, 0.45), 5), M.path);
    stem.position.y = 0.15; g.add(stem);
    const cap = new THREE.Mesh(new THREE.SphereGeometry(rand(0.13, 0.28), 8, 6, 0, TAU, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: i % 3 ? 0xffb0c4 : 0xffd78a, roughness: 0.65, emissive: 0x3a1720, emissiveIntensity: 0.3 }));
    cap.position.y = 0.3; cap.castShadow = true; g.add(cap);
    world.scene.add(g);
  }

  /* ---------------- boss arena ---------------- */
  const arenaX = 27, arenaZ = -31;
  world.addRuneCircle(V3(arenaX, 0.03, arenaZ), 11.5, 0xffcf7e, 0.34);
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU + 0.2;
    const x = arenaX + Math.cos(a) * 13.2, z = arenaZ + Math.sin(a) * 13.2;
    if (i % 2 === 0) {
      world.column(x, 0, z, { height: rand(3.4, 5.4), radius: 0.62, broken: i % 4 === 0, collide: true });
    } else {
      world.rock(x, 0, z, rand(1.4, 2.4), { collide: true });
    }
  }
  world.tree(arenaX - 12, 0, arenaZ + 2, { scale: 1.45, palette: [0x467f3f, 0x5c9f4c, 0x6fb75a] });
  for (let i = 0; i < 16; i++) {
    const a = rand(0, TAU), r = rand(2, 10.5);
    world.flowers;
    const x = arenaX + Math.cos(a) * r, z = arenaZ + Math.sin(a) * r;
    if (i < 4) world.rock(x, 0.02, z, rand(0.4, 0.8), {});
  }
  world.bossSpawns.meadow = {
    zone: 'meadow', type: 'golem', name: 'Moss Golem',
    position: V3(arenaX, 0, arenaZ), arenaRadius: 13, maxHp: 160,
  };

  /* ---------------- gate + stairway to the ruins ---------------- */
  world.addGate({ id: 'ruins_gate', zone: 'meadow', position: V3(0, 0, -55), width: 12, height: 7.4, depth: 1.0 });
  for (let i = 0; i < 7; i++) {
    const top = 0.36 * (i + 1);
    const z = -57.3 - i * 1.05;
    const w = 12.4 + i * 0.25;
    world.addPlatform(0, top, z, w, Math.max(0.6, top + 0.4), 1.15, M.stone, { cast: true });
  }
  for (const sx of [-6.4, 6.4]) {
    for (let i = 0; i < 7; i++) {
      const top = 0.36 * (i + 1);
      const z = -57.3 - i * 1.05;
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.42, Math.max(0.8, top + 0.8), 1.15), M.stone);
      rail.position.set(sx, Math.max(0.8, top + 0.8) / 2 + top * 0.35, z);
      rail.castShadow = rail.receiveShadow = true;
      world.scene.add(rail);
    }
  }
  world.lantern(-5.7, 0, -52);
  world.lantern(5.7, 0, -52);

  /* ---------------- checkpoint before the gate ---------------- */
  world.addCheckpoint('meadow', 1, 0, 0.02, -46, 'Meadow Gate');

  /* ---------------- shards ---------------- */
  const gemData = [
    [10, 1.15, 1], [-11.5, 1.15, -10], [-20, 1.85, -8], [33, 1.15, -14],
    [-36, 1.3, -35], [37, 1.15, -45], [8, 4.35, -24], [-9, 1.15, -51],
  ];
  // pedestal for the high shard
  world.addPlatform(8, 3.15, -24, 3.2, 3.15, 3.2, M.rock);
  gemData.forEach((g, i) => world.addGem('meadow', i, g[0], g[1], g[2]));

  /* ---------------- enemies ---------------- */
  world.addEnemy('meadow', 'mossling', 14, 0, -18, { patrol: 5 });
  world.addEnemy('meadow', 'mossling', -27, 0, -27, { patrol: 4 });
  world.addEnemy('meadow', 'mossling', -7, 0, -39, { patrol: 6 });
  world.addEnemy('meadow', 'wisp', 19, 4.4, -16, { patrol: 6 });
  world.addEnemy('meadow', 'wisp', -32, 5, -12, { patrol: 5 });
  world.addEnemy('meadow', 'mossling', 31, 0, -47, { patrol: 4 });

  /* ---------------- grass / flowers ---------------- */
  const grass = [];
  for (let i = 0; i < 3600; i++) {
    const x = rand(-46, 46), z = rand(-56, 17);
    if (Math.abs(x) < 2.3) continue;
    if (Math.hypot(x - pondX, z - pondZ) < pondR + 0.4) continue;
    if (Math.hypot(x - arenaX, z - arenaZ) < 2.5) continue;
    grass.push({ x, y: 0.02, z, scale: 1 });
  }
  world.grass(grass);
  const flowers = [];
  for (let i = 0; i < 420; i++) {
    const x = rand(-44, 44), z = rand(-55, 16);
    if (Math.abs(x) < 2.6 || Math.hypot(x - pondX, z - pondZ) < pondR) continue;
    flowers.push({ x, y: 0.02, z });
  }
  world.flowers(flowers);

  // low mist drifting over the pond
  const mistTex = makeRadialTexture(96, 'rgba(255,255,255,0.5)', 'rgba(255,255,255,0)', 0.2);
  for (let i = 0; i < 5; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: mistTex, color: 0xcdf7f1, transparent: true, opacity: 0.16, depthWrite: false, blending: THREE.NormalBlending, toneMapped: false }));
    s.position.set(pondX + rand(-6, 6), rand(0.3, 0.8), pondZ + rand(-6, 6));
    s.scale.set(rand(8, 14), rand(2, 4), 1);
    world.scene.add(s);
  }
}

/* ============================================================
   Zone 2 — The Ancient Ruins
   A sun-bleached plateau of broken colonnades, floating stone
   and a rune portal that leads down into the crystal caverns.
   ============================================================ */
import * as THREE from 'three';
import { MovingPlatform, RuneCircle } from './Objects.js';
import { rand, randInt, TAU, makeRadialTexture } from '../Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

export function buildRuins(world) {
  const M = world.materials;
  const TOP = 2.4;

  /* ---------------- plateau ---------------- */
  world.addGround(0, -96, 76, 68, TOP, M.stone, { depth: 13, rockMaterial: M.rock, segments: 3 });
  // mossy patches to break up the stone
  const mossMat = new THREE.MeshStandardMaterial({
    map: world._tex(world.tex.grass, 4), normalMap: world._tex(world.tex.normal, 4),
    roughness: 0.95, metalness: 0, color: 0xa8c47a, transparent: true, opacity: 0.75,
  });
  for (let i = 0; i < 12; i++) {
    const r = rand(1.4, 4.2);
    const moss = new THREE.Mesh(new THREE.CircleGeometry(r, 14), mossMat);
    moss.rotation.x = -Math.PI / 2;
    moss.position.set(rand(-35, 35), TOP + 0.014, rand(-128, -64));
    moss.receiveShadow = true;
    world.scene.add(moss);
  }
  // broken rim stones
  for (let i = 0; i < 26; i++) {
    const side = i % 4;
    let x = rand(-37, 37), z = rand(-129, -63);
    if (side === 0) z = -129 + rand(-0.5, 1);
    if (side === 1) z = -63 + rand(-1, 0.5);
    if (side === 2) x = -37 + rand(-0.5, 1);
    if (side === 3) x = 37 + rand(-1, 0.5);
    const r = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(1, 2.6), 0), M.rock);
    r.position.set(x, TOP + rand(-1.2, 0.3), z);
    r.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    r.castShadow = r.receiveShadow = true;
    world.scene.add(r);
  }

  /* ---------------- threshold & colonnade ---------------- */
  world.addCheckpoint('ruins', 0, 0, TOP + 0.02, -66, 'Ruins Threshold');
  world.addRuneCircle(V3(0, TOP + 0.03, -66), 4.2, 0xffd28a, 0.25);
  world.arch(0, TOP, -74, { width: 9, height: 5.4 });

  for (let i = 0; i < 5; i++) {
    const z = -74 - i * 9.5;
    const broken = i % 3 === 0;
    world.column(-22 + rand(-0.6, 0.6), TOP, z, { height: broken ? rand(2.4, 4.2) : 6.4, radius: 0.62, broken, collide: true });
    world.column(22 + rand(-0.6, 0.6), TOP, z + rand(-1.5, 1.5), { height: broken ? rand(3, 5) : 6.4, radius: 0.62, broken: !broken, collide: true });
  }
  world.wall(-31, TOP, -86, { width: 9, height: 4.5, depth: 0.9 });
  world.wall(30, TOP, -108, { width: 10, height: 3.2, depth: 0.9 });
  world.wall(-29, TOP, -116, { width: 7, height: 5, depth: 1.0 });
  world.arch(0, TOP, -88, { width: 12, height: 6.2 });
  world.wall(17, TOP, -70, { width: 6, height: 2.4, depth: 0.8 });
  world.wall(-17, TOP, -120, { width: 8, height: 3.2, depth: 0.8 });

  // fallen columns and rubble
  for (let i = 0; i < 10; i++) {
    const x = rand(-33, 33), z = rand(-126, -68);
    if (Math.hypot(x, z + 102) < 15) continue;
    world.rock(x, TOP, z, rand(0.4, 1.4), { collide: i < 3 });
  }
  for (let i = 0; i < 5; i++) {
    const x = rand(-28, 28), z = rand(-120, -70);
    const fallen = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.55, rand(3, 6), 10), M.stone);
    fallen.rotation.z = Math.PI / 2;
    fallen.rotation.y = rand(0, TAU);
    fallen.position.set(x, TOP + 0.5, z);
    fallen.castShadow = fallen.receiveShadow = true;
    world.scene.add(fallen);
  }

  // braziers along the processional way
  for (const [x, z] of [[-5.4, -70], [5.4, -70], [-6, -90], [6, -90], [-5.5, -114], [5.5, -114]]) {
    world.brazier(x, TOP, z);
  }

  /* ---------------- boss arena ---------------- */
  const arenaX = 0, arenaZ = -102;
  world.addRuneCircle(V3(arenaX, TOP + 0.04, arenaZ), 13.5, 0xffc96e, 0.32);
  const inner = world.addRuneCircle(V3(arenaX, TOP + 0.05, arenaZ), 7, 0x8ff7ec, 0.22);
  inner.group.scale.setScalar(1);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.2;
    const x = arenaX + Math.cos(a) * 16, z = arenaZ + Math.sin(a) * 16;
    if (i % 2 === 0) world.column(x, TOP, z, { height: rand(5.2, 7.4), radius: 0.7, broken: false, collide: true });
    else world.rock(x, TOP, z, rand(1.2, 2.4), { collide: true });
  }
  // levitating rune stones
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU;
    const stone = new THREE.Mesh(new THREE.BoxGeometry(1.6, 2.6, 0.5), M.stoneDark);
    stone.position.set(arenaX + Math.cos(a) * 19, TOP + 5 + rand(-1, 1), arenaZ + Math.sin(a) * 19);
    stone.rotation.y = -a;
    stone.castShadow = true;
    world.scene.add(stone);
    const rune = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.04, 4, 16, Math.PI * 1.5), new THREE.MeshBasicMaterial({ color: 0x8ff7ec, transparent: true, opacity: 0.55, toneMapped: false }));
    rune.position.copy(stone.position).add(V3(0, 0, 0.3));
    world.scene.add(rune);
  }
  world.bossSpawns.ruins = {
    zone: 'ruins', type: 'sentinel', name: 'Rune Sentinel',
    position: V3(arenaX, TOP, arenaZ), arenaRadius: 15, maxHp: 220,
  };
  world.addCheckpoint('ruins', 1, 0, TOP + 0.02, -91, 'Sunken Court');

  /* ---------------- platforming route ---------------- */
  // west tower
  world.column(-25, TOP, -78, { height: 3.0, radius: 1.0, broken: true, collide: true });
  world.addPlatform(-25, 5.4, -78, 5.2, 0.9, 5.2, M.stone);
  world.addPlatform(-25, 8.2, -79, 3.4, 0.8, 3.4, M.stoneDark);
  const westLift = world.addMesh(new THREE.Mesh(new THREE.BoxGeometry(3.2, 0.45, 3.2), M.stone));
  westLift.position.set(-19.5, 3.0, -78);
  new MovingPlatform(world, westLift, V3(3.2, 0.45, 3.2), {
    axis: V3(0, 1, 0), amplitude: 2.2, speed: 0.6, phase: 0.4, zone: 'ruins',
  });
  // east tower
  world.column(25, TOP, -88, { height: 4.2, radius: 1.1, broken: true, collide: true });
  world.addPlatform(25, 5.0, -88, 5.4, 0.9, 5.4, M.stone);
  world.addPlatform(25, 8.5, -88, 3.6, 0.8, 3.6, M.stoneDark);
  const eastLift = world.addMesh(new THREE.Mesh(new THREE.BoxGeometry(3.2, 0.45, 3.2), M.stoneDark));
  eastLift.position.set(19, 2.8, -88);
  new MovingPlatform(world, eastLift, V3(3.2, 0.45, 3.2), {
    axis: V3(0, 1, 0), amplitude: 2.4, speed: 0.52, phase: 2.1, zone: 'ruins',
  });
  // centre moving slab above the courtyard
  const slab = world.addMesh(new THREE.Mesh(new THREE.BoxGeometry(4.6, 0.5, 3.2), M.stone));
  slab.position.set(0, 7, -114);
  new MovingPlatform(world, slab, V3(4.6, 0.5, 3.2), {
    axis: V3(0, 0, 1), amplitude: 5.5, speed: 0.33, phase: 0.7, zone: 'ruins',
  });
  world.addPlatform(-12, 9.4, -122, 4.2, 0.8, 4.2, M.stoneDark);

  // spike hazards
  const makeSpikes = (x, z, w, d) => {
    const group = new THREE.Group();
    group.position.set(x, TOP, z);
    for (let i = 0; i < Math.max(3, Math.floor(w * d * 0.8)); i++) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(rand(0.12, 0.24), rand(0.4, 0.9), 5), M.darkMetal);
      spike.position.set(rand(-w / 2, w / 2), rand(0.2, 0.45), rand(-d / 2, d / 2));
      spike.rotation.set(rand(-0.2, 0.2), rand(0, TAU), rand(-0.2, 0.2));
      spike.castShadow = true;
      group.add(spike);
    }
    const stain = new THREE.Mesh(new THREE.CircleGeometry(w * 0.7, 16), new THREE.MeshBasicMaterial({ color: 0x1c2a2a, transparent: true, opacity: 0.45 }));
    stain.rotation.x = -Math.PI / 2; stain.position.y = 0.01; group.add(stain);
    world.scene.add(group);
    world.addHazard(x, TOP + 0.35, z, w, 0.7, d, { damage: 1, knockback: 8, kind: 'spikes' });
  };
  makeSpikes(-13, -83, 6, 4);
  makeSpikes(13, -114, 5, 4);
  makeSpikes(29, -98, 4, 4);

  /* ---------------- crystal portal ---------------- */
  // dais and steps
  world.addPlatform(0, TOP + 0.55, -123, 10, 0.55, 9, M.stoneDark);
  for (let i = 0; i < 2; i++) {
    world.addPlatform(0, TOP + 0.18 + i * 0.18, -117.5 - i * 0.7, 8 - i * 1.2, 0.4, 1.0, M.stone);
  }
  world.addPortal({
    id: 'portal_crystal', zone: 'ruins', targetZone: 'crystal',
    position: V3(0, TOP + 0.55, -123), unlocked: false,
    colorA: 0x72f3ff, colorB: 0xb68cff, label: 'Crystal Caverns',
  });
  world.brazier(-6.4, TOP + 0.55, -122);
  world.brazier(6.4, TOP + 0.55, -122);

  /* ---------------- collectible shards ---------------- */
  const gems = [
    [0, TOP + 1.2, -71],
    [-25, 6.7, -78],
    [25, 9.7, -88],
    [12, TOP + 1.2, -96],
    [-13, TOP + 1.2, -109],
    [30, TOP + 1.2, -120],
    [-12, 10.7, -122],
    [0, 5.4, -86],
  ];
  // a small ledge under the last shard
  world.addPlatform(0, 4.8, -86, 3.4, 0.7, 3.4, M.stoneDark);
  gems.forEach((g, i) => world.addGem('ruins', i, g[0], g[1], g[2]));

  /* ---------------- enemies ---------------- */
  world.addEnemy('ruins', 'sentry', -18, TOP, -76, { patrol: 0 });
  world.addEnemy('ruins', 'sentry', 18, TOP, -94, { patrol: 0 });
  world.addEnemy('ruins', 'sentry', -24, TOP, -110, { patrol: 0 });
  world.addEnemy('ruins', 'mossling', 10, TOP, -78, { patrol: 5, variant: 'stone' });
  world.addEnemy('ruins', 'mossling', -9, TOP, -118, { patrol: 4, variant: 'stone' });
  world.addEnemy('ruins', 'wisp', -5, TOP + 6, -96, { patrol: 7 });
  world.addEnemy('ruins', 'wisp', 22, TOP + 5, -112, { patrol: 6 });

  /* ---------------- flora ---------------- */
  const grass = [];
  for (let i = 0; i < 700; i++) {
    const x = rand(-36, 36), z = rand(-128, -64);
    if (Math.hypot(x, z + 102) < 14) continue;
    grass.push({ x, y: TOP + 0.02, z, scale: 0.8 });
  }
  world.grass(grass, { palette: [0x7d9a4f, 0x91a85a, 0x6b8a45, 0xb0b46a] });
  const flowers = [];
  for (let i = 0; i < 90; i++) {
    const x = rand(-34, 34), z = rand(-126, -66);
    if (Math.hypot(x, z + 102) < 14) continue;
    flowers.push({ x, y: TOP + 0.02, z });
  }
  world.flowers(flowers);
  for (let i = 0; i < 6; i++) {
    world.bush(rand(-33, 33), TOP, rand(-125, -69), rand(0.7, 1.2));
  }
  // dry trees at the edges
  world.tree(-34, TOP, -98, { scale: 0.9, palette: [0x7b8a3c, 0x9aa04a, 0x6a7a34] });
  world.tree(33, TOP, -75, { scale: 1.05, palette: [0x8b9c46, 0xa8a850, 0x6e8034] });

  // floating dust in the sunbeams
  const dustTex = makeRadialTexture(96, 'rgba(255,240,190,0.8)', 'rgba(255,240,190,0)', 0.2);
  for (let i = 0; i < 4; i++) {
    const shaft = new THREE.Mesh(
      new THREE.PlaneGeometry(rand(6, 14), rand(26, 40)),
      new THREE.MeshBasicMaterial({ map: dustTex, color: 0xffe3a0, transparent: true, opacity: 0.05, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    );
    shaft.position.set(rand(-20, 20), TOP + 16, rand(-115, -75));
    shaft.rotation.z = rand(-0.3, 0.3);
    world.scene.add(shaft);
  }
}

/* ============================================================
   Zone 3 — The Crystal Caverns
   A dark, luminous cavern of living crystal, acid pools and
   floating shards. Reached by the rune portal in the ruins.
   ============================================================ */
import * as THREE from 'three';
import { MovingPlatform } from './Objects.js';
import { rand, randInt, TAU, makeRadialTexture } from '../Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

export function buildCrystal(world) {
  const M = world.materials;
  const TOP = -24;
  const CX = 0, CZ = -171;

  /* ---------------- cavern shell ---------------- */
  world.addGround(CX, CZ, 84, 70, TOP, M.rock, { depth: 12, rockMaterial: M.rock, segments: 4 });
  // wall blocks (left/right/front/back)
  world.addPlatform(-43, TOP + 27, CZ, 2.4, 54, 74, M.rock, { cast: false });
  world.addPlatform(43, TOP + 27, CZ, 2.4, 54, 74, M.rock, { cast: false });
  world.addPlatform(CX, TOP + 27, -207, 88, 54, 2.4, M.rock, { cast: false });
  // front wall split around the arrival alcove
  world.addPlatform(-26, TOP + 27, -135, 36, 54, 2.4, M.rock, { cast: false });
  world.addPlatform(26, TOP + 27, -135, 36, 54, 2.4, M.rock, { cast: false });
  // ceiling
  world.addPlatform(CX, TOP + 29, CZ, 88, 2.5, 74, M.rock, { cast: false });
  // jagged rock columns and arches
  for (let i = 0; i < 20; i++) {
    const x = rand(-39, 39), z = rand(-203, -139);
    if (Math.hypot(x, z + 180) < 15) continue;
    const h = rand(3, 12);
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(1.2, 3.2), 0), M.rock);
    rock.position.set(x, TOP + h * 0.4, z);
    rock.scale.y = rand(1.2, 2.8);
    rock.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    rock.castShadow = rock.receiveShadow = true;
    world.scene.add(rock);
    if (rand() < 0.45) world.addCollider(x, TOP + h * 0.4, z, rand(2.2, 4.2), h * 0.9, rand(2.2, 4.2), 'solid');
  }
  // stalactites
  for (let i = 0; i < 26; i++) {
    const x = rand(-40, 40), z = rand(-203, -139);
    const h = rand(2, 8);
    const spike = new THREE.Mesh(new THREE.ConeGeometry(rand(0.3, 1.2), h, 5), M.rock);
    spike.position.set(x, TOP + 28.5 - h / 2, z);
    spike.rotation.x = Math.PI;
    spike.castShadow = true;
    world.scene.add(spike);
  }

  // soft volumetric crystals fill light
  const fillA = new THREE.PointLight(0x3ed6d8, 10, 75, 2);
  fillA.position.set(-12, TOP + 16, -160);
  world.scene.add(fillA);
  const fillB = new THREE.PointLight(0x8b6dff, 8, 70, 2);
  fillB.position.set(18, TOP + 12, -190);
  world.scene.add(fillB);
  const fillC = new THREE.PointLight(0x7ff5e7, 6, 50, 2);
  fillC.position.set(0, TOP + 7, -144);
  world.scene.add(fillC);

  /* ---------------- arrival & return ---------------- */
  world.addCheckpoint('crystal', 0, 0, TOP + 0.02, -146, 'Crystal Landing');
  world.addPortal({
    id: 'portal_ruins_return', zone: 'crystal', targetZone: 'ruins',
    position: V3(0, TOP, -139), unlocked: true,
    colorA: 0xffd28a, colorB: 0x8ff7ec, label: 'Ancient Ruins',
  });
  // arrival arch
  world.arch(0, TOP, -147, { width: 11, height: 6.4, material: M.stoneDark });
  world.addRuneCircle(V3(0, TOP + 0.03, -146), 5.2, 0x8ff7ec, 0.28);

  /* ---------------- crystal gardens ---------------- */
  const clusters = [
    [-27, TOP, -152, 1.3, true], [26, TOP, -158, 1.1, true], [-33, TOP, -176, 1.4, true],
    [31, TOP, -184, 1.2, true], [-20, TOP, -194, 1.0, false], [21, TOP, -198, 1.4, true],
    [-11, TOP, -162, 0.8, false], [12, TOP, -145, 0.7, false], [34, TOP, -170, 0.9, true],
    [-36, TOP, -142, 0.8, false], [0, TOP + 12, -150, 1.3, true], [-14, TOP + 18, -192, 1.6, true],
  ];
  for (const [x, y, z, s, light] of clusters) {
    world.crystal(x, y, z, {
      scale: s, color: rand() > 0.4 ? 0x6ff7ea : 0xb48cff,
      color2: rand() > 0.5 ? 0xb48cff : 0x6ff7ea,
      light, lightIntensity: 2.4, lightDistance: 22, collide: s > 1.0,
    });
  }
  // crystal veins on the floor and walls
  for (let i = 0; i < 20; i++) {
    const vein = new THREE.Mesh(new THREE.BoxGeometry(rand(0.06, 0.16), 0.02, rand(2, 8)), new THREE.MeshBasicMaterial({
      color: rand() > 0.5 ? 0x54f0e4 : 0xb388ff, transparent: true, opacity: 0.6, toneMapped: false,
    }));
    vein.position.set(rand(-38, 38), TOP + 0.05, rand(-200, -140));
    vein.rotation.y = rand(0, TAU);
    world.scene.add(vein);
  }

  /* ---------------- acid pools ---------------- */
  const makePool = (x, z, r) => {
    const glow = new THREE.Mesh(new THREE.CircleGeometry(r, 36), new THREE.MeshBasicMaterial({ color: 0x2af0da, transparent: true, opacity: 0.75, toneMapped: false }));
    glow.rotation.x = -Math.PI / 2;
    glow.position.set(x, TOP + 0.04, z);
    world.scene.add(glow);
    const rim = new THREE.Mesh(new THREE.RingGeometry(r, r + 0.5, 36), new THREE.MeshStandardMaterial({ color: 0x1c3a3a, roughness: 0.8 }));
    rim.rotation.x = -Math.PI / 2;
    rim.position.set(x, TOP + 0.05, z);
    world.scene.add(rim);
    const light = new THREE.PointLight(0x2af0da, 2.2, 14, 2);
    light.position.set(x, TOP + 1.2, z);
    world.scene.add(light);
    world.addHazard(x, TOP + 0.4, z, r * 1.8, 0.8, r * 1.8, { damage: 1, knockback: 9, kind: 'acid' });
  };
  makePool(-17, -156, 4.4);
  makePool(18, -166, 3.6);
  makePool(-30, -187, 3.2);

  /* ---------------- boss arena ---------------- */
  const arenaZ = -180;
  world.addRuneCircle(V3(0, TOP + 0.04, arenaZ), 12.5, 0x8ff7ff, 0.3);
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + 0.3;
    const x = Math.cos(a) * 15, z = arenaZ + Math.sin(a) * 15;
    if (i % 2 === 0) world.crystal(x, TOP, z, { scale: 1.05, color: 0x6ff7ea, color2: 0xb48cff, light: i === 0, collide: true });
    else world.rock(x, TOP, z, rand(1, 2), { collide: true });
  }
  world.bossSpawns.crystal = {
    zone: 'crystal', type: 'prism', name: 'Prism Warden',
    position: V3(0, TOP, arenaZ), arenaRadius: 14, maxHp: 300,
  };
  world.addCheckpoint('crystal', 1, 0, TOP + 0.02, -168, 'Prism Hollow');

  /* ---------------- crystal platforms ---------------- */
  const makeCrystalSlab = (x, y, z, w, d) => {
    const mesh = world.addMesh(new THREE.Mesh(new THREE.BoxGeometry(w, 0.7, d), M.ice));
    mesh.position.set(x, y, z);
    return mesh;
  };
  world.addPlatform(-28, -18, -152, 5.2, 0.8, 5.2, M.ice);
  world.addPlatform(-28, -14.5, -152, 3.4, 0.8, 3.4, M.ice);
  world.addPlatform(27, -16, -168, 5.6, 0.8, 5.6, M.ice);
  world.addPlatform(27, -12, -168, 3.6, 0.8, 3.6, M.ice);
  world.addPlatform(-12, -19, -174, 4.4, 0.7, 4.4, M.ice);
  world.addPlatform(-8, -15.5, -174, 3.4, 0.7, 3.4, M.ice);
  world.addPlatform(-8, -10.5, -192, 5, 0.8, 5, M.ice);
  world.addPlatform(-2, -14.8, -192, 3.2, 0.7, 3.2, M.ice);

  // moving lifts
  const liftA = makeCrystalSlab(-20, -19, -162, 3.4, 3.4);
  new MovingPlatform(world, liftA, V3(3.4, 0.7, 3.4), { axis: V3(0, 1, 0), amplitude: 3.2, speed: 0.55, phase: 0.2, zone: 'crystal' });
  const liftB = makeCrystalSlab(16, -17, -186, 3.6, 3.6);
  new MovingPlatform(world, liftB, V3(3.6, 0.7, 3.6), { axis: V3(0, 1, 0), amplitude: 2.8, speed: 0.48, phase: 2.2, zone: 'crystal' });
  const sweep = makeCrystalSlab(0, -19.5, -160, 4.4, 3.0);
  new MovingPlatform(world, sweep, V3(4.4, 0.7, 3.0), { axis: V3(1, 0, 0), amplitude: 8, speed: 0.36, phase: 0.9, zone: 'crystal' });

  /* ---------------- sky portal ---------------- */
  world.addPlatform(0, TOP + 0.6, -201, 10, 0.6, 8.6, M.stoneDark);
  world.addPortal({
    id: 'portal_sky', zone: 'crystal', targetZone: 'sky',
    position: V3(0, TOP + 0.6, -201), unlocked: false,
    colorA: 0xb48cff, colorB: 0xffe6a2, label: 'Skybound Isles',
  });
  world.brazier(-6.2, TOP + 0.6, -200, { color: 0xb48cff });
  world.brazier(6.2, TOP + 0.6, -200, { color: 0x8ff7ec });

  /* ---------------- shards ---------------- */
  const gems = [
    [0, TOP + 1.2, -150],
    [-28, -13.4, -152],
    [27, -10.9, -168],
    [-8, -9.4, -192],
    [16, -17.5, -186],
    [30, TOP + 1.2, -196],
    [-31, TOP + 1.2, -192],
    [0, TOP + 6.2, -186],
  ];
  // floating pedestal beneath the high shard
  world.addPlatform(0, TOP + 5.4, -186, 4.2, 0.7, 4.2, M.ice);
  gems.forEach((g, i) => world.addGem('crystal', i, g[0], g[1], g[2], i % 2 ? 0x9ffff4 : 0xd1b0ff));

  /* ---------------- enemies ---------------- */
  world.addEnemy('crystal', 'mossling', -12, TOP, -152, { patrol: 4, variant: 'crystal' });
  world.addEnemy('crystal', 'mossling', 14, TOP, -176, { patrol: 5, variant: 'crystal' });
  world.addEnemy('crystal', 'mossling', -22, TOP, -190, { patrol: 4, variant: 'crystal' });
  world.addEnemy('crystal', 'wisp', 20, TOP + 5, -154, { patrol: 6, variant: 'crystal' });
  world.addEnemy('crystal', 'wisp', -16, TOP + 6, -186, { patrol: 6, variant: 'crystal' });
  world.addEnemy('crystal', 'sentry', 30, TOP, -158, { variant: 'crystal' });
  world.addEnemy('crystal', 'sentry', -30, TOP, -172, { variant: 'crystal' });

  /* ---------------- motes / mist ---------------- */
  const mistTex = makeRadialTexture(96, 'rgba(140,245,255,0.55)', 'rgba(140,245,255,0)', 0.2);
  for (let i = 0; i < 8; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: mistTex, color: 0x8ff7ff, transparent: true, opacity: 0.05, depthWrite: false, toneMapped: false }));
    s.position.set(rand(-35, 35), TOP + rand(0.5, 5), rand(-200, -140));
    s.scale.set(rand(8, 18), rand(3, 6), 1);
    world.scene.add(s);
  }

  // faint organic growth
  for (let i = 0; i < 10; i++) {
    world.bush(rand(-34, 34), TOP, rand(-200, -142), rand(0.5, 0.9));
  }
}

/* ============================================================
   Zone 4 — The Skybound Isles
   A high archipelago above the world. Wind columns, cloud
   platforms and the final storm arena beneath a golden sky.
   ============================================================ */
import * as THREE from 'three';
import { rand, randInt, TAU, makeRadialTexture } from '../Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

export function buildSky(world) {
  const M = world.materials;
  const SPAWN_Y = 44;
  const MAIN_Y = 47;

  /* ---------------- islands ---------------- */
  world.island(0, SPAWN_Y, -72, 28, 26, { depth: 16, hangVines: true });
  world.island(0, MAIN_Y, -112, 40, 38, { depth: 22, hangVines: true });
  world.island(-33, 46, -88, 18, 16, { depth: 13, hangVines: true });
  world.island(31, 45, -104, 16, 14, { depth: 12, hangVines: true });
  world.island(-17, 53, -134, 15, 13, { depth: 14, hangVines: true });
  world.island(27, 52, -138, 16, 14, { depth: 13, hangVines: true });
  // decorative distant isles
  world.island(-58, 39, -118, 10, 9, { depth: 10, hangVines: true });
  world.island(58, 42, -78, 11, 9, { depth: 11, hangVines: true });

  /* ---------------- bridge ---------------- */
  for (let i = 0; i < 7; i++) {
    const z = -86 - i * 1.18;
    const top = SPAWN_Y + 0.1 + i * 0.47;
    world.addPlatform(0, top, z, 5.6, Math.max(0.7, top - (SPAWN_Y - 1)), 1.25, M.stone, { cast: true });
  }
  for (const sx of [-3.0, 3.0]) {
    for (let i = 0; i < 7; i++) {
      const top = SPAWN_Y + 0.1 + i * 0.47;
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.12, 1.3, 6), M.gold);
      post.position.set(sx, top + 0.65, -86 - i * 1.18);
      post.castShadow = true;
      world.scene.add(post);
    }
  }
  // arch at the start of the bridge
  world.arch(0, SPAWN_Y, -85, { width: 6.2, height: 4.4, material: M.stone });

  /* ---------------- spawn & return ---------------- */
  world.addCheckpoint('sky', 0, 0, SPAWN_Y + 0.02, -78, 'Skyreach');
  world.addRuneCircle(V3(0, SPAWN_Y + 0.03, -78), 4.4, 0xffe6a2, 0.28);
  world.addPortal({
    id: 'portal_crystal_return', zone: 'sky', targetZone: 'crystal',
    position: V3(0, SPAWN_Y, -63), unlocked: true,
    colorA: 0xb48cff, colorB: 0x8ff7ec, label: 'Crystal Caverns',
  });
  // arrival statue
  world.statue(-7, SPAWN_Y, -76.5);

  /* ---------------- final arena ---------------- */
  const arenaZ = -112;
  world.addRuneCircle(V3(0, MAIN_Y + 0.04, arenaZ), 16, 0xffe09a, 0.34);
  world.addRuneCircle(V3(0, MAIN_Y + 0.05, arenaZ), 8.4, 0x9ff4ff, 0.22).group.rotation.y = 0.4;
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    const x = Math.cos(a) * 18.2, z = arenaZ + Math.sin(a) * 18.2;
    if (i % 2 === 0) {
      const obelisk = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 1.1, rand(6, 9), 6), M.stoneDark);
      obelisk.position.set(x, MAIN_Y + 3.4, z);
      obelisk.rotation.y = rand(0, TAU);
      obelisk.castShadow = obelisk.receiveShadow = true;
      world.scene.add(obelisk);
      world.addCollider(x, MAIN_Y + 3.4, z, 2.0, 7, 2.0, 'solid');
      const cap = new THREE.Mesh(new THREE.OctahedronGeometry(0.55, 0), new THREE.MeshBasicMaterial({ color: 0xffe6a2, toneMapped: false }));
      cap.position.set(x, MAIN_Y + 8.2, z);
      world.scene.add(cap);
    } else {
      world.rock(x, MAIN_Y, z, rand(1.2, 2), { collide: true });
    }
  }
  world.bossSpawns.sky = {
    zone: 'sky', type: 'drake', name: 'Storm Drake',
    position: V3(0, MAIN_Y, arenaZ), arenaRadius: 17, maxHp: 420,
  };
  world.addCheckpoint('sky', 1, 0, MAIN_Y + 0.02, -96, "Storm's Edge");
  world.brazier(-8, MAIN_Y, -99, { color: 0xffd98a });
  world.brazier(8, MAIN_Y, -99, { color: 0xffd98a });

  /* ---------------- wind columns ---------------- */
  world.wind(17, MAIN_Y - 0.5, -95, 3.2, 20, { strength: 40, color: 0xd8ffff });
  world.wind(-22, SPAWN_Y, -98, 2.8, 18, { strength: 38, color: 0xd8ffff });
  world.wind(7, 47, -128, 2.4, 16, { strength: 42, color: 0xd8ffff });

  /* ---------------- cloud platforms ---------------- */
  world.cloudPlatform(-14, 45.6, -80, 6.4, 5.4, {
    moving: true, axis: V3(0, 1, 0), amplitude: 1.6, speed: 0.55, phase: 0.4, zone: 'sky',
  });
  world.cloudPlatform(-20, 47.0, -90, 5.6, 4.6, {
    moving: true, axis: V3(1, 0, 0), amplitude: 4.5, speed: 0.42, phase: 1.2, zone: 'sky',
  });
  world.cloudPlatform(22, 48.4, -93, 6, 5, {
    moving: true, axis: V3(0, 1, 0), amplitude: 2.0, speed: 0.5, phase: 2.1, zone: 'sky',
  });
  world.cloudPlatform(19, 50.0, -122, 6.2, 5.2, {
    moving: true, axis: V3(0, 0, 1), amplitude: 5, speed: 0.35, phase: 0.8, zone: 'sky',
  });

  /* ---------------- waterfalls ---------------- */
  world.waterfall(-9, SPAWN_Y, -58.9, 6.5, 30, { speed: 0.55, color: 0xcdf7ff, rotation: 0 });
  world.waterfall(10, MAIN_Y, -93.2, 8, 38, { speed: 0.42, color: 0xd8fbff, rotation: 0 });
  const mistTex = makeRadialTexture(128, 'rgba(220,255,255,0.5)', 'rgba(220,255,255,0)', 0.2);
  for (let i = 0; i < 4; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: mistTex, color: 0xe6ffff, transparent: true, opacity: 0.18, depthWrite: false, toneMapped: false }));
    s.position.set(rand(-8, 12), SPAWN_Y - rand(6, 16), rand(-100, -70));
    s.scale.set(rand(8, 16), rand(3, 6), 1);
    world.scene.add(s);
  }

  /* ---------------- shards ---------------- */
  const gems = [
    [8, SPAWN_Y + 1.2, -76],
    [-33, 47.2, -88],
    [31, 46.2, -104],
    [-17, 54.2, -134],
    [27, 53.2, -138],
    [10, 50.4, -84],
    [0, SPAWN_Y + 2.5, -90],
    [14, MAIN_Y + 1.2, -120],
  ];
  gems.forEach((g, i) => world.addGem('sky', i, g[0], g[1], g[2], i % 2 ? 0xfff0b8 : 0x9ff7ff));

  /* ---------------- life ---------------- */
  for (const [x, z, y] of [[-9, -68, SPAWN_Y], [8, -79, SPAWN_Y], [-30, -90, 46], [30, -103, 45], [-18, -135, 53], [27, -139, 52]]) {
    world.tree(x, y, z, { scale: rand(0.8, 1.15), palette: [0x58a35e, 0x6ec06e, 0x87c95f, 0x4b9a6b] });
  }
  for (const [cx, cz, w, d, y, count] of [
    [0, -72, 24, 22, SPAWN_Y, 430],
    [0, -112, 36, 34, MAIN_Y, 760],
    [-33, -88, 15, 13, 46, 160],
    [31, -104, 13, 11, 45, 120],
    [-17, -134, 12, 10, 53, 140],
    [27, -138, 13, 11, 52, 140],
  ]) {
    const samples = [];
    for (let i = 0; i < count; i++) {
      const x = cx + rand(-w / 2, w / 2);
      const z = cz + rand(-d / 2, d / 2);
      samples.push({ x, y: y + 0.02, z, scale: 1 });
    }
    world.grass(samples, { palette: [0x6fbb5c, 0x86c968, 0x9fd477, 0x5ba94e] });
    const flowers = [];
    for (let i = 0; i < Math.floor(count * 0.1); i++) {
      flowers.push({ x: cx + rand(-w / 2, w / 2), y: y + 0.02, z: cz + rand(-d / 2, d / 2) });
    }
    world.flowers(flowers);
  }
  for (let i = 0; i < 6; i++) {
    world.bush(rand(-12, 12), SPAWN_Y, rand(-82, -64), rand(0.6, 1.0));
    world.bush(rand(-18, 18), MAIN_Y, rand(-128, -98), rand(0.6, 1.0));
  }
  for (let i = 0; i < 7; i++) {
    world.rock(rand(-36, 36), rand(44, 52), rand(-140, -60), rand(0.5, 1.2), { collide: false });
  }

  /* ---------------- enemies ---------------- */
  world.addEnemy('sky', 'wisp', -14, SPAWN_Y + 4, -74, { patrol: 6, variant: 'storm' });
  world.addEnemy('sky', 'wisp', 18, MAIN_Y + 5, -108, { patrol: 7, variant: 'storm' });
  world.addEnemy('sky', 'wisp', -27, 49, -94, { patrol: 5, variant: 'storm' });
  world.addEnemy('sky', 'wisp', 28, 49, -133, { patrol: 5, variant: 'storm' });
  world.addEnemy('sky', 'sentry', -10, MAIN_Y, -128, { variant: 'storm' });
  world.addEnemy('sky', 'sentry', 12, MAIN_Y, -99, { variant: 'storm' });
  world.addEnemy('sky', 'mossling', 22, 45, -103, { patrol: 3, variant: 'storm' });

  // extra cloud wisps for atmosphere
  for (let i = 0; i < 3; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: world.cloudTex, color: 0xf0ffff, transparent: true, opacity: 0.25, depthWrite: false, toneMapped: false }));
    s.position.set(rand(-40, 40), rand(38, 54), rand(-150, -50));
    s.scale.set(rand(12, 25), rand(4, 7), 1);
    world.scene.add(s);
  }
}

/* ============================================================
   Player — collision-safe character controller at 120 Hz with
   coyote time, jump/dash buffering, double jump, wall slide &
   jump, ledge grab, 3-hit combo, i-frames, and a fully
   procedural stylized "Nova" character with animation blending.

   GLTF SWAP POINT:
   Replace buildCharacter() with a loaded GLTF scene and drive
   the AnimationMixer in updateVisual(). All gameplay state lives
   on this.position / this.velocity, independent of the visuals.
   ============================================================ */
import * as THREE from 'three';
import { clamp, damp, lerp, angleLerp, rand, TAU, makeRadialTexture, makeGlowSprite } from './Utils.js';

const V3 = (x = 0, y = 0, z = 0) => new THREE.Vector3(x, y, z);

const RADIUS = 0.42;
const HEIGHT = 1.78;

export class Player {
  constructor(scene, world, effects, callbacks = {}) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.callbacks = callbacks;

    this.position = V3(0, 0.05, 8);
    this.velocity = V3();
    this.radius = RADIUS;
    this.height = HEIGHT;
    this.facing = Math.PI;
    this.targetFacing = Math.PI;

    this.maxHp = 5;
    this.hp = 5;
    this.dead = false;
    this.iframes = 0;
    this.hurtTimer = 0;

    this.grounded = false;
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.dashBuffer = 0;
    this.jumpHeld = false;
    this.jumpsUsed = 0;
    this.standingOn = null;
    this.wallContact = null;
    this.wallSliding = false;
    this.wallJumpLock = 0;
    this.ledge = null;
    this.state = 'air';

    this.dashTimer = 0;
    this.dashCooldown = 0;
    this.airDashUsed = false;
    this.dashDir = V3(0, 0, -1);
    this.dashTrailTimer = 0;

    this.attacking = false;
    this.attackStage = 0;
    this.attackTimer = 0;
    this.attackDuration = 0.4;
    this.attackHitTime = 0.14;
    this.attackHitDone = false;
    this.attackQueued = false;
    this.comboTimer = 0;
    this.swordVisible = false;

    this.stepTimer = 0;
    this.splashTimer = 0;
    this.landTimer = 0;
    this.landImpact = 0;
    this.runPhase = 0;
    this.time = 0;
    this.wasInWater = false;
    this.aimTarget = null;

    this.lastMove = V3();
    this.collisionContact = { x: 0, z: 0 };
    this.tmpBox = new THREE.Box3();

    this._buildCharacter();
    this._buildCompanion();
  }

  /* ============================================================
     Character construction (placeholder primitives)
     ============================================================ */
  _buildCharacter() {
    const suit = new THREE.MeshStandardMaterial({ color: 0xf1efe6, roughness: 0.62, metalness: 0.05, envMapIntensity: 0.9 });
    const suitDark = new THREE.MeshStandardMaterial({ color: 0x253a47, roughness: 0.55, metalness: 0.18, envMapIntensity: 0.8 });
    const accent = new THREE.MeshStandardMaterial({ color: 0x6ff7e8, emissive: 0x2bd8ce, emissiveIntensity: 1.5, roughness: 0.25, metalness: 0.1, toneMapped: true });
    const gold = new THREE.MeshStandardMaterial({ color: 0xe3b35c, metalness: 0.75, roughness: 0.26, envMapIntensity: 1.2 });
    const visor = new THREE.MeshPhysicalMaterial({ color: 0x53e9e0, emissive: 0x1aa7a4, emissiveIntensity: 1.4, metalness: 0.3, roughness: 0.08, clearcoat: 1, clearcoatRoughness: 0.04 });
    const scarfMat = new THREE.MeshStandardMaterial({ color: 0xd95b66, roughness: 0.72, metalness: 0.02, side: THREE.DoubleSide });
    this.materials = { suit, suitDark, accent, gold, visor, scarf: scarfMat };

    const root = new THREE.Group();
    root.position.copy(this.position);
    this.root = root;
    this.scene.add(root);

    const visual = new THREE.Group();
    root.add(visual);
    this.visual = visual;

    const body = new THREE.Group();
    body.position.y = 0;
    visual.add(body);
    this.body = body;

    // torso
    const torsoGeo = new THREE.CapsuleGeometry(0.245, 0.36, 6, 12);
    const torso = new THREE.Mesh(torsoGeo, suit);
    torso.position.y = 1.17;
    torso.castShadow = true;
    body.add(torso);
    const chest = new THREE.Mesh(new THREE.CapsuleGeometry(0.26, 0.18, 5, 12), suitDark);
    chest.position.set(0, 1.31, 0.02);
    chest.scale.set(1.02, 1, 0.88);
    chest.castShadow = true;
    body.add(chest);
    // belt
    const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.27, 0.27, 0.09, 14), gold);
    belt.position.y = 0.98;
    belt.castShadow = true;
    body.add(belt);
    // chest core
    const core = new THREE.Mesh(new THREE.OctahedronGeometry(0.075, 0), accent);
    core.position.set(0, 1.32, 0.21);
    body.add(core);
    this.core = core;
    // backpack
    const pack = new THREE.Mesh(new THREE.CapsuleGeometry(0.18, 0.28, 4, 10), suitDark);
    pack.position.set(0, 1.2, -0.25);
    pack.scale.set(1.1, 1, 0.62);
    pack.castShadow = true;
    body.add(pack);
    const packCore = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.24, 0.06), accent);
    packCore.position.set(0, 1.22, -0.37);
    packCore.rotation.x = 0.06;
    body.add(packCore);

    // head
    const headGroup = new THREE.Group();
    headGroup.position.y = 1.62;
    body.add(headGroup);
    this.headGroup = headGroup;
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.245, 20, 16), suit);
    head.scale.set(1, 1.02, 0.98);
    head.castShadow = true;
    headGroup.add(head);
    const visorMesh = new THREE.Mesh(new THREE.SphereGeometry(0.205, 20, 14, -0.65, 1.3, 0.95, 1.2), visor);
    visorMesh.position.set(0, 0.01, 0.09);
    visorMesh.scale.set(0.94, 0.8, 0.72);
    headGroup.add(visorMesh);
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.025, 0.2, 5), gold);
    antenna.position.set(0.08, 0.3, -0.02);
    antenna.rotation.z = -0.15;
    headGroup.add(antenna);
    const antennaTip = new THREE.Mesh(new THREE.SphereGeometry(0.04, 8, 6), accent);
    antennaTip.position.set(0.1, 0.4, -0.02);
    headGroup.add(antennaTip);
    // helmet rim
    const rim = new THREE.Mesh(new THREE.TorusGeometry(0.245, 0.028, 4, 24), gold);
    rim.rotation.x = Math.PI / 2;
    rim.position.y = -0.03;
    headGroup.add(rim);

    // arms
    const mkArm = (side) => {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.3, 1.42, 0);
      body.add(pivot);
      const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.072, 0.26, 4, 8), suit);
      upper.position.y = -0.16;
      upper.castShadow = true;
      pivot.add(upper);
      const elbow = new THREE.Group();
      elbow.position.y = -0.32;
      pivot.add(elbow);
      const lower = new THREE.Mesh(new THREE.CapsuleGeometry(0.062, 0.24, 4, 8), suitDark);
      lower.position.y = -0.14;
      lower.castShadow = true;
      elbow.add(lower);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.085, 10, 8), suit);
      hand.position.y = -0.29;
      hand.castShadow = true;
      elbow.add(hand);
      // wrist light
      const band = new THREE.Mesh(new THREE.TorusGeometry(0.07, 0.018, 4, 14), accent);
      band.rotation.x = Math.PI / 2;
      band.position.y = -0.23;
      elbow.add(band);
      return { pivot, elbow, hand };
    };
    this.armL = mkArm(-1);
    this.armR = mkArm(1);

    // infinity-blade (visible during attacks)
    const sword = new THREE.Group();
    const hilt = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.035, 0.2, 6), gold);
    hilt.rotation.x = Math.PI / 2;
    sword.add(hilt);
    const bladeMat = new THREE.MeshBasicMaterial({ color: 0xaafff8, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, toneMapped: false });
    const blade = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.035, 0.86), bladeMat);
    blade.position.z = 0.5;
    sword.add(blade);
    const bladeGlow = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.09, 0.9), new THREE.MeshBasicMaterial({ color: 0x5ff7e8, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, toneMapped: false }));
    bladeGlow.position.z = 0.5;
    sword.add(bladeGlow);
    sword.position.set(0, -0.32, 0.06);
    sword.rotation.x = -0.2;
    this.armR.elbow.add(sword);
    this.sword = sword;
    sword.visible = false;

    // legs
    const mkLeg = (side) => {
      const pivot = new THREE.Group();
      pivot.position.set(side * 0.13, 0.9, 0);
      body.add(pivot);
      const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.092, 0.3, 4, 8), suitDark);
      upper.position.y = -0.18;
      upper.castShadow = true;
      pivot.add(upper);
      const knee = new THREE.Group();
      knee.position.y = -0.38;
      pivot.add(knee);
      const lower = new THREE.Mesh(new THREE.CapsuleGeometry(0.078, 0.24, 4, 8), suit);
      lower.position.y = -0.14;
      lower.castShadow = true;
      knee.add(lower);
      const boot = new THREE.Mesh(new THREE.CapsuleGeometry(0.105, 0.12, 4, 8), gold);
      boot.rotation.x = Math.PI / 2;
      boot.position.set(0, -0.29, 0.03);
      boot.scale.set(1.05, 1, 0.9);
      boot.castShadow = true;
      knee.add(boot);
      return { pivot, knee };
    };
    this.legL = mkLeg(-1);
    this.legR = mkLeg(1);

    // scarf + trailing ribbons
    const scarfRing = new THREE.Mesh(new THREE.TorusGeometry(0.23, 0.075, 6, 18), scarfMat);
    scarfRing.rotation.x = Math.PI / 2;
    scarfRing.position.y = 1.48;
    scarfRing.scale.set(1.05, 1, 1);
    scarfRing.castShadow = true;
    body.add(scarfRing);
    this.ribbons = [];
    for (let i = 0; i < 3; i++) {
      const ribbon = new THREE.Mesh(new THREE.PlaneGeometry(0.16 - i * 0.03, 0.34), scarfMat);
      ribbon.position.set(0.06 + i * 0.015, 1.44 - i * 0.3, -0.24 - i * 0.05);
      ribbon.rotation.x = 0.2;
      ribbon.castShadow = true;
      body.add(ribbon);
      this.ribbons.push(ribbon);
    }

    // soft rim light attached to the hero
    this.heroLight = new THREE.PointLight(0x6ff7e8, 0.55, 4.5, 2);
    this.heroLight.position.set(0, 1.3, 0.25);
    root.add(this.heroLight);

    // teleport/landing dust sprite under the feet
    const shadowTex = makeRadialTexture(64, 'rgba(0,0,0,0.45)', 'rgba(0,0,0,0)', 0.2);
    this.contactShadow = new THREE.Mesh(
      new THREE.PlaneGeometry(1.2, 1.2),
      new THREE.MeshBasicMaterial({ map: shadowTex, transparent: true, opacity: 0.35, depthWrite: false, toneMapped: false })
    );
    this.contactShadow.rotation.x = -Math.PI / 2;
    this.scene.add(this.contactShadow);

    this.flashTime = 0;
  }

  _buildCompanion() {
    const g = new THREE.Group();
    const coreMat = new THREE.MeshBasicMaterial({ color: 0xfff0b0, toneMapped: false });
    const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.11, 0), coreMat);
    g.add(orb);
    const glow = makeGlowSprite({ color: 0xffe6a0, size: 0.75, opacity: 0.75 });
    g.add(glow);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xffe6a0, transparent: true, opacity: 0.55, toneMapped: false, blending: THREE.AdditiveBlending });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.2, 0.012, 3, 20), ringMat);
    g.add(ring);
    this.pip = { group: g, orb, glow, ring, pos: V3(1.2, 2.4, 8), phase: 0 };
    this.scene.add(g);
  }

  /* ============================================================
     Public API
     ============================================================ */
  get center() { return V3(this.position.x, this.position.y + this.height * 0.55, this.position.z); }
  get forward() { return V3(Math.sin(this.facing), 0, Math.cos(this.facing)); }
  get speed() { return Math.hypot(this.velocity.x, this.velocity.z); }
  get healthRatio() { return clamp(this.hp / this.maxHp, 0, 1); }

  reset(position, facing = Math.PI) {
    this.position.copy(position);
    this.velocity.set(0, 0, 0);
    this.facing = this.targetFacing = facing;
    this.hp = this.maxHp;
    this.dead = false;
    this.iframes = 1.1;
    this.hurtTimer = 0;
    this.dashTimer = 0;
    this.dashCooldown = 0;
    this.attacking = false;
    this.attackTimer = 0;
    this.attackStage = 0;
    this.attackQueued = false;
    this.ledge = null;
    this.comboTimer = 0;
    this.visual.rotation.set(0, 0, 0);
    this.visual.position.set(0, 0, 0);
    this.root.visible = true;
    this.root.position.copy(position);
    this.standingOn = null;
  }

  addHp(n) {
    if (this.dead) return;
    const before = this.hp;
    this.hp = clamp(this.hp + n, 0, this.maxHp);
    if (this.hp > before) this.callbacks.onHeal?.(this.hp, this.maxHp);
  }

  takeDamage(amount, sourcePosition = null, opts = {}) {
    if (this.dead || this.iframes > 0 || this.dashTimer > 0) return false;
    this.hp -= amount;
    this.iframes = opts.iframes ?? 1.1;
    this.hurtTimer = 0.32;
    this.flashTime = 0.2;
    if (sourcePosition) {
      const dir = this.position.clone().sub(sourcePosition);
      dir.y = 0;
      if (dir.lengthSq() < 0.001) dir.set(0, 0, 1);
      dir.normalize();
      this.velocity.x = dir.x * (opts.knockback ?? 8);
      this.velocity.z = dir.z * (opts.knockback ?? 8);
      this.velocity.y = opts.up ?? 5.2;
    } else {
      this.velocity.y = Math.max(this.velocity.y, 4);
    }
    this.grounded = false;
    this.height = HEIGHT;
    this.effects.hitSpark(this.center, 0xff7d8a, 18);
    this.effects.addShake(0.34, 0.35);
    this.callbacks.onDamage?.(amount, this.hp, this.maxHp);
    if (this.hp <= 0) this._die();
    return true;
  }

  _die() {
    if (this.dead) return;
    this.dead = true;
    this.hp = 0;
    this.velocity.set(0, 0, 0);
    this.attacking = false;
    this.ledge = null;
    this.callbacks.onDeath?.();
  }

  healFull() {
    this.hp = this.maxHp;
    this.callbacks.onHeal?.(this.hp, this.maxHp);
  }

  /* ============================================================
     Fixed-step simulation
     ============================================================ */
  update(dt, input, cameraYaw, aimTarget = null) {
    if (this.dead) {
      this.time += dt;
      return;
    }
    this.time += dt;
    this.aimTarget = aimTarget;

    // timers
    this.iframes = Math.max(0, this.iframes - dt);
    this.hurtTimer = Math.max(0, this.hurtTimer - dt);
    this.dashCooldown = Math.max(0, this.dashCooldown - dt);
    this.coyote = Math.max(0, this.coyote - dt);
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
    this.dashBuffer = Math.max(0, this.dashBuffer - dt);
    this.wallJumpLock = Math.max(0, this.wallJumpLock - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    this.landTimer = Math.max(0, this.landTimer - dt);
    this.attackTimer = Math.max(0, this.attackTimer - dt * 0); // attack consumed below

    // input edges
    if (input.consumePressed('jump')) this.jumpBuffer = 0.14;
    if (input.consumePressed('dash')) this.dashBuffer = 0.12;
    const attackPressed = input.consumePressed('attack');
    this.jumpHeld = input.isDown('jump');

    // attack combo input
    if (attackPressed) {
      if (!this.attacking && this.comboTimer > 0 && this.attackStage < 2 && this.attackStage > 0) {
        this._startAttack(this.attackStage + 1);
      } else if (!this.attacking) {
        this._startAttack(0);
      } else if (this.attackStage < 2) {
        this.attackQueued = true;
      }
    }

    // moving platforms carry the player
    if (this.grounded && this.standingOn && this.standingOn.platform) {
      this.position.add(this.standingOn.platform.delta);
    }

    // ledge state
    if (this.ledge) {
      this._updateLedge(dt);
      this._updateAttack(dt);
      return;
    }

    // dash
    if (this.dashTimer > 0) {
      this._updateDash(dt);
      this._updateAttack(dt);
      this._checkHazards();
      return;
    }

    if (this.dashBuffer > 0 && this.dashCooldown <= 0 && (!this.grounded ? !this.airDashUsed : true)) {
      this._startDash(input, cameraYaw);
      this._checkHazards();
      return;
    }

    // movement input relative to camera
    const mv = input.getMove();
    const forward = V3(-Math.sin(cameraYaw), 0, -Math.cos(cameraYaw));
    const right = V3(Math.cos(cameraYaw), 0, -Math.sin(cameraYaw));
    const wish = V3().addScaledVector(forward, mv.y).addScaledVector(right, mv.x);
    const wishLen = Math.min(1, wish.length());
    if (wish.lengthSq() > 0.0001) wish.normalize();
    this.lastMove.copy(wish);
    const inWater = this.world.inWater(this.position);
    const wind = this.world.windAt(this.position);
    const speedCap = inWater ? 4.6 : 8.3;
    const accel = this.grounded ? 62 : (inWater ? 24 : 34);
    const decel = this.grounded ? (inWater ? 10 : 15) : 3.2;

    // slow while attacking / hurt
    const control = this.attacking ? 0.28 : (this.hurtTimer > 0 ? 0.12 : 1);
    if (wishLen > 0.05) {
      const desiredX = wish.x * speedCap * wishLen * control;
      const desiredZ = wish.z * speedCap * wishLen * control;
      this.velocity.x = damp(this.velocity.x, desiredX, accel * 0.28, dt);
      this.velocity.z = damp(this.velocity.z, desiredZ, accel * 0.28, dt);
      if (!this.attacking) {
        this.targetFacing = Math.atan2(wish.x, wish.z);
        if (this.aimTarget) {
          this.targetFacing = Math.atan2(this.aimTarget.x - this.position.x, this.aimTarget.z - this.position.z);
        }
      }
    } else {
      this.velocity.x = damp(this.velocity.x, 0, decel, dt);
      this.velocity.z = damp(this.velocity.z, 0, decel, dt);
    }

    // gravity / buoyancy / wind
    this.velocity.y -= 32 * dt;
    if (inWater) {
      this.velocity.y = Math.max(this.velocity.y, -4.5);
      if (this.wasJumping) { this.velocity.y = Math.max(this.velocity.y, 5.5); this.wasJumping = false; }
    }
    if (wind && !this.grounded) {
      this.velocity.y += wind.strength * dt * 1.6;
      this.velocity.y = Math.min(this.velocity.y, 17);
    }
    if (this.jumpHeld && this.velocity.y > 0) {
      this.velocity.y -= 18 * dt;
    } else if (this.velocity.y > 0) {
      this.velocity.y -= 16 * dt;
    }
    this.velocity.y = Math.max(this.velocity.y, -38);

    // jumping
    if (this.jumpBuffer > 0) {
      if (this.grounded || this.coyote > 0) {
        this._jump();
      } else if (this.wallContact && this.wallJumpLock <= 0) {
        this._wallJump();
      } else if (this.jumpsUsed < 2) {
        this._doubleJump();
      }
    }

    // fall through a ledge with down input
    if (this.grounded && mv.y < -0.7 && this.standingOn && this.standingOn.kind === 'solid' && this.position.y > 1) {
      // only trigger on one-way platforms (none currently) - kept for extensibility
    }

    // physics move
    this.grounded = false;
    this._moveAndCollide(dt);
    if (this.grounded) {
      this.coyote = 0.11;
      this.jumpsUsed = 0;
      this.airDashUsed = false;
      if (this.velocity.y < -11) {
        const impact = clamp(-this.velocity.y / 26, 0.2, 1);
        this.landTimer = 0.2;
        this.landImpact = impact;
        this.effects.burst(this.position.clone().add(V3(0, 0.05, 0)), {
          count: 16, speed: 2.6, direction: V3(0, 1, 0), spread: 1.0,
          posVar: 0.25, size: 0.18, life: 0.5, gravity: -2, drag: 2.2,
          colors: [0xd9c69a, 0xcab98d, 0xffffff],
        });
        this.callbacks.onLand?.(impact);
      }
    }

    // wall detection & slide
    this._detectWalls();
    this.wallSliding = false;
    if (!this.grounded && this.wallContact && this.velocity.y < -2.5 && wishLen > 0.2) {
      const intoWall = wish.dot(this.wallContact.normal) < -0.25;
      if (intoWall && !this.ledge) {
        this.wallSliding = true;
        this.velocity.y = Math.max(this.velocity.y, -3.2);
        if (Math.random() < dt * 18) {
          this.effects.spawnWallDust?.(this.position);
          this.effects.burst(this.position.clone().add(V3(0, 1.2, 0)).addScaledVector(this.wallContact.normal, -0.35), {
            count: 2, speed: 1.2, size: 0.09, life: 0.34, gravity: -1, drag: 3,
            colors: [0xd9c9a8, 0xffffff],
          });
        }
      }
    }

    // ledge grab
    if (!this.grounded && this.velocity.y < -1.2 && !this.attacking && this.wallContact) {
      const ledge = this._findLedge(wish);
      if (ledge) {
        this._grabLedge(ledge);
      }
    }

    // attack progression
    this._updateAttack(dt);

    // footsteps / water splashes
    if (this.grounded && this.speed > 2.2) {
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = clamp(0.4 - this.speed * 0.027, 0.18, 0.36);
        this.effects.footstep(this.position.clone(), this.world.zoneAt(this.position) === 'ruins' ? 0xcabb9a : 0x9fbb7a);
        this.callbacks.onStep?.();
      }
    } else {
      this.stepTimer = 0;
    }
    if (inWater) {
      this.splashTimer -= dt;
      if (this.splashTimer <= 0 && this.speed > 1.2) {
        this.splashTimer = 0.18;
        this.effects.splash(this.position.clone().add(V3(0, 0.1, 0)));
        this.callbacks.onWater?.();
      }
    }

    // facing
    if (!this.attacking && this.hurtTimer <= 0 && (this.speed > 0.4 || mv.len > 0.1)) {
      this.targetFacing = this.aimTarget
        ? Math.atan2(this.aimTarget.x - this.position.x, this.aimTarget.z - this.position.z)
        : Math.atan2(this.velocity.x, this.velocity.z);
    }
    if (this.ledge) {
      this.targetFacing = Math.atan2(-this.ledge.normal.x, -this.ledge.normal.z);
    }
    this.facing = angleLerp(this.facing, this.targetFacing, 1 - Math.exp(-16 * dt));

    this._checkHazards();

    if (this.position.y < -52) {
      this._die();
    }
  }

  _jump() {
    this.velocity.y = 12.8;
    this.grounded = false;
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.jumpsUsed = 1;
    this.landTimer = 0;
    this.wasJumping = true;
    this.effects.burst(this.position.clone(), {
      count: 10, speed: 2.4, direction: V3(0, 1, 0), spread: 0.9, posVar: 0.2,
      size: 0.14, life: 0.4, gravity: -1, drag: 2.5, colors: [0xd8ccaa, 0xffffff],
    });
    this.callbacks.onJump?.(false);
  }

  _doubleJump() {
    this.velocity.y = 12.2;
    this.jumpsUsed = 2;
    this.jumpBuffer = 0;
    this.effects.doubleJump(this.center);
    this.callbacks.onDoubleJump?.();
  }

  _wallJump() {
    const n = this.wallContact.normal;
    this.velocity.x = n.x * 10.5;
    this.velocity.z = n.z * 10.5;
    this.velocity.y = 11.5;
    this.jumpsUsed = 1;
    this.jumpBuffer = 0;
    this.wallJumpLock = 0.25;
    this.targetFacing = Math.atan2(n.x, n.z);
    this.effects.burst(this.center, {
      count: 14, speed: 3.2, size: 0.12, life: 0.38, gravity: -2, drag: 2.4,
      colors: [0x8ff7ec, 0xffffff],
    });
    this.callbacks.onJump?.(true);
  }

  _startDash(input, cameraYaw) {
    const mv = input.getMove();
    let dir;
    if (mv.len > 0.15) {
      const forward = V3(-Math.sin(cameraYaw), 0, -Math.cos(cameraYaw));
      const right = V3(Math.cos(cameraYaw), 0, -Math.sin(cameraYaw));
      dir = V3().addScaledVector(forward, mv.y).addScaledVector(right, mv.x).normalize();
    } else {
      dir = this.forward;
    }
    this.dashDir.copy(dir);
    this.targetFacing = Math.atan2(dir.x, dir.z);
    this.dashTimer = 0.22;
    this.dashCooldown = 0.72;
    this.dashBuffer = 0;
    this.velocity.set(dir.x * 25, 0.5, dir.z * 25);
    this.iframes = Math.max(this.iframes, 0.28);
    if (!this.grounded) this.airDashUsed = true;
    this.attacking = false;
    this.effects.burst(this.center, {
      count: 16, speed: 3, direction: dir.clone().negate(), spread: 0.7,
      size: 0.2, life: 0.45, gravity: 0.2, drag: 2.8, colors: [0x8ff7ec, 0xffffff, 0xa8e8ff],
    });
    this.callbacks.onDash?.();
  }

  _updateDash(dt) {
    this.dashTimer -= dt;
    this.dashTrailTimer -= dt;
    this.velocity.y = Math.max(this.velocity.y, -0.2);
    this.grounded = false;
    this._moveAndCollide(dt);
    if (this.dashTrailTimer <= 0) {
      this.dashTrailTimer = 0.018;
      this.effects.dashTrail(this.center.clone().add(V3(0, 0.2, 0)));
    }
    if (this.grounded) this.coyote = 0.1;
    if (this.dashTimer <= 0) {
      this.velocity.x *= 0.42;
      this.velocity.z *= 0.42;
      this.velocity.y = Math.min(this.velocity.y, 2);
    }
  }

  _updateLedge(dt) {
    if (!this.ledge) return;
    this.velocity.set(0, 0, 0);
    this.iframes = Math.max(this.iframes, 0.05);
    const n = this.ledge.normal;
    this.targetFacing = Math.atan2(-n.x, -n.z);
    this.facing = angleLerp(this.facing, this.targetFacing, 1 - Math.exp(-20 * dt));
    // keep glued
    this.position.x = this.ledge.box.max.x + this.radius + 0.02 * (n.x > 0 ? 1 : -1) * 0 - n.x * (this.radius + 0.04);
    this.position.z = this.ledge.box.max.z + this.radius + 0.02 * (n.z > 0 ? 1 : -1) * 0 - n.z * (this.radius + 0.04);
    this.position.y = this.ledge.box.max.y - 1.62;
    if (this.jumpBuffer > 0) {
      // climb up
      this.position.copy(this.ledge.climbPos);
      this.velocity.set(n.x * 1.8, 8.4, n.z * 1.8);
      this.ledge = null;
      this.jumpBuffer = 0;
      this.jumpsUsed = 1;
      this.grounded = false;
      this.effects.burst(this.center, { count: 12, speed: 2, size: 0.12, life: 0.4, gravity: -3, colors: [0x8ff7ec, 0xffffff] });
      this.callbacks.onJump?.(false);
      return;
    }
    if (this.dashBuffer > 0) {
      this.velocity.set(n.x * 9, 5, n.z * 9);
      this.ledge = null;
      this.dashBuffer = 0;
      this.iframes = Math.max(this.iframes, 0.2);
    }
  }

  _findLedge(wish) {
    if (!this.wallContact) return null;
    const col = this.wallContact.collider;
    if (!col || !col.box) return null;
    const top = col.box.max.y;
    const rel = top - this.position.y;
    if (rel < 1.15 || rel > 1.95) return null;
    const n = this.wallContact.normal;
    if (wish.len > 0.1 && wish.dot(n) > -0.15) return null;
    // ensure there's space above
    const climbPos = V3(
      this.position.x - n.x * (this.radius + 0.08),
      top + 0.03,
      this.position.z - n.z * (this.radius + 0.08)
    );
    const test = this._boxAt(climbPos.x, climbPos.y + 0.1, climbPos.z);
    for (const c of this.world.colliders) {
      if (!c.active) continue;
      if (c === col) continue;
      if (test.intersectsBox(c.box)) return null;
    }
    return { box: col.box, normal: n, climbPos };
  }

  _grabLedge(ledge) {
    this.ledge = ledge;
    this.dashTimer = 0;
    this.attacking = false;
    this.velocity.set(0, 0, 0);
    this.wallSliding = false;
    this.targetFacing = Math.atan2(-ledge.normal.x, -ledge.normal.z);
    this.effects.burst(this.center.clone().add(V3(0, 0.55, 0)), {
      count: 10, speed: 1.5, size: 0.1, life: 0.4, gravity: -1, drag: 2.5, colors: [0xffffff, 0xd8ccaa],
    });
    this.callbacks.onLedge?.();
  }

  _startAttack(stage) {
    this.attackStage = clamp(stage, 0, 2);
    this.attacking = true;
    this.attackTimer = 0;
    this.attackHitDone = false;
    this.attackQueued = false;
    this.attackDuration = this.attackStage === 2 ? 0.52 : 0.4;
    this.attackHitTime = this.attackStage === 2 ? 0.2 : 0.15;
    this.comboTimer = 0.55;
    this.sword.visible = true;
    if (this.aimTarget) {
      this.targetFacing = Math.atan2(this.aimTarget.x - this.position.x, this.aimTarget.z - this.position.z);
      this.facing = this.targetFacing;
    }
    this.velocity.x *= 0.4;
    this.velocity.z *= 0.4;
    this.callbacks.onAttackStart?.(this.attackStage);
  }

  _updateAttack(dt) {
    if (!this.attacking) {
      this.sword.visible = false;
      if (this.attackStage > 0 && this.comboTimer <= 0) this.attackStage = 0;
      return;
    }
    this.attackTimer += dt;
    if (!this.attackHitDone && this.attackTimer >= this.attackHitTime) {
      this.attackHitDone = true;
      const fwd = this.forward;
      this.effects.slash(this.position.clone().addScaledVector(fwd, 0.8), this.facing, {
        color: this.attackStage === 2 ? 0xffe6a0 : 0x9ffff4,
        scale: this.attackStage === 2 ? 1.35 : 1,
      });
      this.callbacks.onAttackHit?.(this.attackStage, this.position.clone(), this.facing);
    }
    if (this.attackTimer >= this.attackDuration) {
      this.attacking = false;
      this.sword.visible = false;
      this.comboTimer = 0.38;
      if (this.attackQueued && this.attackStage < 2) {
        this._startAttack(this.attackStage + 1);
      } else if (this.attackStage >= 2) {
        this.attackStage = 0;
      }
    }
  }

  _checkHazards() {
    if (this.iframes > 0 || this.dead) return;
    const box = this._boxAt(this.position.x, this.position.y + 0.15, this.position.z);
    const hazard = this.world.hazardAt(box);
    if (hazard) {
      const center = hazard.box.getCenter(V3());
      this.takeDamage(hazard.damage, center, { knockback: hazard.knockback, up: 6.5, iframes: 1.2 });
      this.callbacks.onHazard?.(hazard);
    }
  }

  /* ============================================================
     Collision
     ============================================================ */
  _boxAt(x, y, z) {
    const box = this.tmpBox;
    box.min.set(x - this.radius, y, z - this.radius);
    box.max.set(x + this.radius, y + this.height, z + this.radius);
    return box;
  }

  _moveAndCollide(dt) {
    this.collisionContact.x = 0;
    this.collisionContact.z = 0;
    const active = this.world.colliders;

    // X
    this.position.x += this.velocity.x * dt;
    for (let iter = 0; iter < 2; iter++) {
      const box = this._boxAt(this.position.x, this.position.y, this.position.z);
      let hit = false;
      for (const c of active) {
        if (!c.active) continue;
        if (!box.intersectsBox(c.box)) continue;
        // step up small ledges
        if (this.grounded && c.box.max.y - this.position.y <= 0.56 && c.box.max.y > this.position.y + 0.02) {
          this.position.y = c.box.max.y + 0.015;
          this.velocity.y = Math.max(0, this.velocity.y);
          this.standingOn = c;
          this.grounded = true;
          continue;
        }
        if (this.velocity.x > 0) {
          this.position.x = c.box.min.x - this.radius - 0.001;
          this.collisionContact.x = 1;
        } else if (this.velocity.x < 0) {
          this.position.x = c.box.max.x + this.radius + 0.001;
          this.collisionContact.x = -1;
        } else {
          const pc = c.box.getCenter(V3());
          this.position.x += this.position.x < pc.x ? -0.02 : 0.02;
        }
        this.velocity.x = 0;
        this._recordWallContact(c, this.collisionContact.x, 0);
        hit = true;
        break;
      }
      if (!hit) break;
    }

    // Z
    this.position.z += this.velocity.z * dt;
    for (let iter = 0; iter < 2; iter++) {
      const box = this._boxAt(this.position.x, this.position.y, this.position.z);
      let hit = false;
      for (const c of active) {
        if (!c.active) continue;
        if (!box.intersectsBox(c.box)) continue;
        if (this.grounded && c.box.max.y - this.position.y <= 0.56 && c.box.max.y > this.position.y + 0.02) {
          this.position.y = c.box.max.y + 0.015;
          this.velocity.y = Math.max(0, this.velocity.y);
          this.standingOn = c;
          this.grounded = true;
          continue;
        }
        if (this.velocity.z > 0) {
          this.position.z = c.box.min.z - this.radius - 0.001;
          this.collisionContact.z = 1;
        } else if (this.velocity.z < 0) {
          this.position.z = c.box.max.z + this.radius + 0.001;
          this.collisionContact.z = -1;
        }
        this.velocity.z = 0;
        this._recordWallContact(c, 0, this.collisionContact.z);
        hit = true;
        break;
      }
      if (!hit) break;
    }

    // Y
    const prevVy = this.velocity.y;
    this.position.y += this.velocity.y * dt;
    this.grounded = false;
    this.standingOn = null;
    for (let iter = 0; iter < 2; iter++) {
      const box = this._boxAt(this.position.x, this.position.y, this.position.z);
      let hit = false;
      for (const c of active) {
        if (!c.active) continue;
        if (!box.intersectsBox(c.box)) continue;
        if (this.velocity.y <= 0) {
          this.position.y = c.box.max.y;
          this.velocity.y = 0;
          this.grounded = true;
          this.standingOn = c;
          this.coyote = 0.11;
        } else {
          this.position.y = c.box.min.y - this.height - 0.001;
          this.velocity.y = 0;
        }
        hit = true;
        break;
      }
      if (!hit) break;
    }

    // ground probe (handles standing still)
    if (!this.grounded && this.velocity.y <= 0.01) {
      const probe = this._boxAt(this.position.x, this.position.y - 0.06, this.position.z);
      let best = null;
      for (const c of active) {
        if (!c.active) continue;
        if (probe.intersectsBox(c.box)) {
          if (!best || c.box.max.y > best.box.max.y) best = c;
        }
      }
      if (best) {
        this.position.y = best.box.max.y;
        this.velocity.y = 0;
        this.grounded = true;
        this.standingOn = best;
        this.coyote = 0.11;
      }
    }

    // keep inside the world's vertical bounds
    if (this.position.y < -52) {
      this.position.y = -52;
      this.velocity.y = 0;
    }
  }

  _recordWallContact(collider, nx, nz) {
    if (nx === 0 && nz === 0) return;
    this.wallContact = {
      collider,
      normal: V3(nx, 0, nz).normalize(),
      time: this.time,
    };
  }

  _detectWalls() {
    this.wallContact = null;
    this.wallJumpLock = Math.max(0, this.wallJumpLock);
    if (this.grounded) return;
    const p = this.position;
    const probes = [
      { nx: 1, x: p.x + this.radius + 0.06, z: p.z },
      { nx: -1, x: p.x - this.radius - 0.06, z: p.z },
      { nz: 1, x: p.x, z: p.z + this.radius + 0.06 },
      { nz: -1, x: p.x, z: p.z - this.radius - 0.06 },
    ];
    for (const probe of probes) {
      for (const c of this.world.colliders) {
        if (!c.active) continue;
        if (probe.x - 0.02 > c.box.min.x && probe.x + 0.02 < c.box.max.x &&
            probe.z - 0.02 > c.box.min.z && probe.z + 0.02 < c.box.max.z &&
            p.y + 0.3 < c.box.max.y && p.y + this.height - 0.2 > c.box.min.y) {
          this.wallContact = { collider: c, normal: V3(probe.nx || 0, 0, probe.nz || 0), time: this.time };
          return;
        }
      }
    }
  }

  /* ============================================================
     Visuals / animation blending
     ============================================================ */
  updateVisual(dt, camera) {
    if (!this.root) return;
    this.root.position.copy(this.position);
    this.root.rotation.y = this.facing;

    // i-frame blink
    if (this.dead) {
      this.visual.rotation.z = damp(this.visual.rotation.z, -Math.PI / 2, 7, dt);
      this.visual.position.y = damp(this.visual.position.y, 0.15, 5, dt);
      this.root.visible = true;
    } else if (this.iframes > 0.12 && this.hurtTimer > 0) {
      this.visual.visible = Math.floor(this.time * 28) % 2 === 0;
    } else {
      this.visual.visible = true;
    }

    const moving = this.speed > 0.6;
    const airborne = !this.grounded && !this.ledge;
    const targetLean = this.dashTimer > 0 ? 0.35 : (this.attacking ? 0.08 : (moving ? 0.06 : 0));
    this.visual.rotation.x = damp(this.visual.rotation.x, targetLean, 10, dt);
    this.visual.rotation.z = damp(this.visual.rotation.z, airborne ? -this.velocity.x * 0.008 : 0, 6, dt);

    // squash & stretch
    let squash = 1;
    if (this.landTimer > 0) squash = 1 - Math.sin((this.landTimer / 0.2) * Math.PI) * 0.12 * this.landImpact;
    if (airborne) squash = 1 + clamp(Math.abs(this.velocity.y) * 0.003, 0, 0.06);
    this.body.scale.set(1 / Math.sqrt(squash), squash, 1 / Math.sqrt(squash));
    this.visual.position.y = damp(this.visual.position.y, this.dead ? 0.15 : 0, 6, dt);

    // idle bob + breathing
    const breath = Math.sin(this.time * 2.1) * 0.01;
    const runSpeed = clamp(this.speed / 8.3, 0, 1);
    if (moving && this.grounded) this.runPhase += dt * (5.2 + runSpeed * 5.6);
    else this.runPhase += dt * 1.2;

    const phase = this.runPhase;
    const runWeight = this.grounded && moving ? clamp(this.speed / 4, 0, 1) : 0;
    const idleWeight = 1 - runWeight;
    const swing = Math.sin(phase) * 0.72 * runWeight;
    const swing2 = Math.sin(phase + Math.PI) * 0.72 * runWeight;

    // target rotations
    let legLX = swing, legRX = swing2, kneeLX = Math.max(0, -swing) * 0.7, kneeRX = Math.max(0, -swing2) * 0.7;
    let armLX = -swing * 0.85, armRX = -swing2 * 0.85;
    let armLZ = -0.06, armRZ = 0.06;
    let headX = 0, headY = 0;
    let torsoTwist = Math.sin(phase) * 0.055 * runWeight;
    let swordSwing = 0;

    if (this.ledge) {
      legLX = -0.3; legRX = -0.05; kneeLX = 0.65; kneeRX = 0.4;
      armLX = -2.45; armRX = -2.45; armLZ = -0.3; armRZ = 0.3;
      torsoTwist = 0.1; headX = 0.25;
    } else if (this.dashTimer > 0) {
      legLX = -0.9; legRX = 0.55; kneeLX = 0.25; kneeRX = 0.1;
      armLX = 1.9; armRX = 1.9; armLZ = -0.55; armRZ = 0.55;
      headX = -0.2;
    } else if (airborne) {
      if (this.velocity.y > 2) {
        legLX = -0.72; legRX = -0.25; kneeLX = 1.15; kneeRX = 0.7;
        armLX = -1.1; armRX = -1.1; armLZ = -0.28; armRZ = 0.28;
        headX = -0.08;
      } else {
        legLX = -0.2; legRX = 0.2; kneeLX = 0.35; kneeRX = 0.35;
        armLX = -0.6; armRX = -0.6; armLZ = -0.65; armRZ = 0.65;
        headX = 0.12;
      }
    } else if (this.hurtTimer > 0) {
      legLX = 0.2; legRX = -0.2; armLX = -0.8; armRX = -0.8; headX = -0.25;
    }

    if (this.attacking) {
      const t = this.attackTimer / this.attackDuration;
      const arc = Math.sin(clamp(t, 0, 1) * Math.PI);
      if (this.attackStage === 2) {
        armRX = -2.4 + t * 3.7;
        armRZ = 0.6 - t * 0.9;
        swordSwing = -1.2 + t * 2.4;
        torsoTwist = -0.2 + t * 0.45;
        armLX = -0.7;
      } else if (this.attackStage === 1) {
        armRX = -1.9 + t * 3.1;
        armRZ = 0.9 - t * 1.5;
        swordSwing = -0.8 + t * 1.9;
        torsoTwist = 0.2 - t * 0.4;
        armLX = 0.5;
      } else {
        armRX = -1.4 + t * 2.5;
        armRZ = 0.4 - t * 1.2;
        swordSwing = -0.5 + t * 2;
        torsoTwist = 0.14 - t * 0.3;
        armLX = -0.4;
      }
      armRX += arc * 0.1;
    }

    // additive idle
    const idleArm = Math.sin(this.time * 1.4) * 0.045 * idleWeight;
    armLX += idleArm; armRX -= idleArm;
    headX += Math.sin(this.time * 0.9) * 0.025 * idleWeight;
    headY = Math.sin(this.time * 0.55) * 0.05 * idleWeight;

    // apply with damping
    const k = 1 - Math.exp(-18 * dt);
    this.legL.pivot.rotation.x = lerp(this.legL.pivot.rotation.x, legLX, k);
    this.legR.pivot.rotation.x = lerp(this.legR.pivot.rotation.x, legRX, k);
    this.legL.knee.rotation.x = lerp(this.legL.knee.rotation.x, kneeLX, k);
    this.legR.knee.rotation.x = lerp(this.legR.knee.rotation.x, kneeRX, k);
    this.armL.pivot.rotation.x = lerp(this.armL.pivot.rotation.x, armLX, k);
    this.armR.pivot.rotation.x = lerp(this.armR.pivot.rotation.x, armRX, k);
    this.armL.pivot.rotation.z = lerp(this.armL.pivot.rotation.z, armLZ, k);
    this.armR.pivot.rotation.z = lerp(this.armR.pivot.rotation.z, armRZ, k);
    this.headGroup.rotation.x = lerp(this.headGroup.rotation.x, headX, k);
    this.headGroup.rotation.y = lerp(this.headGroup.rotation.y, headY, k);
    this.body.rotation.y = lerp(this.body.rotation.y, torsoTwist, k);
    this.body.position.y = breath + (this.grounded && moving ? Math.abs(Math.sin(phase * 2)) * 0.03 : 0);

    // sword orientation
    if (this.sword.visible) {
      this.sword.rotation.x = lerp(this.sword.rotation.x, -1.5 + swordSwing, 0.35);
      this.sword.rotation.z = Math.sin(this.time * 24) * 0.02;
    }

    // scarf ribbons follow movement
    for (let i = 0; i < this.ribbons.length; i++) {
      const r = this.ribbons[i];
      const target = Math.sin(this.time * (4 + i * 0.6) + i) * 0.2 + clamp(this.speed * 0.04, 0, 0.45);
      r.rotation.x = damp(r.rotation.x, this.grounded ? target : target + 0.5, 5, dt);
      r.rotation.z = Math.sin(this.time * 3.2 + i * 0.8) * 0.12;
    }
    this.core.rotation.y += dt * 1.8;
    this.core.rotation.x += dt * 0.8;
    this.heroLight.intensity = 0.45 + Math.sin(this.time * 2.4) * 0.1;

    // contact shadow tracks ground under the player
    const gy = this._groundYUnder();
    this.contactShadow.position.set(this.position.x, gy + 0.025, this.position.z);
    const airHeight = this.position.y - gy;
    const shadowScale = clamp(1.25 - airHeight * 0.12, 0.35, 1.3);
    this.contactShadow.scale.setScalar(shadowScale * (1 + Math.sin(this.time * 2) * 0.02));
    this.contactShadow.material.opacity = clamp(0.36 - airHeight * 0.03, 0.04, 0.36);

    this._updateCompanion(dt, camera);
  }

  _groundYUnder() {
    // probe straight down through the collider set
    let best = -50;
    const x = this.position.x, z = this.position.z;
    for (const c of this.world.colliders) {
      if (!c.active) continue;
      if (x > c.box.min.x - this.radius * 0.6 && x < c.box.max.x + this.radius * 0.6 &&
          z > c.box.min.z - this.radius * 0.6 && z < c.box.max.z + this.radius * 0.6) {
        if (c.box.max.y <= this.position.y + 0.1 && c.box.max.y > best) best = c.box.max.y;
      }
    }
    return best;
  }

  _updateCompanion(dt, camera) {
    const p = this.pip;
    p.phase += dt;
    const side = this.facing + Math.PI * 0.6;
    const target = V3(
      this.position.x + Math.cos(side) * 1.25,
      this.position.y + 2.15 + Math.sin(p.phase * 1.7) * 0.16,
      this.position.z + Math.sin(side) * 1.25
    );
    p.pos.x = damp(p.pos.x, target.x, 3.4, dt);
    p.pos.y = damp(p.pos.y, target.y, 4.2, dt);
    p.pos.z = damp(p.pos.z, target.z, 3.4, dt);
    p.group.position.copy(p.pos);
    p.group.rotation.y += dt * 0.8;
    p.orb.position.y = Math.sin(p.phase * 2.3) * 0.04;
    p.ring.rotation.x = Math.PI / 2 + Math.sin(p.phase) * 0.4;
    p.ring.rotation.z += dt * 1.6;
    p.glow.material.opacity = 0.55 + Math.sin(p.phase * 3.1) * 0.15;
    if (Math.random() < dt * 2.5) {
      this.effects.pool.spawn({
        position: p.pos.clone(), count: 1, speed: 0.3, size: 0.09, life: 0.6, lifeVar: 0.5,
        gravity: 0.4, drag: 2, colors: [0xffe6a0, 0xffffff],
      });
    }
  }
}

