      buttons: new Array(20).fill(false),
      prev: new Array(20).fill(false),
      axes: [0, 0, 0, 0],
    };
    this.activeDevice = 'keyboard';
    this.onGamepad = null;

    this._mouse = { down: false, id: -1, lastX: 0, lastY: 0, startX: 0, startY: 0, dragged: false, locked: false };

    this._bindKeyboard();
    this._bindMouse();
