_buildComposer() {
  if (this.composer) {
    this.composer.dispose?.();
    this.composer = null;
  }
  const preset = QUALITY[this.qualityName] || QUALITY.high;
  this.composer = new EffectComposer(this.renderer);
  this.composer.setPixelRatio(this._effectivePixelRatio());
  this.composer.setSize(window.innerWidth, window.innerHeight);

  this.renderPass = new RenderPass(this.scene, this.camera);
  this.composer.addPass(this.renderPass);

  this.ssaoPass = null;
  if (preset.ssao) {
    try {
      this.ssaoPass = new SSAOPass(this.scene, this.camera, window.innerWidth, window.innerHeight);
      this.ssaoPass.kernelRadius = 1.4;
      this.ssaoPass.minDistance = 0.002;
      this.ssaoPass.maxDistance = 0.08;
      this.ssaoPass.output = SSAOPass.OUTPUT.Default;
      this.composer.addPass(this.ssaoPass);
    } catch (err) {
      console.warn('SSAO unavailable:', err);
      this.ssaoPass = null;
    }
  }

  this.bokehPass = null;
  if (preset.dof) {
    try {
      this.bokehPass = new BokehPass(this.scene, this.camera, { focus: 12, aperture: 0.00045, maxblur: 0.0055 });
      this.composer.addPass(this.bokehPass);
    } catch (err) {
      console.warn('DOF unavailable:', err);
      this.bokehPass = null;
    }
  }

  this.bloomPass = null;
  if (preset.bloom) {
    this.bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      preset.bloomStrength, preset.bloomRadius, preset.bloomThreshold
    );
    this.composer.addPass(this.bloomPass);
  }

  this.gradePass = new ShaderPass(GradeShader);
  this.composer.addPass(this.gradePass);

  this.outputPass = new OutputPass();
  this.composer.addPass(this.outputPass);

  if (preset.smaa) {
    this.smaaPass = new SMAAPass(window.innerWidth, window.innerHeight);
    this.composer.addPass(this.smaaPass);
  } else {
    this.smaaPass = null;
  }

  this.renderer.shadowMap.enabled = preset.shadow;
  this.sun.castShadow = preset.shadow;
  this.sun.shadow.mapSize.set(preset.shadowSize, preset.shadowSize);
  if (this.sun.shadow.map) {
    this.sun.shadow.map.dispose();
    this.sun.shadow.map = null;
  }
}

_effectivePixelRatio() {
  const preset = QUALITY[this.qualityName] || QUALITY.high;
  const dpr = Math.min(window.devicePixelRatio || 1, preset.maxPR);
  return clamp(dpr * this.renderScale * this.autoScale, 0.5, 2.2);
}

applyQuality(name, { silent = false, renderScale = this.renderScale } = {}) {
  if (!QUALITY[name]) name = 'high';
  this.qualityName = name;
  this.renderScale = renderScale;
  if (!silent) this._buildComposer();
  this._applyResolution();
  return QUALITY[name];
}

_applyResolution() {
  const pr = this._effectivePixelRatio();
  this.renderer.setPixelRatio(pr);
  this.renderer.setSize(window.innerWidth, window.innerHeight, false);
  if (this.composer) {
    this.composer.setPixelRatio(pr);
    this.composer.setSize(window.innerWidth, window.innerHeight);
  }
  if (this.smaaPass && this.smaaPass.setSize) this.smaaPass.setSize(window.innerWidth, window.innerHeight);
}

setRenderScale(scale, { rebuild = false } = {}) {
  this.renderScale = clamp(scale, 0.6, 1.5);
  if (rebuild) this._buildComposer();
  this._applyResolution();
}

setAutoScale(scale) {
  this.autoScale = clamp(scale, 0.6, 1.0);
  this._applyResolution();
}

_bindResize() {
  window.addEventListener('resize', () => {
    const w = window.innerWidth, h = window.innerHeight;
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(w, h, false);
    if (this.composer) this.composer.setSize(w, h);
    if (this.smaaPass && this.smaaPass.setSize) this.smaaPass.setSize(w, h);
    if (this.bokehPass) {
      this.bokehPass.uniforms.aspect.value = this.camera.aspect;
    }

_bindMouse() {
  const canvas = this.canvas;

  canvas.addEventListener('contextmenu', (e) => e.preventDefault());

  canvas.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'touch') return;
    this.activeDevice = e.pointerType === 'pen' ? 'pen' : 'mouse';
    if (e.button === 1) { e.preventDefault(); this.pressed.add('lock'); return; }
    if (e.button === 2) { e.preventDefault(); this.pressed.add('lock'); return; }
    if (e.button !== 0) return;
    this._mouse.down = true;
    this._mouse.id = e.pointerId;
    this._mouse.lastX = e.clientX;
    this._mouse.lastY = e.clientY;
    this._mouse.startX = e.clientX;
    this._mouse.startY = e.clientY;
    this._mouse.dragged = false;
    try { canvas.setPointerCapture(e.pointerId); } catch { /* ignore */ }

    if (document.pointerLockElement === canvas) {
      this.pressed.add('attack');
    }
  });

  window.addEventListener('pointermove', (e) => {
    if (e.pointerType === 'touch') return;
    if (document.pointerLockElement === canvas) {
      this._addLook(e.movementX, e.movementY);
      return;
    }
    if (!this._mouse.down || e.pointerId !== this._mouse.id) return;
    const dx = e.clientX - this._mouse.lastX;
    const dy = e.clientY - this._mouse.lastY;
    this._mouse.lastX = e.clientX;
    this._mouse.lastY = e.clientY;
    if (Math.hypot(e.clientX - this._mouse.startX, e.clientY - this._mouse.startY) > 5) this._mouse.dragged = true;
    if (this._mouse.dragged) this._addLook(dx, dy);
    this.activeDevice = 'mouse';
  });

  const endMouse = (e) => {
    if (e.pointerType === 'touch') return;
    if (!this._mouse.down) return;
    const wasDrag = this._mouse.dragged;
    this._mouse.down = false;
    this._mouse.dragged = false;
    if (!wasDrag && e.button === 0 && document.pointerLockElement !== canvas) {
      // A short click: capture the mouse for fluid camera control.
      this.pressed.add('attack');
      this.requestLock();
    }
  };
  window.addEventListener('pointerup', endMouse);
  window.addEventListener('pointercancel', () => { this._mouse.down = false; this._mouse.dragged = false; });

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    this.zoomDelta += clamp(e.deltaY * 0.0025, -1.5, 1.5);
  }, { passive: false });

  document.addEventListener('pointerlockchange', () => {
    this._mouse.locked = document.pointerLockElement === canvas;
  });
}

requestLock() {
  if (this.isTouchDevice) return;
  const el = this.canvas;
  if (document.pointerLockElement === el) return;
  if (el.requestPointerLock) {
    const p = el.requestPointerLock();
    if (p && p.catch) p.catch(() => {});
  }
}

exitLock() {
  if (document.pointerLockElement) document.exitPointerLock();
}

_addLook(dx, dy) {
  this.lookX += dx * 0.0026 * this.lookSensitivity;
  this.lookY += dy * 0.0026 * this.lookSensitivity * (this.invertY ? -1 : 1);
}

