  this.attackStage = clamp(stage, 0, 2);
  this.attacking = true;
  this.attackTimer = 0;
  this.attackHitDone = false;
  this.attackQueued = false;
  this.attackDuration = this.attackStage === 2 ? 0.52 : 0.4;
  this.attackHitTime = this.attackStage === 2 ? 0.2 : 0.15;
  this.comboTimer = 0.55;
